import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Stops withdrawals from group storage that would take any of what's held back from you: bounties you
 * haven't earned yet, and items kept for other members' requests. Withdraw options that only take from
 * what's left over stay, so anything more than the amount held is free for anyone.
 * <p>
 * Clicks can come faster than the game reports what's left, so withdrawals we've let through are
 * counted until the game catches up, and a click that would dip into what's held is stopped.
 */
@Singleton
public class BountyGuard
{
	/**
	 * Ticks a withdrawal we let through stays counted while the game hasn't reported it.
	 */
	private static final int PENDING_TICKS = 3;

	private final Client client;
	private final StorageHolds holds;
	private final HomebaseConfig config;

	/**
	 * Per item: how many we've let through that the game hasn't taken out of storage yet.
	 */
	private final Map<Integer, Integer> pending = new HashMap<>();

	/**
	 * Per item: how many group storage held at the game's last report.
	 */
	private Map<Integer, Integer> reported = new HashMap<>();

	/**
	 * When we last let a withdrawal through. One the game refuses, such as with a full inventory, never
	 * shows up, so withdrawals still counted a few ticks later are forgotten.
	 */
	private int lastWithdrawTick;

	@Inject
	private BountyGuard(Client client, StorageHolds holds, HomebaseConfig config)
	{
		this.client = client;
		this.holds = holds;
		this.config = config;
	}

	/**
	 * Forget withdrawals still being counted, when the plugin stops.
	 */
	public void reset()
	{
		pending.clear();
		reported = new HashMap<>();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.holdItems() || !isWithdraw(event.getActionParam1(), event.getOption()))
		{
			return;
		}
		MenuEntry entry = event.getMenuEntry();
		int itemId = itemId(event.getItemId(), entry.getWidget());
		if (itemId <= 0)
		{
			return;
		}
		StorageHolds.Hold hold = holds.holdFor(itemId);
		if (hold.getHeld() > 0 && !StorageHolds.allowed(event.getOption(), available(itemId), hold.getHeld()))
		{
			client.getMenu().removeMenuEntry(entry);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (!config.holdItems() || !isWithdraw(entry.getParam1(), entry.getOption()))
		{
			return;
		}
		int itemId = itemId(entry.getItemId(), entry.getWidget());
		if (itemId <= 0)
		{
			return;
		}
		StorageHolds.Hold hold = holds.holdFor(itemId);
		if (hold.getHeld() <= 0)
		{
			return;
		}
		int count = available(itemId);
		if (!StorageHolds.allowed(entry.getOption(), count, hold.getHeld()))
		{
			// the menu was built before an earlier withdrawal showed up
			event.consume();
			return;
		}
		pending.merge(itemId, StorageHolds.amount(entry.getOption(), count), Integer::sum);
		lastWithdrawTick = client.getTickCount();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!pending.isEmpty() && client.getTickCount() - lastWithdrawTick > PENDING_TICKS)
		{
			pending.clear();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV_GROUP_TEMP)
		{
			return;
		}
		Map<Integer, Integer> now = counts(event.getItemContainer());
		// withdrawals the game has now reported no longer need counting
		pending.replaceAll((itemId, amount) ->
		{
			int taken = Math.max(0, reported.getOrDefault(itemId, 0) - now.getOrDefault(itemId, 0));
			return Math.max(0, amount - taken);
		});
		pending.values().removeIf(amount -> amount == 0);
		reported = now;
	}

	/**
	 * @return how many of an item are in group storage once withdrawals still on their way are taken off
	 */
	private int available(int itemId)
	{
		ItemContainer storage = client.getItemContainer(InventoryID.INV_GROUP_TEMP);
		int count = storage == null ? 0 : storage.count(itemId);
		return Math.max(0, count - pending.getOrDefault(itemId, 0));
	}

	private static boolean isWithdraw(int param1, String option)
	{
		return param1 == InterfaceID.SharedBank.ITEMS && option != null && option.startsWith("Withdraw");
	}

	private static int itemId(int itemId, Widget widget)
	{
		return itemId > 0 || widget == null ? itemId : widget.getItemId();
	}

	private static Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0)
				{
					out.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return out;
	}
}

package com.homebase.bounties;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * A padlock on group storage items with a bounty or a request waiting on them: red while some of it is
 * held back from you, green while you can take it, with the reasons and what's free in a tooltip.
 */
@Singleton
public class BountyOverlay extends WidgetItemOverlay
{
	private static final Color LOCKED = new Color(0xEF5350);
	private static final Color OPEN = new Color(0x66BB6A);

	private final Client client;
	private final StorageHolds holds;
	private final TooltipManager tooltipManager;

	@Inject
	private BountyOverlay(Client client, StorageHolds holds, TooltipManager tooltipManager)
	{
		this.client = client;
		this.holds = holds;
		this.tooltipManager = tooltipManager;
		showOnInterfaces(InterfaceID.SHARED_BANK);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		StorageHolds.Hold hold = holds.holdFor(itemId);
		if (!hold.any())
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		// in the slot's top right corner, clear of the stack size
		drawPadlock(graphics, bounds.x + bounds.width - 9, bounds.y + 1, hold.getHeld() > 0 ? LOCKED : OPEN);

		Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
		{
			StringBuilder text = new StringBuilder(String.join("</br>", hold.getReasons()));
			if (hold.getHeld() > 0)
			{
				int free = StorageHolds.free(widgetItem.getQuantity(), hold.getHeld());
				text.append("</br>").append(free > 0 ? free + " free to take" : "None free to take");
			}
			tooltipManager.add(new Tooltip(text.toString()));
		}
	}

	private static void drawPadlock(Graphics2D g, int x, int y, Color color)
	{
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(1.5f));
		g.setColor(Color.BLACK);
		g.drawArc(x + 1, y, 6, 7, 0, 180);
		g.fillRect(x - 1, y + 3, 10, 8);
		g.setColor(color);
		g.drawArc(x + 2, y + 1, 4, 6, 0, 180);
		g.fillRect(x, y + 4, 8, 6);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
	}
}

package com.homebase.bounties;

import com.google.gson.Gson;
import com.homebase.collect.LocalCollector;
import com.homebase.data.BountyData;
import com.homebase.data.Checkable;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.data.Ids;
import com.homebase.goals.GoalService;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncEngine;
import com.homebase.sync.SyncRecord;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Bank bounties: items in group storage that some members can't take until they reach a goal. The
 * lock is soft, since all the plugin can do is hide the Withdraw options for locked members.
 */
@Slf4j
@Singleton
public class BountyService
{
	public static final String TYPE = "bounty";

	/**
	 * A bounty or request amount meaning the whole stack.
	 */
	public static final int ALL = Integer.MAX_VALUE;

	private static final int MAX_ITEM_NAME = 60;
	private static final int MAX_NAME = 20;

	@Value
	public static class Bounty
	{
		String id;
		BountyData data;
	}

	/**
	 * How an item in group storage stands for the logged in player.
	 */
	@Value
	public static class Lock
	{
		/**
		 * The goal that lifts it, such as "70 Attack".
		 */
		String goal;

		/**
		 * True if the player can't withdraw the item yet.
		 */
		boolean locked;

		/**
		 * How many are held back from the player while locked; {@link BountyService#ALL} for every one.
		 */
		int quantity;
	}

	private final LocalCollector collector;
	private final GoalService goals;
	private final GroupIndex groupIndex;
	private final Gson gson;

	private volatile SyncEngine engine;
	private volatile boolean dirty = true;
	private volatile Map<Integer, Lock> locks = Collections.emptyMap();

	@Inject
	private BountyService(LocalCollector collector, GoalService goals, GroupIndex groupIndex, Gson gson)
	{
		this.collector = collector;
		this.goals = goals;
		this.groupIndex = groupIndex;
		this.gson = gson;
	}

	public void setEngine(SyncEngine engine)
	{
		this.engine = engine;
		dirty = true;
	}

	/**
	 * Group data changed, which may lock or unlock items.
	 */
	public void invalidate()
	{
		dirty = true;
	}

	public List<Bounty> list()
	{
		SyncEngine engine = this.engine;
		List<Bounty> out = new ArrayList<>();
		if (engine == null)
		{
			return out;
		}
		String prefix = Keys.sharedPrefix(TYPE);
		for (SyncRecord record : engine.getStore().withPrefix(prefix))
		{
			BountyData data = decode(record);
			if (data != null)
			{
				out.add(new Bounty(record.getKey().substring(prefix.length()), data));
			}
		}
		out.sort(Comparator.comparingLong((Bounty b) -> b.getData().getCreatedAt()));
		return out;
	}

	public void create(int itemId, String itemName, int quantity, String goalId, List<String> locked)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		String myName = collector.getLocalName();
		if (engine == null || me == null || myName == null || itemId <= 0 || goalId == null || locked == null || locked.isEmpty())
		{
			return;
		}
		BountyData data = new BountyData();
		data.setItemId(itemId);
		data.setItemName(Clean.text(itemName, MAX_ITEM_NAME));
		data.setGoalId(goalId);
		data.setQuantity(Math.max(0, quantity));
		data.setLocked(new ArrayList<>(locked));
		data.setCreatedBy(me);
		data.setCreatedByName(myName);
		data.setCreatedAt(System.currentTimeMillis());
		String id = Ids.random();
		engine.publish(Keys.shared(TYPE, id), me, gson.toJsonTree(data));
	}

	public void delete(String id)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		if (engine != null && me != null)
		{
			engine.delete(Keys.shared(TYPE, id), me);
		}
	}

	/**
	 * Delete a goal's bounties along with it, since they're only ever listed under their goal.
	 */
	public void deleteForGoal(String goalId)
	{
		for (Bounty bounty : list())
		{
			if (goalId.equals(bounty.getData().getGoalId()))
			{
				delete(bounty.getId());
			}
		}
	}

	/**
	 * @return how the item stands for the logged in player, or null if there's no bounty on it.
	 * Cheap enough to call for every menu entry and every frame.
	 */
	public Lock lockFor(int itemId)
	{
		if (dirty)
		{
			dirty = false;
			locks = buildLocks();
		}
		return locks.get(itemId);
	}

	/**
	 * True if the bounty still holds for the member: they're on its list and haven't reached its goal.
	 */
	public boolean isLocked(BountyData bounty, String memberId)
	{
		if (bounty.getLocked() == null || !bounty.getLocked().contains(memberId))
		{
			return false;
		}
		GoalService.Goal goal = goals.get(bounty.getGoalId());
		// a deleted goal can never be reached, so its bounty no longer holds
		return goal != null && !goals.progress(goal.getData(), memberId).isDone();
	}

	private Map<Integer, Lock> buildLocks()
	{
		String me = collector.getMemberId();
		Map<Integer, Lock> out = new HashMap<>();
		for (Bounty bounty : list())
		{
			BountyData data = bounty.getData();
			if (!groupIndex.isMember(data.getCreatedBy()))
			{
				// only bounties set by someone in the group hold anything back
				continue;
			}
			GoalService.Goal goal = goals.get(data.getGoalId());
			if (goal == null)
			{
				// its goal has been deleted, or hasn't arrived yet, so it holds nothing back
				continue;
			}
			String title = GoalService.title(goal.getData());
			boolean locked = me != null && isLocked(data, me);
			int quantity = 0;
			if (locked)
			{
				quantity = data.getQuantity() > 0 ? data.getQuantity() : ALL;
			}
			Lock existing = out.get(data.getItemId());
			if (existing == null)
			{
				out.put(data.getItemId(), new Lock(title, locked, quantity));
			}
			else if (locked)
			{
				// several bounties on one item hold back their amounts together
				long total = (long) existing.getQuantity() + quantity;
				String goalTitle = existing.isLocked() ? existing.getGoal() : title;
				out.put(data.getItemId(), new Lock(goalTitle, true, (int) Math.min(ALL, total)));
			}
		}
		return out;
	}

	private BountyData decode(SyncRecord record)
	{
		if (record == null || record.getData() == null)
		{
			return null;
		}
		try
		{
			BountyData data = Checkable.checked(gson.fromJson(record.getData(), BountyData.class));
			if (data == null || data.getItemId() <= 0)
			{
				return null;
			}
			data.setItemName(Clean.text(data.getItemName(), MAX_ITEM_NAME));
			data.setCreatedByName(Clean.text(data.getCreatedByName(), MAX_NAME));
			return data;
		}
		catch (RuntimeException e)
		{
			log.debug("Unreadable bounty {}", record.getKey(), e);
			return null;
		}
	}
}

package com.homebase.bounties;

import com.homebase.requests.RequestService;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * How much of an item in group storage is held back from the logged in player: by bounties on it
 * that they haven't earned yet, and by other members' requests waiting to be collected. Only the
 * amount asked for is held; anything more in storage is free for anyone. Runs on the client thread.
 */
@Singleton
public class StorageHolds
{
	public static final int ALL = BountyService.ALL;

	@Value
	public static class Hold
	{
		/**
		 * How many are held back from the player: 0 for none, {@link StorageHolds#ALL} for every one.
		 */
		int held;

		/**
		 * One line per bounty or request on the item, for its padlock's tooltip.
		 */
		List<String> reasons;

		/**
		 * @return true if there's a bounty or request on the item, even one that holds nothing back
		 */
		public boolean any()
		{
			return !reasons.isEmpty();
		}
	}

	private final ItemManager itemManager;
	private final BountyService bounties;
	private final RequestService requests;

	@Inject
	private StorageHolds(ItemManager itemManager, BountyService bounties, RequestService requests)
	{
		this.itemManager = itemManager;
		this.bounties = bounties;
		this.requests = requests;
	}

	/**
	 * @return how much of the item is held back from the logged in player, and why
	 */
	public Hold holdFor(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		long held = 0;
		List<String> reasons = new ArrayList<>();

		BountyService.Lock lock = bounties.lockFor(canonical);
		if (lock == null)
		{
			lock = bounties.lockFor(itemId);
		}
		if (lock != null)
		{
			if (lock.isLocked())
			{
				held += lock.getQuantity();
				reasons.add("Bounty: " + (lock.getQuantity() == ALL ? "" : lock.getQuantity() + " ")
					+ "locked until you reach " + lock.getGoal());
			}
			else
			{
				reasons.add("Bounty: " + lock.getGoal() + " (you can take this)");
			}
		}

		List<RequestService.Reservation> reservations = requests.reservationsFor(canonical);
		if (reservations.isEmpty())
		{
			reservations = requests.reservationsFor(itemId);
		}
		for (RequestService.Reservation reservation : reservations)
		{
			if (requests.isMe(reservation.getRequestedBy()))
			{
				reasons.add(reservation.getQuantity() + " kept for you: your request");
			}
			else
			{
				held += reservation.getQuantity();
				reasons.add(reservation.getQuantity() + " kept for "
					+ (reservation.getRequestedByName() == null ? "someone" : reservation.getRequestedByName()) + "'s request");
			}
		}
		return new Hold((int) Math.min(ALL, held), reasons);
	}

	/**
	 * @return how many of a stack anyone may take while {@code held} of it are held back
	 */
	public static int free(int count, int held)
	{
		return held >= ALL ? 0 : Math.max(0, count - held);
	}

	/**
	 * @return how many of a stack of {@code count} this Withdraw option takes, or -1 for Withdraw-X,
	 * whose amount isn't known until it's typed
	 */
	public static int amount(String option, int count)
	{
		String text = Text.removeTags(option).trim().toLowerCase(Locale.ROOT);
		if (text.endsWith("-all-but-1"))
		{
			return Math.max(0, count - 1);
		}
		if (text.endsWith("-all"))
		{
			return count;
		}
		int dash = text.lastIndexOf('-');
		try
		{
			return Math.min(count, Integer.parseInt(text.substring(dash + 1)));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/**
	 * @return true if the Withdraw option may stay: it can't take any of what's held back
	 */
	public static boolean allowed(String option, int count, int held)
	{
		if (held <= 0)
		{
			return true;
		}
		int amount = amount(option, count);
		return amount >= 0 && amount <= free(count, held);
	}
}

