package com.homebase.data;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.UUID;

/**
 * Identifiers. Most are derived by hashing, so raw account hashes and the group passphrase are never sent
 * to other players or written into file names.
 */
public final class Ids
{
	/**
	 * How much of the hash to keep: 64 bits, written as 16 hex digits.
	 */
	private static final int ID_BYTES = 8;

	private Ids()
	{
	}

	public static String member(long accountHash)
	{
		return hash("homebase-member:" + accountHash);
	}

	public static String group(String passphrase)
	{
		return hash("homebase-group:" + passphrase);
	}

	/**
	 * @return a new id for something shared, such as a goal
	 */
	public static String random()
	{
		return UUID.randomUUID().toString().replace("-", "").substring(0, ID_BYTES * 2);
	}

	private static String hash(String input)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder(ID_BYTES * 2);
			for (int i = 0; i < ID_BYTES; i++)
			{
				sb.append(String.format("%02x", digest[i]));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import lombok.Data;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

@Data
public class ItemsData implements Checkable
{
	/**
	 * Two values per slot, for more slots than any bank has.
	 */
	private static final int MAX_VALUES = 2 * 2_000;

	/**
	 * Item id and quantity pairs in slot order, with -1 for empty slots, the same layout RuneLite's own
	 * party sync uses.
	 */
	private int[] items = new int[0];

	public static ItemsData of(ItemContainer container)
	{
		ItemsData data = new ItemsData();
		if (container == null)
		{
			return data;
		}
		Item[] slots = container.getItems();
		int[] packed = new int[slots.length * 2];
		for (int i = 0; i < slots.length; i++)
		{
			Item item = slots[i];
			boolean empty = item == null || item.getId() < 0 || item.getQuantity() <= 0;
			packed[i * 2] = empty ? -1 : item.getId();
			packed[i * 2 + 1] = empty ? 0 : item.getQuantity();
		}
		data.items = packed;
		return data;
	}

	/**
	 * @return the slots, with null for empty ones
	 */
	public List<Item> toItems()
	{
		List<Item> out = new ArrayList<>(items.length / 2);
		for (int i = 0; i + 1 < items.length; i += 2)
		{
			out.add(items[i] < 0 || items[i + 1] <= 0 ? null : new Item(items[i], items[i + 1]));
		}
		return out;
	}

	public boolean isEmpty()
	{
		for (int i = 0; i < items.length; i += 2)
		{
			if (items[i] >= 0)
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public void check()
	{
		if (items == null)
		{
			items = new int[0];
		}
		else if (items.length > MAX_VALUES)
		{
			items = Arrays.copyOf(items, MAX_VALUES);
		}
	}
}

package com.homebase.data;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import lombok.Data;

/**
 * Boss kill counts, from the "Your Vorkath kill count is: 12" messages the game sends, the collection
 * log's page headers and the hiscores.
 */
@Data
public class KillCountsData implements Checkable
{
	/**
	 * Most bosses kept, so a bad client can't flood everyone with junk.
	 */
	public static final int MAX_BOSSES = 200;

	/**
	 * Boss name to kill count.
	 */
	private Map<String, Integer> counts = new HashMap<>();

	/**
	 * @return the boss's kill count, or null if there's none
	 */
	public Integer countFor(String boss)
	{
		String name = existingName(boss);
		return name == null ? null : counts.get(name);
	}

	/**
	 * @return the name this boss is already kept under, or null if it isn't. The game's messages, the
	 * collection log and the hiscores don't always name a boss the same way ("Gauntlet" and
	 * "The Gauntlet", "Barrows" and "Barrows Chests"), so names are matched loosely.
	 */
	public String existingName(String boss)
	{
		if (boss == null)
		{
			return null;
		}
		if (counts.containsKey(boss))
		{
			return boss;
		}
		String key = bossKey(boss);
		for (String name : counts.keySet())
		{
			if (bossKey(name).equals(key))
			{
				return name;
			}
		}
		return null;
	}

	/**
	 * @return the boss name in lower case, without "The", punctuation, a closing "Chest" or "Chests",
	 * or a plural "s"
	 */
	static String bossKey(String name)
	{
		String key = name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9 ]", "").replaceAll("\\s+", " ").trim();
		if (key.startsWith("the "))
		{
			key = key.substring(4);
		}
		key = key.replaceAll(" chests?$", "");
		return key.endsWith("s") ? key.substring(0, key.length() - 1) : key;
	}

	@Override
	public void check()
	{
		counts = Checkable.counts(Checkable.map(counts, MAX_BOSSES), Integer.MAX_VALUE);
	}
}

package com.homebase.data;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The spot a member has pinned on the world map for the group. Each member has one pin at a time.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class PinData implements Checkable
{
	/**
	 * The largest number the game's coordinates can hold.
	 */
	private static final int MAX_COORD = 16_383;
	private static final int MAX_PLANE = 3;

	/**
	 * False once the member has taken the pin away.
	 */
	private boolean placed;

	private int x;
	private int y;
	private int plane;

	/**
	 * Colour as 0xRRGGBB.
	 */
	private int color;

	/**
	 * When it was placed, so old pins can stop showing.
	 */
	private long at;

	@Override
	public void check()
	{
		x = Math.max(0, Math.min(MAX_COORD, x));
		y = Math.max(0, Math.min(MAX_COORD, y));
		plane = Math.max(0, Math.min(MAX_PLANE, plane));
	}
}

