package com.homebase.data;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.Data;
import net.runelite.api.Quest;

@Data
public class QuestsData implements Checkable
{
	public static final String FINISHED = "F";
	public static final String STARTED = "S";

	/**
	 * Miniquests, which the game counts apart from quests. RuneLite's quest list doesn't say which
	 * are which.
	 */
	public static final Set<String> MINIQUESTS = new HashSet<>();

	static
	{
		for (Quest quest : new Quest[]{
			Quest.ALFRED_GRIMHANDS_BARCRAWL, Quest.BARBARIAN_TRAINING, Quest.BEAR_YOUR_SOUL,
			Quest.CURSE_OF_THE_EMPTY_LORD, Quest.DADDYS_HOME, Quest.THE_ENCHANTED_KEY, Quest.ENTER_THE_ABYSS,
			Quest.FAMILY_PEST, Quest.THE_FROZEN_DOOR, Quest.THE_GENERALS_SHADOW, Quest.HIS_FAITHFUL_SERVANTS,
			Quest.HOPESPEARS_WILL, Quest.IN_SEARCH_OF_KNOWLEDGE, Quest.INTO_THE_TOMBS, Quest.LAIR_OF_TARN_RAZORLOR,
			Quest.MAGE_ARENA_I, Quest.MAGE_ARENA_II, Quest.SKIPPY_AND_THE_MOGRES, Quest.VALE_TOTEMS})
		{
			MINIQUESTS.add(quest.getName());
		}
	}

	/**
	 * Quest name to {@link #FINISHED} or {@link #STARTED}. Quests not started are left out. Keyed by
	 * name rather than RuneLite's quest list so members on different RuneLite versions still agree.
	 */
	private Map<String, String> quests = new HashMap<>();

	/**
	 * @return how many quests, not counting miniquests, are in the given state
	 */
	public int count(String state)
	{
		return count(state, false);
	}

	/**
	 * @return how many miniquests are in the given state
	 */
	public int countMiniquests(String state)
	{
		return count(state, true);
	}

	public static boolean isMiniquest(String name)
	{
		return MINIQUESTS.contains(name);
	}

	private int count(String state, boolean miniquests)
	{
		int n = 0;
		for (Map.Entry<String, String> e : quests.entrySet())
		{
			if (state.equals(e.getValue()) && isMiniquest(e.getKey()) == miniquests)
			{
				n++;
			}
		}
		return n;
	}

	@Override
	public void check()
	{
		quests = Checkable.map(quests);
	}
}

package com.homebase.data;

import lombok.Data;

/**
 * A request for an item from the group, such as asking the group's best smith for a rune scimitar.
 */
@Data
public class RequestData implements Checkable
{
	private String item;
	private int quantity;
	private String note;

	/**
	 * Member id and name of whoever asked.
	 */
	private String requestedBy;
	private String requestedByName;

	/**
	 * Member id and name of whoever has taken it on, or null while nobody has.
	 */
	private String assignedTo;
	private String assignedToName;

	private boolean done;
	private long createdAt;

	/**
	 * The item the member who took the request on put into group storage, kept for the requester
	 * until they take it out; 0 while nothing has been put in.
	 */
	private int reservedItemId;

	/**
	 * How many of that item wait in group storage for the requester.
	 */
	private int reservedQuantity;

	/**
	 * How many the requester has received so far, out of group storage or by trade.
	 */
	private int delivered;

	/**
	 * @return how many were asked for, at least one
	 */
	public int asked()
	{
		return Math.max(1, quantity);
	}

	/**
	 * @return true while some of the item waits in group storage for the requester
	 */
	public boolean isReserved()
	{
		return reservedItemId > 0 && reservedQuantity > 0 && !done;
	}

	/**
	 * Some of the item went into group storage for the requester: keep it for them, up to what they
	 * still need. Anything more is free for anyone.
	 */
	public void keep(int itemId, int amount)
	{
		reservedItemId = itemId;
		reservedQuantity = Math.max(0, Math.min(asked() - delivered, reservedQuantity + amount));
	}

	/**
	 * The member who put the item in group storage took some of it back out, so that much is no longer
	 * waiting there.
	 */
	public void takeBack(int amount)
	{
		reservedQuantity = Math.max(0, reservedQuantity - amount);
	}

	/**
	 * The requester got some of the item, out of group storage or by trade. Once they have all they
	 * asked for, the request is done.
	 */
	public void receive(int amount, boolean fromStorage)
	{
		int got = fromStorage ? Math.min(amount, reservedQuantity) : amount;
		if (fromStorage)
		{
			reservedQuantity -= got;
		}
		delivered += Math.max(0, got);
		if (delivered >= asked())
		{
			done = true;
			reservedQuantity = 0;
		}
	}

	@Override
	public void check()
	{
		reservedQuantity = Math.max(0, reservedQuantity);
		delivered = Math.max(0, delivered);
	}
}

package com.homebase.data;

import com.homebase.sync.Keys;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The kinds of data each member shares. Each section is versioned on its own, so a member's bank from
 * this morning and their skills from a minute ago can both be the newest copy.
 */
@Getter
@RequiredArgsConstructor
public enum Section
{
	PROFILE("profile", false, 0),
	SKILLS("skills", false, 5_000),
	INVENTORY("inv", false, 3_000),
	EQUIPMENT("worn", false, 3_000),
	BANK("bank", false, 3_000),
	SEED_VAULT("seedvault", false, 3_000),
	LOOTING_BAG("lootingbag", false, 3_000),
	QUESTS("quests", false, 5_000),
	DIARIES("diaries", false, 2_000),
	TILES("tiles", false, 1_000),
	HIGHLIGHTS("npcs", false, 300),
	COMBAT_ACHIEVEMENTS("ca", false, 5_000),
	COLLECTION_LOG("clog", false, 3_000),
	KILL_COUNTS("kc", false, 3_000),
	HOUSE("poh", false, 5_000),
	FEED("feed", false, 1_000),
	PIN("pin", false, 500),
	GROUP_STORAGE("storage", true, 2_000),
	STORAGE_LOG("storagelog", false, 2_000);

	/**
	 * Part of the record key. Records are saved and sent under it, so it can't change.
	 */
	private final String key;

	/**
	 * True for data about the whole group, such as the shared group storage, rather than one member.
	 */
	private final boolean groupWide;

	/**
	 * Minimum gap between publishes, so a burst of changes goes out as one update.
	 */
	private final long minIntervalMs;

	public String keyFor(String memberId)
	{
		return groupWide ? Keys.group(key) : Keys.member(memberId, key);
	}
}

package com.homebase.data;

import java.util.HashMap;
import java.util.Map;
import lombok.Data;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

@Data
public class SkillsData implements Checkable
{
	/**
	 * Experience by {@link Skill} name. Stored by name rather than position so a skill added in a game
	 * update doesn't shift everyone else's numbers.
	 */
	private Map<String, Integer> xp = new HashMap<>();

	public int getXp(Skill skill)
	{
		Integer value = xp.get(skill.name());
		return value == null ? 0 : value;
	}

	/**
	 * @return the skill's real level, 1 to 99. RuneLite's own lookup goes on to virtual levels past 99,
	 * which would throw off total and combat levels.
	 */
	public int getLevel(Skill skill)
	{
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp(getXp(skill)));
	}

	public int getTotalLevel()
	{
		int total = 0;
		for (Skill skill : Skill.values())
		{
			total += getLevel(skill);
		}
		return total;
	}

	@Override
	public void check()
	{
		xp = Checkable.counts(xp, Experience.MAX_SKILL_XP);
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * What one member has put in and taken out of group storage, oldest first. Who did it isn't written
 * here: it's the member whose record this is, and only they can write it. Each member keeps their own
 * log, so two members saving while they can't reach each other can't overwrite one another's entries.
 */
@Data
public class StorageLogData implements Checkable
{
	/**
	 * Most entries one member keeps, with the oldest dropped first. An entry is 55 bytes at most, so a
	 * full log is under 6 KB before it's compressed.
	 */
	public static final int MAX_ENTRIES = 100;

	private List<Entry> entries = new ArrayList<>();

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Entry
	{
		private int item;

		/**
		 * How many: above 0 when put in, below 0 when taken out.
		 */
		private int amount;

		/**
		 * When the change was saved.
		 */
		private long at;
	}

	public void add(int item, int amount, long at)
	{
		entries.add(new Entry(item, amount, at));
		while (entries.size() > MAX_ENTRIES)
		{
			entries.remove(0);
		}
	}

	@Override
	public void check()
	{
		entries = Checkable.list(entries, MAX_ENTRIES);
		// Integer.MIN_VALUE has no positive amount to show
		entries.removeIf(e -> e.item <= 0 || e.amount == 0 || e.amount == Integer.MIN_VALUE || e.at <= 0);
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The tiles one member has marked for the group, and the colour they chose for them.
 */
@Data
public class TilesData implements Checkable
{
	/**
	 * Most tiles one member can mark, so a runaway client can't flood everyone else.
	 */
	public static final int MAX_TILES = 250;

	/**
	 * Colour as 0xRRGGBB.
	 */
	private int color;

	private List<Tile> tiles = new ArrayList<>();

	/**
	 * A marked tile. Tiles inside instances, such as raids, are stored at their location in the game's
	 * template map, so they line up for everyone who enters a copy of that instance.
	 */
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Tile
	{
		private int x;
		private int y;
		private int plane;
	}

	public boolean contains(int x, int y, int plane)
	{
		for (Tile tile : tiles)
		{
			if (tile.x == x && tile.y == y && tile.plane == plane)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Mark the tile, or unmark it if it's already marked.
	 *
	 * @return true if the tile is now marked
	 */
	public boolean toggle(int x, int y, int plane)
	{
		if (tiles.removeIf(t -> t.x == x && t.y == y && t.plane == plane))
		{
			return false;
		}
		if (tiles.size() >= MAX_TILES)
		{
			tiles.remove(0);
		}
		tiles.add(new Tile(x, y, plane));
		return true;
	}

	@Override
	public void check()
	{
		tiles = Checkable.list(tiles, MAX_TILES);
	}
}

