	private AreaNames()
	{
	}

	public static String describe(WorldPoint point)
	{
		return point == null ? null : describe(point.getX(), point.getY());
	}

	public static String describe(int x, int y)
	{
		Place closest = closest(x, y);
		if (closest != null && closest.distance(x, y) <= closest.radius)
		{
			return closest.name;
		}

		int wildy = wildernessLevel(x, y);
		if (wildy > 0)
		{
			return (isUnderground(y) ? "Wilderness dungeon" : "Wilderness") + " (level " + wildy + ")";
		}

		if (isUnderground(y))
		{
			String above = describe(x, y - UNDERGROUND_OFFSET);
			if (UNKNOWN.equals(above))
			{
				return "Underground";
			}
			return (above.startsWith("near ") ? above.substring(5) : above) + " (underground)";
		}

		if (closest != null && closest.distance(x, y) <= closest.radius + NEAR_DISTANCE)
		{
			return "near " + closest.name;
		}
		return UNKNOWN;
	}

	/**
	 * @return the Wilderness level at a point, or 0 outside the Wilderness
	 */
	private static int wildernessLevel(int x, int y)
	{
		int surfaceY = y >= WILDERNESS_SOUTH + UNDERGROUND_OFFSET ? y - UNDERGROUND_OFFSET : y;
		if (x < WILDERNESS_WEST || x >= WILDERNESS_EAST || surfaceY < WILDERNESS_SOUTH || surfaceY >= WILDERNESS_NORTH)
		{
			return 0;
		}
		return (surfaceY - WILDERNESS_SOUTH) / ROWS_PER_LEVEL + 1;
	}

	/**
	 * @return the spot on the surface above a point, or the point itself if it isn't in a dungeon
	 */
	public static WorldPoint aboveGround(WorldPoint point)
	{
		return isUnderground(point.getY()) ? new WorldPoint(point.getX(), point.getY() - UNDERGROUND_OFFSET, 0) : point;
	}

	/**
	 * @return true if a point is on the land of the main map, rather than in somewhere like a player-owned
	 * house or a raid, which are all further north. A few boss rooms are the exception.
	 */
	public static boolean isOnSurface(WorldPoint point)
	{
		return point.getY() < SURFACE_NORTH;
	}

	private static boolean isUnderground(int y)
	{
		return y >= UNDERGROUND_SOUTH && y < UNDERGROUND_NORTH;
	}

	private static Place closest(int x, int y)
	{
		Place best = null;
		Place smallestAround = null;
		int bestScore = Integer.MAX_VALUE;
		for (Place place : PLACES)
		{
			// compare by how far outside each place's radius the point is, so a small place next to a
			// big one still wins when you're standing in it
			int score = place.distance(x, y) - place.radius;
			if (score <= 0 && (smallestAround == null || place.radius < smallestAround.radius))
			{
				smallestAround = place;
			}
			if (score < bestScore)
			{
				bestScore = score;
				best = place;
			}
		}
		// a town on an island is named over the island it's on
		return smallestAround != null ? smallestAround : best;
	}
}

package com.homebase.map;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.overlay.GroupHudOverlay;
import com.homebase.party.Presence;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

/**
 * Click a member in the group HUD, or right-click the box and choose Find on map, to find them on the
 * world map. A plugin isn't allowed to open the map itself, so the choice is remembered and the map
 * goes to them when it's next opened.
 */
@Singleton
public class FindOnMap
{
	/**
	 * How long a click is remembered, so opening the map much later doesn't jump somewhere unexpected.
	 */
	static final long REMEMBER_MS = 60_000;

	private static final int MAX_NAME = 20;
	private static final int NO_BUTTON = -1;

	private final Client client;
	private final ClientThread clientThread;
	private final HomebaseConfig config;
	private final MouseManager mouseManager;
	private final PartyService partyService;
	private final Presence presence;
	private final GroupHudOverlay hud;
	private final GroupWorldMap groupWorldMap;

	private final MouseAdapter clicks = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			swallowedButton = NO_BUTTON;
			// Alt is how overlays are moved, so it's left alone
			if (!SwingUtilities.isLeftMouseButton(e) || e.isAltDown() || !config.hudClickToMap())
			{
				return e;
			}
			Long memberId = hud.memberAt(e.getPoint());
			if (memberId == null)
			{
				return e;
			}
			swallowedButton = e.getButton();
			e.consume();
			clientThread.invoke(() -> clicked(memberId));
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (e.getButton() == swallowedButton)
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			if (e.getButton() == swallowedButton)
			{
				swallowedButton = NO_BUTTON;
				e.consume();
			}
			return e;
		}
	};

	private Consumer<String> messages;

	/**
	 * The button of a press we kept from the game, so its release doesn't reach the game either.
	 */
	private volatile int swallowedButton = NO_BUTTON;
	private long wantedMember;
	private long wantedAt;
	private boolean wanted;

	@Inject
	private FindOnMap(Client client, ClientThread clientThread, HomebaseConfig config, MouseManager mouseManager,
		PartyService partyService, Presence presence, GroupHudOverlay hud, GroupWorldMap groupWorldMap)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.mouseManager = mouseManager;
		this.partyService = partyService;
		this.presence = presence;
		this.hud = hud;
		this.groupWorldMap = groupWorldMap;
	}

	/**
	 * @param messages shows a line in the chat box, called on the client thread
	 */
	public void start(Consumer<String> messages)
	{
		this.messages = messages;
		mouseManager.registerMouseListener(clicks);
	}

	public void stop()
	{
		mouseManager.unregisterMouseListener(clicks);
		wanted = false;
	}

	private void clicked(long memberId)
	{
		PartyMember member = partyService.getMemberById(memberId);
		String name = member == null ? null : Clean.text(member.getDisplayName(), MAX_NAME);
		if (name == null)
		{
			return;
		}
		if (presence.positionOf(member) == null)
		{
			wanted = false;
			messages.accept("Can't see where " + name + " is right now.");
			return;
		}
		wanted = true;
		wantedMember = memberId;
		wantedAt = System.currentTimeMillis();
		messages.accept("Open your world map to see where " + name + " is.");
	}

	/**
	 * Keeps the box's right-click menu up to date. It works even with a monster behind the box, where a
	 * left-click goes to the monster.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		hud.getMenuEntries().clear();
		if (!config.hudClickToMap())
		{
			return;
		}
		for (PartyMember member : hud.visibleMembers())
		{
			String name = Clean.text(member.getDisplayName(), MAX_NAME);
			long memberId = member.getMemberId();
			if (name != null)
			{
				hud.addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Find on map", name, entry -> clicked(memberId));
			}
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.WORLDMAP && wanted)
		{
			// the map centres on the player as it opens, so this waits for that to finish
			clientThread.invokeLater(this::goToMember);
		}
	}

	private void goToMember()
	{
		boolean due = isStillWanted(wanted, wantedAt, System.currentTimeMillis());
		wanted = false;
		PartyMember member = due ? partyService.getMemberById(wantedMember) : null;
		WorldPoint where = member == null ? null : presence.positionOf(member);
		WorldPoint point = where == null ? null : groupWorldMap.pointOnMap(wantedMember, where);
		WorldMap map = client.getWorldMap();
		if (point != null && map != null)
		{
			map.setWorldMapPositionTarget(point);
		}
	}

	static boolean isStillWanted(boolean wanted, long wantedAt, long now)
	{
		return wanted && now - wantedAt < REMEMBER_MS;
	}
}

package com.homebase.map;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.party.GroupSync;
import com.homebase.party.PartyMembers;
import com.homebase.party.Presence;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.api.worldmap.WorldMapData;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Online group members and everyone's pins on the world map, moved as new positions arrive.
 * <p>
 * RuneLite only draws a marker that's on the map being looked at, which on its own would make anyone in
 * a dungeon or an instance vanish. So someone in a dungeon is shown above it, and someone somewhere the
 * map doesn't cover, such as a player-owned house, stays where they were last on it. Only a viewer who
 * has a dungeon's own map open misses members on the surface, because that map has nowhere to put them.
 */
@Singleton
public class GroupWorldMap
{
	private static final int MAX_NAME = 20;

	/**
	 * Far more pictures than a group needs. This only stops them piling up as people change colour.
	 */
	private static final int MAX_KEPT_IMAGES = 256;

	/**
	 * Stands in for an angle in a picture's name, since a pin doesn't turn.
	 */
	private static final int NO_ANGLE = -1;

	private final Client client;
	private final WorldMapPointManager worldMapPointManager;
	private final PartyService partyService;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final HomebaseConfig config;
	private final Presence presence;

	/**
	 * Markers we added for members, by party member id.
	 */
	private final Map<Long, Marker> memberMarkers = new HashMap<>();

	/**
	 * Markers we added for pins, by the id of the member who placed them.
	 */
	private final Map<String, Marker> pinMarkers = new HashMap<>();

	/**
	 * The last place each member could be shown, by party member id.
	 */
	private final Map<Long, WorldPoint> lastOnMap = new HashMap<>();
	private final Map<String, BufferedImage> images = new HashMap<>();

	@Inject
	private GroupWorldMap(Client client, WorldMapPointManager worldMapPointManager, PartyService partyService, GroupSync groupSync,
		GroupIndex index, HomebaseConfig config, Presence presence)
	{
		this.client = client;
		this.worldMapPointManager = worldMapPointManager;
		this.partyService = partyService;
		this.groupSync = groupSync;
		this.index = index;
		this.config = config;
		this.presence = presence;
	}

	/**
	 * Move everyone's markers. Runs on the client thread, a couple of times a second.
	 */
	public void update()
	{
		if (!config.worldMap() || !groupSync.isGroupParty())
		{
			clear();
			return;
		}
		updateMembers();
		updatePins();
	}

	public void clear()
	{
		memberMarkers.values().forEach(worldMapPointManager::remove);
		memberMarkers.clear();
		pinMarkers.values().forEach(worldMapPointManager::remove);
		pinMarkers.clear();
		lastOnMap.clear();
	}

	private void updateMembers()
	{
		PartyMember local = partyService.getLocalMember();
		Set<Long> seen = new HashSet<>();
		for (PartyMember member : PartyMembers.current(partyService))
		{
			WorldPoint coord = presence.positionOf(member);
			String name = Clean.text(member.getDisplayName(), MAX_NAME);
			// the game already shows you on the map
			if (!presence.isOnline(member) || coord == null || name == null
				|| (local != null && local.getMemberId() == member.getMemberId()))
			{
				continue;
			}
			WorldPoint shown = pointOnMap(member.getMemberId(), coord);
			if (shown == null)
			{
				continue;
			}
			seen.add(member.getMemberId());
			Marker marker = memberMarkers.get(member.getMemberId());
			boolean isNew = marker == null;
			if (isNew)
			{
				marker = new Marker(shown, false);
				memberMarkers.put(member.getMemberId(), marker);
			}
			marker.show(shown, name, name, index.color(name), name + " - " + AreaNames.describe(coord));
			if (isNew)
			{
				worldMapPointManager.add(marker);
			}
		}

		for (Iterator<Map.Entry<Long, Marker>> it = memberMarkers.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Long, Marker> entry = it.next();
			if (!seen.contains(entry.getKey()))
			{
				worldMapPointManager.remove(entry.getValue());
				lastOnMap.remove(entry.getKey());
				it.remove();
			}
		}
	}

	private void updatePins()
	{
		Set<String> seen = new HashSet<>();
		long oldest = System.currentTimeMillis() - TimeUnit.HOURS.toMillis(config.mapPinHours());
		if (config.mapPins())
		{
			for (GroupIndex.Pin pin : index.pins())
			{
				if (pin.getAt() < oldest)
				{
					continue;
				}
				seen.add(pin.getMemberId());
				WorldPoint shown = pinOnMap(pin.getPoint());
				Marker marker = pinMarkers.get(pin.getMemberId());
				boolean isNew = marker == null;
				if (isNew)
				{
					marker = new Marker(shown, true);
					pinMarkers.put(pin.getMemberId(), marker);
				}
				String title = pin.getName() + "'s pin";
				marker.show(shown, title, pin.getName(), pin.getColor(), title + " - " + AreaNames.describe(pin.getPoint()));
				if (isNew)
				{
					worldMapPointManager.add(marker);
				}
			}
		}

		for (Iterator<Map.Entry<String, Marker>> it = pinMarkers.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<String, Marker> entry = it.next();
			if (!seen.contains(entry.getKey()))
			{
				worldMapPointManager.remove(entry.getValue());
				it.remove();
			}
		}
	}

	/**
	 * @return where to put a pin on the map being looked at: where it was placed, or above it if it was
	 * placed on a dungeon's own map and this is the surface
	 */
	private WorldPoint pinOnMap(WorldPoint point)
	{
		WorldMapData openMap = openMap();
		return openMap == null || openMap.surfaceContainsPosition(point.getX(), point.getY()) ? point : AreaNames.aboveGround(point);
	}

	/**
	 * @return where to put a member's marker on the map being looked at, or null if there's nowhere yet
	 */
	WorldPoint pointOnMap(long memberId, WorldPoint coord)
	{
		WorldPoint above = AreaNames.aboveGround(coord);
		WorldMapData openMap = openMap();
		WorldPoint point;
		if (openMap == null)
		{
			// nothing's drawn while the map is closed, so this only needs to remember roughly where they were
			point = AreaNames.isOnSurface(above) ? above : null;
		}
		else if (openMap.surfaceContainsPosition(coord.getX(), coord.getY()))
		{
			point = coord;
		}
		else
		{
			point = openMap.surfaceContainsPosition(above.getX(), above.getY()) ? above : null;
		}

		if (point == null)
		{
			return lastOnMap.get(memberId);
		}
		lastOnMap.put(memberId, point);
		return point;
	}

	/**
	 * @return the map being looked at, or null if the world map is closed
	 */
	private WorldMapData openMap()
	{
		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}
		WorldMap map = client.getWorldMap();
		return map == null ? null : map.getWorldMapData();
	}

	private BufferedImage image(boolean pin, String label, Color color, int angle, double scale)
	{
		if (images.size() >= MAX_KEPT_IMAGES)
		{
			images.clear();
		}
		String key = label + '|' + color.getRGB() + '|' + angle + '|' + scale + '|' + pin;
		return images.computeIfAbsent(key, k -> pin ? MapMarker.pin(label, color, scale) : MapMarker.arrow(label, color, angle, scale));
	}

	/**
	 * One marker. On the part of the map being looked at, its tip is on the spot it marks. When that's
	 * off the edge it waits at the edge instead, and a member's arrow points the way to go.
	 */
	private final class Marker extends WorldMapPoint
	{
		private final boolean pin;
		private String label;
		private Color color;

		private Marker(WorldPoint point, boolean pin)
		{
			super(point, null);
			this.pin = pin;
			setJumpOnClick(true);
		}

		/**
		 * @param title what RuneLite's Focus on menu option calls it
		 * @param name the name to show on it, if names are turned on
		 */
		private void show(WorldPoint point, String title, String name, Color color, String tooltip)
		{
			setWorldPoint(point);
			setName(title);
			setTooltip(tooltip);
			boolean keepAtEdge = config.mapEdge();
			setSnapToEdge(keepAtEdge);
			if (!keepAtEdge)
			{
				setCurrentlyEdgeSnapped(false);
			}
			label = config.mapNames() ? name : null;
			this.color = color;
			redraw();
		}

		@Override
		public void onEdgeSnap()
		{
			redraw();
		}

		@Override
		public void onEdgeUnsnap()
		{
			redraw();
		}

		private void redraw()
		{
			double scale = config.mapMarkerSize().getScale();
			if (isCurrentlyEdgeSnapped())
			{
				setImage(image(pin, label, color, pin ? NO_ANGLE : angleFromMapCentre(), scale));
				// RuneLite keeps a snapped picture on screen around its middle
				setImagePoint(null);
			}
			else
			{
				BufferedImage picture = image(pin, label, color, pin ? NO_ANGLE : MapMarker.DOWN, scale);
				setImage(picture);
				setImagePoint(MapMarker.tip(picture, scale));
			}
		}

		private int angleFromMapCentre()
		{
			WorldMap map = client.getWorldMap();
			Point centre = map == null ? null : map.getWorldMapPosition();
			WorldPoint point = getWorldPoint();
			return centre == null ? MapMarker.DOWN
				: MapMarker.angleBetween(centre.getX(), centre.getY(), point.getX(), point.getY());
		}
	}
}

package com.homebase.map;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;

/**
 * The pictures that mark things on the world map: an arrow for a group member and a pin for a spot
 * they've pointed out, each in the member's colour. Either can have a name above it, on a dark label so
 * it reads against any part of the map.
 */
final class MapMarker
{
	/**
	 * Angles are in degrees clockwise from north, which is up on the map.
	 */
	static final int DOWN = 180;
	private static final int ANGLE_STEP = 45;

	/**
	 * The arrow's outline, pointing up around its middle.
	 */
	private static final Polygon ARROW = new Polygon(
		new int[]{0, 9, 4, 4, -4, -4, -9},
		new int[]{-12, -1, -1, 12, 12, -1, -1}, 7);

	/**
	 * How far an arrow pointing down, or a pin, reaches below the middle of its box.
	 */
	private static final int TIP_DISTANCE = 12;

	/**
	 * A pin's round head and its point, and the hole in its head.
	 */
	private static final Shape PIN = pinShape();
	private static final Shape PIN_HOLE = new Ellipse2D.Double(-3, -8, 6, 6);

	/**
	 * The square a picture can turn inside, with room for its black edge.
	 */
	private static final int BOX = 28;
	private static final Stroke EDGE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private static final int LABEL_PADDING_X = 3;
	private static final int LABEL_PADDING_Y = 1;
	private static final int LABEL_CORNER = 4;
	private static final Color LABEL_BACKGROUND = new Color(0, 0, 0, 170);

	/**
	 * A name in a colour darker than this can't be read on the label, so it's written in white.
	 */
	private static final int MIN_TEXT_BRIGHTNESS = 90;

	private MapMarker()
	{
	}

	/**
	 * @param label the name to show above it, or null for none
	 * @param scale how much bigger or smaller than normal to draw it
	 */
	static BufferedImage arrow(String label, Color color, int angle, double scale)
	{
		BufferedImage image = canvas(label, color, scale);
		Graphics2D g = shapeGraphics(image, scale);
		g.rotate(Math.toRadians(angle));
		paint(g, ARROW, color);
		g.dispose();
		return image;
	}

	/**
	 * @param label the name to show above it, or null for none
	 * @param scale how much bigger or smaller than normal to draw it
	 */
	static BufferedImage pin(String label, Color color, double scale)
	{
		BufferedImage image = canvas(label, color, scale);
		Graphics2D g = shapeGraphics(image, scale);
		paint(g, PIN, color);
		g.setColor(Color.BLACK);
		g.fill(PIN_HOLE);
		g.dispose();
		return image;
	}

	/**
	 * @return where the tip of an arrow pointing {@link #DOWN}, or of a pin, is in its picture, which is
	 * the pixel to put on the spot it marks
	 */
	static Point tip(BufferedImage image, double scale)
	{
		return new Point(image.getWidth() / 2, (int) (image.getHeight() - boxSize(scale) / 2.0 + TIP_DISTANCE * scale));
	}

	/**
	 * @return the angle from one spot on the map to another, to the nearest eighth of a turn
	 */
	static int angleBetween(int fromX, int fromY, int toX, int toY)
	{
		// y grows going north on the game's map, so this is clockwise from north
		double degrees = Math.toDegrees(Math.atan2(toX - fromX, toY - fromY));
		return Math.floorMod((int) (Math.round(degrees / ANGLE_STEP) * ANGLE_STEP), 360);
	}

	private static Shape pinShape()
	{
		Area shape = new Area(new Ellipse2D.Double(-8, -13, 16, 16));
		shape.add(new Area(new Polygon(new int[]{-6, 6, 0}, new int[]{0, 0, TIP_DISTANCE}, 3)));
		return shape;
	}

	private static int boxSize(double scale)
	{
		return (int) Math.ceil(BOX * scale);
	}

	/**
	 * @return a picture sized to fit the box and the label, with the label already drawn on it
	 */
	private static BufferedImage canvas(String label, Color color, double scale)
	{
		int box = boxSize(scale);
		if (label == null)
		{
			return new BufferedImage(box, box, BufferedImage.TYPE_INT_ARGB);
		}

		Font font = FontManager.getRunescapeBoldFont();
		Graphics2D measuring = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		FontMetrics metrics = measuring.getFontMetrics(font);
		measuring.dispose();
		int labelWidth = metrics.stringWidth(label) + 2 * LABEL_PADDING_X;
		int labelHeight = metrics.getHeight() + 2 * LABEL_PADDING_Y;
		int width = Math.max(labelWidth, box);

		BufferedImage image = new BufferedImage(width, labelHeight + box, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		int labelX = (width - labelWidth) / 2;
		g.setColor(LABEL_BACKGROUND);
		g.fillRoundRect(labelX, 0, labelWidth, labelHeight, LABEL_CORNER, LABEL_CORNER);
		g.setFont(font);
		int textX = labelX + LABEL_PADDING_X;
		int textY = LABEL_PADDING_Y + metrics.getAscent();
		g.setColor(Color.BLACK);
		g.drawString(label, textX + 1, textY + 1);
		g.setColor(readableOnLabel(color));
		g.drawString(label, textX, textY);
		g.dispose();
		return image;
	}

	/**
	 * @return graphics for drawing a shape around the middle of the box at the bottom of the picture
	 */
	private static Graphics2D shapeGraphics(BufferedImage image, double scale)
	{
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.translate(image.getWidth() / 2.0, image.getHeight() - boxSize(scale) / 2.0);
		g.scale(scale, scale);
		return g;
	}

	private static void paint(Graphics2D g, Shape shape, Color color)
	{
		g.setColor(color);
		g.fill(shape);
		g.setColor(Color.BLACK);
		g.setStroke(EDGE);
		g.draw(shape);
	}

	private static Color readableOnLabel(Color color)
	{
		int brightness = (299 * color.getRed() + 587 * color.getGreen() + 114 * color.getBlue()) / 1000;
		return brightness < MIN_TEXT_BRIGHTNESS ? Color.WHITE : color;
	}
}

package com.homebase.map;

import com.google.gson.Gson;
import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.Checkable;
import com.homebase.data.GroupIndex;
import com.homebase.data.PinData;
import com.homebase.data.Section;
import com.homebase.party.GroupSync;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncRecord;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

/**
 * Right-click the world map and choose Pin for group, and everyone in the group sees a pin there in
 * your colour. Each member has one pin at a time, so placing another moves it.
 */
@Singleton
public class MapPins
{
	private static final String PIN = "Pin for group";
	private static final String UNPIN = "Remove your pin";
	private static final String MENU_TARGET = ColorUtil.wrapWithColorTag("Map", JagexColors.MENU_TARGET);

	/**
	 * A pin sent later than this after it was placed, as changing colour does, isn't news.
	 */
	private static final long NEW_PIN_MS = 10_000;

	private final Client client;
	private final HomebaseConfig config;
	private final LocalCollector collector;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final Gson gson;

	@Inject
	private MapPins(Client client, HomebaseConfig config, LocalCollector collector, GroupSync groupSync, GroupIndex index, Gson gson)
	{
		this.client = client;
		this.config = config;
		this.collector = collector;
		this.groupSync = groupSync;
		this.index = index;
		this.gson = gson;
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.worldMap() || !config.mapPins() || collector.getMemberId() == null || !groupSync.isGroupParty())
		{
			return;
		}
		Widget mapWidget = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		Point mouse = client.getMouseCanvasPosition();
		WorldMap map = client.getWorldMap();
		if (mapWidget == null || mapWidget.isHidden() || mouse == null || map == null
			|| !mapWidget.getBounds().contains(mouse.getX(), mouse.getY()))
		{
			return;
		}
		Point centre = map.getWorldMapPosition();
		if (centre == null)
		{
			return;
		}
		WorldPoint target = pointAt(mouse.getX(), mouse.getY(), mapWidget.getBounds(), map.getWorldMapZoom(), centre.getX(), centre.getY());

		if (hasPin())
		{
			client.getMenu().createMenuEntry(-1)
				.setOption(UNPIN)
				.setTarget(MENU_TARGET)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> remove());
		}
		client.getMenu().createMenuEntry(-1)
			.setOption(PIN)
			.setTarget(MENU_TARGET)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> place(target));
	}

	/**
	 * The reverse of how RuneLite places a marker on the map.
	 *
	 * @param map where the map is on screen
	 * @param zoom how many pixels wide a tile is
	 * @param centreX the tile in the middle of the map
	 * @param centreY the tile in the middle of the map
	 * @return the tile under a point on the map
	 */
	static WorldPoint pointAt(int mouseX, int mouseY, Rectangle map, float zoom, int centreX, int centreY)
	{
		int widthInTiles = (int) Math.ceil(map.getWidth() / zoom);
		int heightInTiles = (int) Math.ceil(map.getHeight() / zoom);
		int tilesAcross = (int) ((mouseX - map.getX()) / zoom);
		int tilesUp = (int) ((map.getY() + map.getHeight() - mouseY) / zoom);
		return new WorldPoint(centreX - widthInTiles / 2 + tilesAcross, centreY - heightInTiles / 2 - 1 + tilesUp, 0);
	}

	/**
	 * Share the player's new colour on their pin. Runs on the client thread.
	 */
	public void colorChanged()
	{
		PinData pin = mine();
		if (pin != null && pin.isPlaced())
		{
			pin.setColor(config.tileColor().getRGB() & 0xFFFFFF);
			collector.share(Section.PIN, pin);
		}
	}

	/**
	 * @return a line for the chat box when someone places a pin, or null if the record isn't one
	 */
	public String describeChange(SyncRecord record)
	{
		if (!Section.PIN.getKey().equals(Keys.sectionOf(record.getKey())) || record.isDeleted() || record.getData() == null)
		{
			return null;
		}
		String name = index.nameOf(Keys.memberOf(record.getKey()));
		PinData pin;
		try
		{
			pin = Checkable.checked(gson.fromJson(record.getData(), PinData.class));
		}
		catch (RuntimeException e)
		{
			return null;
		}
		if (name == null || pin == null || !pin.isPlaced() || !isNewPin(record.getVersion(), pin.getAt()))
		{
			return null;
		}
		String area = AreaNames.describe(pin.getX(), pin.getY());
		return name + " pinned a spot on the world map" + (AreaNames.UNKNOWN.equals(area) ? "." : ": " + area + ".");
	}

	/**
	 * Both times come from the clock of whoever placed the pin, so it doesn't matter if ours differs.
	 *
	 * @param sentAt when this copy of the pin was sent
	 * @param placedAt when the pin was placed
	 */
	static boolean isNewPin(long sentAt, long placedAt)
	{
		return sentAt - placedAt <= NEW_PIN_MS;
	}

	private boolean hasPin()
	{
		PinData pin = mine();
		return pin != null && pin.isPlaced();
	}

	private void place(WorldPoint point)
	{
		collector.share(Section.PIN, new PinData(true, point.getX(), point.getY(), point.getPlane(),
			config.tileColor().getRGB() & 0xFFFFFF, System.currentTimeMillis()));
	}

	private void remove()
	{
		PinData pin = mine();
		if (pin != null)
		{
			pin.setPlaced(false);
			collector.share(Section.PIN, pin);
		}
	}

	private PinData mine()
	{
		return collector.shared(Section.PIN, PinData.class);
	}
}

package com.homebase.overlay;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

/**
 * Bars side by side on one line of an overlay panel. RuneLite's own panel squashes a row of bars to
 * nothing, and sizes a new one a frame late, so this row lays itself out.
 */
class BarRow implements LayoutableRenderableEntity
{
	private final List<ProgressBarComponent> bars;
	private final int barWidth;
	private final int barHeight;
	private final int gap;

	/**
	 * Space above and below the bars, so they don't touch the lines around them.
	 */
	private final int top;
	private final int bottom;

	private final Rectangle bounds = new Rectangle();
	private Point location = new Point();

	BarRow(List<ProgressBarComponent> bars, int barWidth, int barHeight, int gap, int top, int bottom)
	{
		this.bars = bars;
		this.barWidth = barWidth;
		this.barHeight = barHeight;
		this.gap = gap;
		this.top = top;
		this.bottom = bottom;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int x = location.x;
		int tallest = 0;
		for (ProgressBarComponent bar : bars)
		{
			bar.setPreferredLocation(new Point(x, location.y + top));
			bar.setPreferredSize(new Dimension(barWidth, barHeight));
			tallest = Math.max(tallest, bar.render(graphics).height);
			x += barWidth + gap;
		}
		Dimension size = new Dimension(Math.max(0, x - gap - location.x), top + tallest + bottom);
		bounds.setLocation(location);
		bounds.setSize(size);
		return size;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point location)
	{
		this.location = location;
	}

	@Override
	public void setPreferredSize(Dimension size)
	{
		// the bars decide the row's size
	}
}

package com.homebase.overlay;

import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.GroupIndex;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * While the collection log is open, on a page or in search results, a dot on each item in the colour
 * of every other group member who has it, with their names when the mouse is over it. Only what's been
 * shared can be shown, so someone who hasn't opened the log and clicked Search yet may have more than
 * their dots say.
 */
@Singleton
public class CollectionLogOverlay extends Overlay
{
	private static final int DOT_SIZE = 6;
	private static final int DOT_GAP = 1;
	private static final Stroke DOT_EDGE = new BasicStroke(1f);

	private final Client client;
	private final HomebaseConfig config;
	private final GroupIndex index;
	private final LocalCollector collector;
	private final TooltipManager tooltipManager;

	@Inject
	private CollectionLogOverlay(Client client, HomebaseConfig config, GroupIndex index, LocalCollector collector, TooltipManager tooltipManager)
	{
		this.client = client;
		this.config = config;
		this.index = index;
		this.collector = collector;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget items = config.logOwners() ? itemList() : null;
		Widget[] children = items == null || items.isHidden() ? null : items.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}
		// items scrolled out of view still have positions, so keep the dots inside the visible area
		Rectangle visible = visibleArea(items);
		Point mouse = client.getMouseCanvasPosition();
		Shape clip = graphics.getClip();
		Object antialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setClip(visible);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		String me = collector.getMemberId();

		for (Widget child : children)
		{
			int itemId = child.getItemId();
			Rectangle bounds = child.getBounds();
			if (itemId <= 0 || child.isHidden() || !bounds.intersects(visible))
			{
				continue;
			}
			List<String> names = new ArrayList<>();
			int x = bounds.x + 1;
			for (GroupIndex.LogOwner owner : index.logOwners(itemId))
			{
				if (owner.getMemberId().equals(me))
				{
					continue;
				}
				drawDot(graphics, x, bounds.y + bounds.height - DOT_SIZE - 1, owner.getColor());
				x += DOT_SIZE + DOT_GAP;
				names.add(owner.getName());
			}
			boolean hovered = mouse != null && visible.contains(mouse.getX(), mouse.getY()) && bounds.contains(mouse.getX(), mouse.getY());
			if (hovered && !client.isMenuOpen() && (!names.isEmpty() || index.hasOtherMembers(me)))
			{
				tooltipManager.add(new Tooltip(names.isEmpty() ? "Nobody else in your group has shown this yet" : "Also has this: " + String.join(", ", names)));
			}
		}

		graphics.setClip(clip);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialiasing);
		return null;
	}

	/**
	 * @return the list of items on show: the results of a search, or else a page
	 */
	private Widget itemList()
	{
		Widget results = client.getWidget(InterfaceID.Collection.SEARCH_RESULTS);
		return results != null && !results.isHidden() ? results : client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
	}

	private Rectangle visibleArea(Widget items)
	{
		Widget search = client.getWidget(InterfaceID.Collection.SEARCH_CONTAINER);
		return search != null && !search.isHidden() ? items.getBounds().intersection(search.getBounds()) : items.getBounds();
	}

	private static void drawDot(Graphics2D g, int x, int y, Color color)
	{
		g.setColor(color);
		g.fillOval(x, y, DOT_SIZE, DOT_SIZE);
		g.setColor(Color.BLACK);
		g.setStroke(DOT_EDGE);
		g.drawOval(x, y, DOT_SIZE, DOT_SIZE);
	}
}

package com.homebase.overlay;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.map.AreaNames;
import com.homebase.party.GroupSync;
import com.homebase.party.PartyMembers;
import com.homebase.party.Presence;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * An on-screen box with each online group member's hitpoints, prayer, run energy and special attack as bars, their
 * combat level and where they are. Live numbers come from RuneLite's party; combat level comes from
 * shared skills.
 */
@Singleton
public class GroupHudOverlay extends OverlayPanel
{
	private static final Color AREA = new Color(0xBDBDBD);

	/**
	 * Bar colours, the same as the sidebar panel's (and RuneLite's Party panel's).
	 */
	private static final Color HP_FG = new Color(0, 146, 54, 230);
	private static final Color HP_BG = new Color(102, 15, 16, 230);
	private static final Color PRAY_FG = new Color(0, 149, 151);
	private static final Color PRAY_BG = Color.BLACK;
	private static final Color RUN_FG = new Color(0xC8A01E);
	private static final Color RUN_BG = new Color(0x3A3220);
	private static final Color SPEC_FG = new Color(0x8E5CC8);
	private static final Color SPEC_BG = new Color(0x2B2140);
	private static final int BAR_GAP = 3;

	/**
	 * How much wider the box gets when all four bars are showing, to keep their numbers readable.
	 */
	private static final int FOURTH_BAR_WIDTH = 30;

	private static final int MAX_NAME = 20;

	/**
	 * How bright a name has to be to read on the HUD's dark box, from 0 to 255.
	 */
	private static final double MIN_NAME_BRIGHTNESS = 130;

	/**
	 * How long since it was last drawn that the box still counts as being there for a click.
	 */
	private static final long MAX_DRAWN_AGE_MS = 250;

	private final Client client;
	private final HomebaseConfig config;
	private final PartyService partyService;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final Presence presence;

	/**
	 * Where each member starts in the box as last drawn, top first. The mouse is read on another thread.
	 */
	private volatile List<MemberStart> memberStarts = Collections.emptyList();
	private List<MemberStart> drawing = new ArrayList<>();

	/**
	 * Whether the mouse was over plain ground as last drawn. The HUD is drawn under interfaces and over
	 * the game, so otherwise a click on it could really be meant for the bank on top of it or a monster
	 * behind it.
	 */
	private volatile boolean mouseOverGround;

	/**
	 * RuneLite doesn't draw overlays at the login screen, and that doesn't reach render, so this says
	 * whether what's above is still true.
	 */
	private volatile long drawnAt;

	@Inject
	private GroupHudOverlay(Client client, HomebaseConfig config, PartyService partyService, GroupSync groupSync, GroupIndex index,
		Presence presence)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.groupSync = groupSync;
		this.index = index;
		this.presence = presence;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.hudEnabled() || client.getGameState() != GameState.LOGGED_IN || !groupSync.isGroupParty())
		{
			memberStarts = Collections.emptyList();
			return null;
		}
		mouseOverGround = isMouseOverGround();
		List<PartyMember> members = visibleMembers();
		if (members.isEmpty())
		{
			memberStarts = Collections.emptyList();
			return null;
		}

		HomebaseConfig.HudSize size = config.hudSize();
		Font font = fontFor(size);
		boolean compact = config.hudCompact();
		panelComponent.setPreferredSize(new Dimension(boxWidth(size), 0));

		drawing = new ArrayList<>();
		for (PartyMember member : members)
		{
			panelComponent.getChildren().add(new MemberStart(member.getMemberId()));
			if (compact)
			{
				addCompact(member, font, size);
			}
			else
			{
				addFull(member, font, size);
			}
		}
		Dimension drawn = super.render(graphics);
		memberStarts = drawing;
		drawnAt = System.currentTimeMillis();
		return drawn;
	}

	/**
	 * @return the member whose part of the box a point on the screen is in, or null if it isn't in the
	 * box or a click there is meant for something else
	 */
	public Long memberAt(Point point)
	{
		Rectangle box = getBounds();
		if (!mouseOverGround || box == null || !box.contains(point) || System.currentTimeMillis() - drawnAt > MAX_DRAWN_AGE_MS)
		{
			return null;
		}
		int y = point.y - box.y;
		Long found = null;
		for (MemberStart start : memberStarts)
		{
			if (start.y > y)
			{
				break;
			}
			found = start.memberId;
		}
		return found;
	}

	private boolean isMouseOverGround()
	{
		if (client.isMenuOpen())
		{
			return false;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		// the last entry is the one a left-click would choose, leaving out what overlays add for right-clicks
		for (int i = entries.length - 1; i >= 0; i--)
		{
			if (entries[i].getType() != MenuAction.RUNELITE_OVERLAY)
			{
				return entries[i].getType() == MenuAction.WALK;
			}
		}
		return false;
	}

	/**
	 * Takes up no room, and notes where in the box a member's lines begin.
	 */
	private final class MemberStart implements LayoutableRenderableEntity
	{
		private final long memberId;
		private final Rectangle bounds = new Rectangle();
		private int y;

		MemberStart(long memberId)
		{
			this.memberId = memberId;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			drawing.add(this);
			return new Dimension();
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			y = location.y;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
		}
	}

	public List<PartyMember> visibleMembers()
	{
		PartyMember local = partyService.getLocalMember();
		boolean includeSelf = config.hudIncludeSelf();
		boolean sameWorldOnly = config.hudSameWorld();
		List<PartyMember> out = new ArrayList<>();
		for (PartyMember member : PartyMembers.current(partyService))
		{
			// a name that is nothing once cleaned would leave the title with no text to draw
			if (!presence.isOnline(member) || Clean.text(member.getDisplayName(), MAX_NAME) == null)
			{
				continue;
			}
			boolean self = local != null && local.getMemberId() == member.getMemberId();
			if (!includeSelf && self)
			{
				continue;
			}
			if (sameWorldOnly && !self && index.world(member.getDisplayName()) != client.getWorld())
			{
				continue;
			}
			out.add(member);
		}
		Comparator<PartyMember> byName = Comparator.comparing(PartyMember::getDisplayName, String.CASE_INSENSITIVE_ORDER);
		out.sort(config.hudOrder() == HomebaseConfig.HudOrder.LOWEST_HITPOINTS
			? Comparator.comparingDouble(this::hitpointsLeft).thenComparing(byName)
			: byName);
		return out;
	}

	/**
	 * @return how much of a member's hitpoints they have left, from 0 to 1
	 */
	private double hitpointsLeft(PartyMember member)
	{
		PartyMember local = partyService.getLocalMember();
		boolean self = local != null && local.getMemberId() == member.getMemberId();
		int max = self ? client.getRealSkillLevel(Skill.HITPOINTS) : member.getStatBase(Skill.HITPOINTS);
		int hp = self ? client.getBoostedSkillLevel(Skill.HITPOINTS) : member.getStatBoost(Skill.HITPOINTS);
		return max <= 0 ? 1 : (double) hp / max;
	}

	private void addFull(PartyMember member, Font font, HomebaseConfig.HudSize size)
	{
		String name = Clean.text(member.getDisplayName(), MAX_NAME);
		int level = index.combatLevel(name);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(level > 0 && config.hudLevel() ? name + "  (level " + level + ")" : name)
			.color(readable(index.color(name)))
			.build());
		addBars(member, size);
		WorldPoint coord = presence.positionOf(member);
		if (config.hudPosition() && coord != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Area")
				.leftFont(font)
				.right(AreaNames.describe(coord))
				.rightColor(AREA)
				.rightFont(font)
				.build());
		}
	}

	private void addCompact(PartyMember member, Font font, HomebaseConfig.HudSize size)
	{
		String name = Clean.text(member.getDisplayName(), MAX_NAME);
		int level = index.combatLevel(name);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(level > 0 && config.hudLevel() ? name + " (" + level + ")" : name)
			.leftColor(readable(index.color(name)))
			.leftFont(font)
			.build());
		addBars(member, size);
	}

	/**
	 * Whichever of hitpoints, prayer, run energy and special attack are turned on, as bars side by side.
	 */
	private void addBars(PartyMember member, HomebaseConfig.HudSize size)
	{
		// our own numbers come straight from the game, since the party only sends them once they change
		PartyMember local = partyService.getLocalMember();
		boolean self = local != null && local.getMemberId() == member.getMemberId();

		List<ProgressBarComponent> bars = new ArrayList<>();
		int maxHp = self ? client.getRealSkillLevel(Skill.HITPOINTS) : member.getStatBase(Skill.HITPOINTS);
		if (config.hudHitpoints() && maxHp > 0)
		{
			int hp = self ? client.getBoostedSkillLevel(Skill.HITPOINTS) : member.getStatBoost(Skill.HITPOINTS);
			bars.add(bar(hp, maxHp, hp + "/" + maxHp, HP_FG, HP_BG));
		}
		int maxPrayer = self ? client.getRealSkillLevel(Skill.PRAYER) : member.getStatBase(Skill.PRAYER);
		if (config.hudPrayer() && maxPrayer > 0)
		{
			int prayer = self ? client.getBoostedSkillLevel(Skill.PRAYER) : member.getStatBoost(Skill.PRAYER);
			bars.add(bar(prayer, maxPrayer, prayer + "/" + maxPrayer, PRAY_FG, PRAY_BG));
		}
		if (config.hudRunEnergy())
		{
			// the game counts run energy in hundredths of a percent
			int run = self ? client.getEnergy() / 100 : member.getRunEnergy();
			bars.add(bar(run, 100, run + "%", RUN_FG, RUN_BG));
		}
		if (config.hudSpecEnergy() && (self || presence.knowsSpec(member.getMemberId())))
		{
			// the game counts special attack energy in tenths of a percent
			int spec = self ? client.getVarpValue(VarPlayerID.SA_ENERGY) / 10 : member.getSpecEnergy();
			bars.add(bar(spec, 100, spec + "%", SPEC_FG, SPEC_BG));
		}
		if (bars.isEmpty())
		{
			return;
		}
		int width = boxWidth(size) - 2 * ComponentConstants.STANDARD_BORDER;
		int each = (width - BAR_GAP * (bars.size() - 1)) / bars.size();
		panelComponent.getChildren().add(new BarRow(bars, each, barHeight(size), BAR_GAP, 1, 3));
	}

	private static ProgressBarComponent bar(int value, int max, String label, Color fg, Color bg)
	{
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMinimum(0);
		bar.setMaximum(Math.max(1, max));
		bar.setValue(Math.max(0, Math.min(value, max)));
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
		bar.setCenterLabel(label);
		bar.setForegroundColor(fg);
		bar.setBackgroundColor(bg);
		bar.setFontColor(Color.WHITE);
		return bar;
	}

	/**
	 * @return the colour, lightened just enough to read if a player has chosen a dark one
	 */
	static Color readable(Color color)
	{
		double brightness = 0.299 * color.getRed() + 0.587 * color.getGreen() + 0.114 * color.getBlue();
		if (brightness >= MIN_NAME_BRIGHTNESS)
		{
			return color;
		}
		double toWhite = (MIN_NAME_BRIGHTNESS - brightness) / (255 - brightness);
		return new Color(lighten(color.getRed(), toWhite), lighten(color.getGreen(), toWhite), lighten(color.getBlue(), toWhite));
	}

	private static int lighten(int channel, double toWhite)
	{
		return (int) Math.round(channel + (255 - channel) * toWhite);
	}

	private static int barHeight(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return 12;
			case LARGE:
				return 18;
			default:
				return 15;
		}
	}

	private static Font fontFor(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return FontManager.getRunescapeSmallFont();
			case LARGE:
				return FontManager.getRunescapeBoldFont();
			default:
				return FontManager.getRunescapeFont();
		}
	}

	private int boxWidth(HomebaseConfig.HudSize size)
	{
		boolean allFourBars = config.hudHitpoints() && config.hudPrayer() && config.hudRunEnergy() && config.hudSpecEnergy();
		return widthFor(size) + (allFourBars ? FOURTH_BAR_WIDTH : 0);
	}

	private static int widthFor(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return 130;
			case LARGE:
				return 190;
			default:
				return 155;
		}
	}
}

package com.homebase.overlay;

import com.homebase.HomebaseConfig;
import com.homebase.data.GroupIndex;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws every tile the group has marked, each in the colour of whoever marked it.
 */
@Singleton
public class GroupTileOverlay extends Overlay
{
	private static final Stroke STROKE = new BasicStroke(2f);
	private static final int FILL_ALPHA = 40;

	private final Client client;
	private final HomebaseConfig config;
	private final GroupIndex index;

	@Inject
	private GroupTileOverlay(Client client, HomebaseConfig config, GroupIndex index)
	{
		this.client = client;
		this.config = config;
		this.index = index;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.groupTiles() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return null;
		}
		int plane = view.getPlane();
		boolean names = config.tileNames();
		for (GroupIndex.MarkedTile tile : index.tiles())
		{
			// in an instance one template tile can appear in several places, or none
			for (WorldPoint point : WorldPoint.toLocalInstance(view, tile.getPoint()))
			{
				if (point.getPlane() != plane)
				{
					continue;
				}
				LocalPoint local = LocalPoint.fromWorld(view, point);
				if (local == null)
				{
					continue;
				}
				Polygon poly = Perspective.getCanvasTilePoly(client, local);
				if (poly == null)
				{
					continue;
				}
				Color color = tile.getColor();
				OverlayUtil.renderPolygon(graphics, poly, color, new Color(color.getRed(), color.getGreen(), color.getBlue(), FILL_ALPHA), STROKE);
				if (names)
				{
					Point text = Perspective.getCanvasTextLocation(client, graphics, local, tile.getName(), 0);
					if (text != null)
					{
						OverlayUtil.renderTextLocation(graphics, text, tile.getName(), color);
					}
				}
			}
		}
		return null;
	}
}

package com.homebase.party;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.homebase.sync.SyncEngine;
import com.homebase.sync.SyncRecord;
import com.homebase.sync.WireCodec;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.PartyData;
import net.runelite.client.util.Text;

/**
 * Moves group data over RuneLite's party service, so nobody has to host a server.
 * <p>
 * The group passphrase is used as the party passphrase. When anyone joins, everyone online sends a
 * summary of what they hold and fills in whatever the others are missing.
 * <p>
 * The party is only ever joined when the player presses Connect: RuneLite doesn't let plugins join
 * parties by themselves. A Group Ironman group's party is named after the group, which anyone can look
 * up, so nothing is shared while anyone in the party is missing from the group's member list as the
 * game reports it, and nothing they send is used.
 */
@Slf4j
@Singleton
public class GroupSync
{
	public enum Status
	{
		/**
		 * No group yet.
		 */
		NO_GROUP,
		/**
		 * A Group Ironman group: log in on an account in it to connect.
		 */
		LOG_IN,
		/**
		 * Logged in on an account that isn't in the Group Ironman group, so it can't connect.
		 */
		NOT_IN_GROUP,
		/**
		 * Ready to connect.
		 */
		DISCONNECTED,
		/**
		 * In someone else's party, so syncing is paused.
		 */
		OTHER_PARTY,
		/**
		 * In the group's party, but someone there hasn't said who they are yet, so nothing is shared
		 * until they do. It's most likely a connection that has already closed.
		 */
		CONNECTING,
		/**
		 * In the group's party, but someone in it isn't in the group, so nothing is shared.
		 */
		PAUSED,
		CONNECTED,
	}

	/**
	 * How long at the login screen before leaving the group's party, as RuneLite's Party plugin does.
	 */
	static final long IDLE_LEAVE_MS = 30 * 60_000L;

	/**
	 * How long a nameless party member may stay silent before they're taken to be a closed connection.
	 * RuneLite's party server keeps listing a connection for a few minutes after it closes, and anyone
	 * who joins after that sees it with no name. Anyone actually there answers a newcomer within a few
	 * seconds, and a nameless member who says anything counts as a stranger until they've been quiet this long.
	 */
	static final long SILENT_CONNECTION_MS = 10_000;

	/**
	 * How long after logging out a member of a Group Ironman group goes on sending what was waiting.
	 */
	static final long LOGOUT_SEND_MS = 10_000;

	/**
	 * The name RuneLite gives a party member until theirs arrives.
	 */
	private static final String NO_NAME = "<unknown>";

	/**
	 * Ticks after logging in to wait for the game to say which group the account is in.
	 */
	private static final int ROSTER_WAIT_TICKS = 10;

	static final int PROTOCOL = 1;

	/**
	 * Rough cap on the uncompressed size of one batch of records.
	 */
	private static final int RECORD_BUDGET = 48_000;

	/**
	 * Rough allowance for a record's version, author and JSON punctuation when estimating its size.
	 */
	private static final int RECORD_OVERHEAD = 64;
	private static final long SUMMARY_INTERVAL_MS = 3_000;

	/**
	 * Most records one message may carry. Ours stay well under this, since each batch is kept small.
	 */
	private static final int MAX_RECORDS_PER_MESSAGE = 2_000;

	private final Client client;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final ClientThread clientThread;
	private final Gson gson;
	private final Presence presence;

	private final List<Runnable> statusListeners = new CopyOnWriteArrayList<>();

	private volatile String passphrase;
	private volatile SyncEngine engine;
	private volatile boolean summaryWanted;
	private long lastSummaryAt;

	/**
	 * The Group Ironman group's name, or null for a passphrase group.
	 */
	private volatile String gimGroup;

	/**
	 * The group's members as the game last reported them, and whether the account logged in now is in
	 * the group. Read on the client thread, used from any thread.
	 */
	private volatile Set<String> roster = Collections.emptySet();
	private volatile boolean localInGroup;

	/**
	 * When the player logged out while connected, or 0 while playing or not connected.
	 */
	private long loginScreenSince;

	/**
	 * When each party member was last heard from, by any message, and when each was first listed.
	 */
	private final Map<Long, Long> heardAt = new ConcurrentHashMap<>();
	private final Map<Long, Long> listedAt = new ConcurrentHashMap<>();

	/**
	 * Whether we were sharing at the last flush, so a change can be shown straight away.
	 */
	private boolean wasSharing;

	/**
	 * Whether the game has had time to say which group this account is in since logging in.
	 */
	private volatile boolean rosterChecked;
	private int loggedInTicks;

	@Inject
	private GroupSync(Client client, PartyService partyService, WSClient wsClient, ClientThread clientThread, Gson gson,
		Presence presence)
	{
		this.client = client;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.clientThread = clientThread;
		this.gson = gson;
		this.presence = presence;
	}

	public void start()
	{
		wsClient.registerMessage(HomebaseSyncMessage.class);
		presence.setTrusted(this::isTrusted);
	}

	public void stop()
	{
		wsClient.unregisterMessage(HomebaseSyncMessage.class);
		passphrase = null;
		engine = null;
		statusListeners.clear();
	}

	public void addStatusListener(Runnable listener)
	{
		statusListeners.add(listener);
	}

	/**
	 * Switch to a group. Pass nulls when no passphrase is set.
	 *
	 * @param gimGroup the Group Ironman group's name, or null for a passphrase group
	 */
	public void setGroup(String passphrase, SyncEngine engine, String gimGroup)
	{
		this.passphrase = Strings.emptyToNull(passphrase);
		this.engine = engine;
		if (!Objects.equals(this.gimGroup, gimGroup))
		{
			this.gimGroup = gimGroup;
			roster = Collections.emptySet();
			localInGroup = false;
		}
		summaryWanted = isGroupParty();
		notifyStatus();
	}

	public Status getStatus()
	{
		if (passphrase == null)
		{
			return Status.NO_GROUP;
		}
		if (isGroupParty())
		{
			if (isOnOtherAccount())
			{
				return Status.NOT_IN_GROUP;
			}
			if (isShareSafe())
			{
				return Status.CONNECTED;
			}
			return isWaitingOnSilentMembers() ? Status.CONNECTING : Status.PAUSED;
		}
		if (partyService.isInParty())
		{
			return Status.OTHER_PARTY;
		}
		if (gimGroup != null && !localInGroup)
		{
			return client.getGameState() == GameState.LOGGED_IN && rosterChecked ? Status.NOT_IN_GROUP : Status.LOG_IN;
		}
		return Status.DISCONNECTED;
	}

	/**
	 * @return true if it's safe to share: a passphrase group, whose members all know the passphrase, or
	 * a Group Ironman group whose party holds only its members
	 */
	public boolean isShareSafe()
	{
		return gimGroup == null || strangers().isEmpty();
	}

	/**
	 * @return true if the game has shown this account is in the group. It can't at the login screen, or
	 * for a moment after logging in, until the member list arrives.
	 */
	public boolean isVerifiedAccount()
	{
		return gimGroup == null || localInGroup;
	}

	/**
	 * @return true if we may send the group anything
	 */
	public boolean isSharing()
	{
		return isGroupParty() && isShareSafe() && isVerifiedAccount();
	}

	/**
	 * A member at the login screen has no name for anyone who joins after them, and anyone nameless who
	 * says something stops sharing for whoever hears it. So once logged out, this only finishes sending
	 * what was waiting, then goes quiet, and whoever joins next takes it for a closed connection. Nothing
	 * is lost: what's left goes out at the next login. An alt on the same client says nothing at all, or
	 * it would look like a stranger to everyone else.
	 */
	static boolean isFinishingAfterLogout(GameState state, long sinceLogout)
	{
		return state == GameState.LOGIN_SCREEN && sinceLogout < LOGOUT_SEND_MS;
	}

	private boolean isOnOtherAccount()
	{
		return gimGroup != null && !localInGroup && rosterChecked && client.getGameState() == GameState.LOGGED_IN;
	}

	/**
	 * @return anyone in the group's party who isn't on the Group Ironman group's member list, by name
	 * ("someone" for a member whose name hasn't arrived yet); always empty for a passphrase group
	 */
	public List<String> strangers()
	{
		List<String> out = new ArrayList<>();
		for (PartyMember member : unverifiedMembers())
		{
			out.add(hasName(member) ? member.getDisplayName() : "someone");
		}
		return out;
	}

	/**
	 * @return true if everyone holding up sharing has no name and hasn't said anything yet
	 */
	private boolean isWaitingOnSilentMembers()
	{
		for (PartyMember member : unverifiedMembers())
		{
			boolean heardLately = System.currentTimeMillis() - heardAt.getOrDefault(member.getMemberId(), 0L) < SILENT_CONNECTION_MS;
			if (!isSilent(hasName(member), heardLately))
			{
				return false;
			}
		}
		return true;
	}

	private List<PartyMember> unverifiedMembers()
	{
		List<PartyMember> out = new ArrayList<>();
		if (gimGroup == null || !isGroupParty())
		{
			return out;
		}
		long now = System.currentTimeMillis();
		PartyMember local = partyService.getLocalMember();
		for (PartyMember member : partyService.getMembers())
		{
			if (local != null && local.getMemberId() == member.getMemberId())
			{
				continue;
			}
			boolean named = hasName(member);
			long lastSign = Math.max(listedAt.getOrDefault(member.getMemberId(), now), heardAt.getOrDefault(member.getMemberId(), 0L));
			boolean closed = isClosedConnection(named, lastSign, now);
			if (!isVerified(member) && !closed)
			{
				out.add(member);
			}
		}
		return out;
	}

	/**
	 * @param lastSign when they were listed or last heard from, whichever came later
	 * @return true if a party member is most likely a connection that has already closed, or a member at
	 * the login screen, who has no name for anyone who joined after them: they have no name, and haven't
	 * said anything for a while
	 */
	static boolean isClosedConnection(boolean named, long lastSign, long now)
	{
		return !named && now - lastSign >= SILENT_CONNECTION_MS;
	}

	static boolean isSilent(boolean named, boolean heard)
	{
		return !named && !heard;
	}

	private static boolean hasName(PartyMember member)
	{
		String name = member.getDisplayName();
		return !Strings.isNullOrEmpty(name) && !NO_NAME.equals(name);
	}

	/**
	 * @return true if this party member's messages can be used: anyone in a passphrase group, or a
	 * member of the Group Ironman group
	 */
	public boolean isTrusted(long memberId)
	{
		if (gimGroup == null)
		{
			return true;
		}
		PartyMember member = partyService.getMemberById(memberId);
		return member != null && isVerified(member);
	}

	private boolean isVerified(PartyMember member)
	{
		return hasName(member) && roster.contains(rosterKey(member.getDisplayName()));
	}

	/**
	 * Read the group's member list from the game. Runs on the client thread every tick.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		String group = gimGroup;
		if (group == null)
		{
			return;
		}
		ClanSettings settings = client.getClanSettings(ClanID.GROUP_IRONMAN);
		// the list can go missing for a moment, such as when hopping worlds, which doesn't mean we've left
		boolean inGroup = settings == null ? localInGroup : settings.getName() != null
			&& rosterKey(settings.getName()).equals(rosterKey(group));
		if (inGroup && settings != null)
		{
			Set<String> names = new HashSet<>();
			for (ClanMember member : settings.getMembers())
			{
				if (member != null && member.getName() != null)
				{
					names.add(rosterKey(member.getName()));
				}
			}
			if (!names.equals(roster))
			{
				roster = names;
				notifyStatus();
			}
		}
		boolean checked = settings != null || ++loggedInTicks > ROSTER_WAIT_TICKS;
		if (inGroup != localInGroup || checked != rosterChecked)
		{
			localInGroup = inGroup;
			rosterChecked = checked;
			notifyStatus();
		}
	}

	static String rosterKey(String name)
	{
		return Text.toJagexName(name).toLowerCase(Locale.ROOT);
	}

	public boolean isGroupParty()
	{
		String passphrase = this.passphrase;
		return passphrase != null && passphrase.equals(partyService.getPartyPassphrase());
	}

	/**
	 * @return true if Connect can be pressed now: not already connected, and for a Group Ironman group,
	 * logged in on an account in it
	 */
	public boolean canConnect()
	{
		return passphrase != null && !isGroupParty() && (gimGroup == null || localInGroup);
	}

	/**
	 * Join the group's party. Only ever called when the player presses Connect.
	 */
	public void joinGroupParty()
	{
		String passphrase = this.passphrase;
		if (passphrase != null && canConnect())
		{
			loginScreenSince = 0;
			clientThread.invokeLater(() -> partyService.changeParty(passphrase));
		}
	}

	public void leaveGroupParty()
	{
		if (isGroupParty())
		{
			// the party server doesn't reliably tell the others we left, so say so ourselves
			if (isShareSafe() && isVerifiedAccount())
			{
				presence.sendOffline();
			}
			loginScreenSince = 0;
			partyService.changeParty(null);
		}
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		heardAt.clear();
		listedAt.clear();
		notifyStatus();
	}

	/**
	 * Runs after the rest of the plugin has seen the change, so a logout's last details are captured
	 * before they're sent.
	 */
	@Subscribe(priority = -1)
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			if (isGroupParty())
			{
				// stay connected, but send whatever is waiting and tell the group we've gone
				flush();
				if (isShareSafe() && isVerifiedAccount())
				{
					presence.sendOffline();
				}
				loginScreenSince = System.currentTimeMillis();
			}
			// the next login may be a different account; the member list is kept to check the party with
			localInGroup = false;
			rosterChecked = false;
			loggedInTicks = 0;
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			// playing again, so the next logout starts the idle time afresh instead of leaving straight away
			loginScreenSince = 0;
		}
		notifyStatus();
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		// joining a party lists everyone already in it, so for them this is when we arrived
		listedAt.putIfAbsent(event.getMemberId(), System.currentTimeMillis());
		if (isGroupParty())
		{
			// someone arrived, possibly us: swap summaries so everyone catches up
			summaryWanted = true;
		}
		notifyStatus();
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		heardAt.remove(event.getMemberId());
		listedAt.remove(event.getMemberId());
		notifyStatus();
	}

	// anything from a party member shows their connection is open, whoever they are

	@Subscribe
	public void onPartyData(PartyData message)
	{
		heardAt.put(message.getMemberId(), System.currentTimeMillis());
	}

	@Subscribe
	public void onHomebasePresence(HomebasePresence message)
	{
		heardAt.put(message.getMemberId(), System.currentTimeMillis());
	}

	@Subscribe
	public void onHomebasePing(HomebasePing message)
	{
		heardAt.put(message.getMemberId(), System.currentTimeMillis());
	}

	@Subscribe
	public void onHomebaseSyncMessage(HomebaseSyncMessage message)
	{
		heardAt.put(message.getMemberId(), System.currentTimeMillis());
		SyncEngine engine = this.engine;
		if (engine == null || !isGroupParty())
		{
			return;
		}

		if (!isTrusted(message.getMemberId()))
		{
			// someone outside the group can't change it
			return;
		}
		presence.heard(message.getMemberId());
		PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == message.getMemberId())
		{
			return;
		}

		if (message.getProtocol() != PROTOCOL)
		{
			log.debug("Ignoring sync message with protocol {}", message.getProtocol());
			return;
		}

		try
		{
			String json = WireCodec.unpack(message.getPayload());
			if (HomebaseSyncMessage.SUMMARY.equals(message.getType()))
			{
				Map<String, Long> summary = gson.fromJson(json, WireCodec.SUMMARY_TYPE);
				if (summary != null && engine.onSummary(summary))
				{
					summaryWanted = true;
				}
			}
			else if (HomebaseSyncMessage.RECORDS.equals(message.getType()))
			{
				List<SyncRecord> records = gson.fromJson(json, WireCodec.RECORDS_TYPE);
				if (records != null && records.size() <= MAX_RECORDS_PER_MESSAGE)
				{
					int accepted = engine.onRecords(records);
					log.debug("Received {} records, {} newer than ours", records.size(), accepted);
				}
			}
		}
		catch (IOException | RuntimeException | StackOverflowError e)
		{
			// anything thrown here would reach the party connection's thread, so a bad message is
			// dropped rather than allowed to break the connection
			log.debug("Dropping unreadable sync message", e);
		}
	}

	/**
	 * Send whatever is due. Runs on the client thread about once a second.
	 */
	public void flush()
	{
		boolean connected = isGroupParty();
		if (connected && loginScreenSince > 0 && client.getGameState() == GameState.LOGIN_SCREEN
			&& System.currentTimeMillis() - loginScreenSince >= IDLE_LEAVE_MS)
		{
			// logged out for a while: leave, so the party servers only carry people who are playing
			leaveGroupParty();
			return;
		}
		boolean safe = connected && isShareSafe();
		boolean sharing = safe && isVerifiedAccount();
		boolean justStarted = sharing && !wasSharing;
		if (sharing != wasSharing)
		{
			wasSharing = sharing;
			if (sharing)
			{
				// whatever arrived while paused may be news to the others
				summaryWanted = true;
			}
			notifyStatus();
		}
		// our name went out just before this, and whatever gets there ahead of it is ignored, so it waits a turn
		presence.tick(safe, sharing && !justStarted);
		if (justStarted)
		{
			return;
		}
		SyncEngine engine = this.engine;
		long now = System.currentTimeMillis();
		boolean finishing = safe && isFinishingAfterLogout(client.getGameState(), now - loginScreenSince);
		if (engine == null || !(sharing || finishing))
		{
			return;
		}

		if (sharing && summaryWanted && now - lastSummaryAt >= SUMMARY_INTERVAL_MS)
		{
			summaryWanted = false;
			lastSummaryAt = now;
			send(HomebaseSyncMessage.SUMMARY, gson.toJson(engine.summary()));
		}

		List<SyncRecord> due = engine.takeDue(RECORD_BUDGET, GroupSync::estimateSize);
		if (!due.isEmpty())
		{
			send(HomebaseSyncMessage.RECORDS, gson.toJson(due));
		}
	}

	private void send(String type, String json)
	{
		partyService.send(new HomebaseSyncMessage(PROTOCOL, type, WireCodec.pack(json)));
	}

	private static int estimateSize(SyncRecord record)
	{
		return RECORD_OVERHEAD + record.getKey().length() + (record.getData() == null ? 0 : record.getData().toString().length());
	}

	private void notifyStatus()
	{
		for (Runnable listener : statusListeners)
		{
			listener.run();
		}
	}
}

package com.homebase.party;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Points at a tile or a monster for a few seconds. Pings aren't saved or synced later, so they only
 * reach members who are online. The class name is the message type on the wire, so it must not be
 * renamed.
 */
@Getter
@RequiredArgsConstructor
public class HomebasePing extends PartyMemberMessage
{
	/**
	 * The world the ping was made on. Monsters are only the same monster on the same world.
	 */
	private final int world;

	/**
	 * Where it is, in the game's template map when inside an instance, as for marked tiles.
	 */
	private final int x;
	private final int y;
	private final int plane;

	/**
	 * The monster pinged, or -1 for a tile.
	 */
	private final int npcIndex;
	private final int npcId;

	/**
	 * The pinger's colour as RGB.
	 */
	private final int color;
}

package com.homebase.party;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * "Still here" while a member plays, and "going offline" just before they leave the party. The class
 * name is the message type on the wire, so it must not be renamed.
 */
@Getter
@RequiredArgsConstructor
public class HomebasePresence extends PartyMemberMessage
{
	private final boolean online;

	/**
	 * Sent in place of a position by a member who has chosen not to share theirs.
	 */
	static final int NO_POSITION = -1;

	/**
	 * Where the member is, in the form {@link WorldPoint#fromCoord} reads, or {@link #NO_POSITION}. Null
	 * when going offline, and from members on a version of the plugin that didn't send it.
	 */
	private final Integer coord;

	/**
	 * @return the point packed the way {@link #coord} carries it
	 */
	static int packCoord(WorldPoint point)
	{
		return point.getPlane() << 28 | point.getX() << 14 | point.getY();
	}
}

package com.homebase.party;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Carries a compressed summary or batch of records over RuneLite's party service. The class name is
 * the message type on the wire, so it must stay unique among plugins and must not be renamed.
 */
@Getter
@RequiredArgsConstructor
public class HomebaseSyncMessage extends PartyMemberMessage
{
	static final String SUMMARY = "S";
	static final String RECORDS = "R";

	private final int protocol;
	private final String type;
	private final String payload;
}

package com.homebase.party;

import com.homebase.HomebaseConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.party.PartyDataService;
import net.runelite.client.party.PartyDataType;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.messages.UserSync;
import net.runelite.client.plugins.Plugin;

/**
 * Shares live details through RuneLite's party service; our own sync handles everything that persists.
 * Our name goes out once the game has shown this account is in the group, even while sharing is paused,
 * so the others can tell we belong. Position, run energy, special attack, hitpoints and prayer also wait
 * until nobody else is in the party. Runs on the client thread.
 */
@Singleton
public class LiveSharing
{
	private final GroupSync groupSync;
	private final HomebaseConfig config;
	private final PartyService partyService;
	private final PartyDataService partyDataService;

	private Plugin plugin;
	private boolean nameShared;
	private boolean positionShared;
	private boolean statsShared;

	@Inject
	private LiveSharing(GroupSync groupSync, HomebaseConfig config, PartyService partyService, PartyDataService partyDataService)
	{
		this.groupSync = groupSync;
		this.config = config;
		this.partyService = partyService;
		this.partyDataService = partyDataService;
	}

	/**
	 * @param plugin who the party service keeps these subscriptions for
	 */
	public void start(Plugin plugin)
	{
		this.plugin = plugin;
	}

	public void stop()
	{
		partyDataService.unsubscribe(plugin, PartyDataType.values());
		partyDataService.unsubscribe(plugin, Skill.values());
		nameShared = false;
		positionShared = false;
		statsShared = false;
	}

	public void update()
	{
		boolean shareName = groupSync.isGroupParty() && groupSync.isVerifiedAccount();
		boolean shareStats = shareName && groupSync.isShareSafe();
		boolean sharePosition = shareStats && config.sharePosition();
		boolean started = false;
		if (shareName != nameShared)
		{
			nameShared = shareName;
			started = shareName;
			if (shareName)
			{
				partyDataService.subscribe(plugin, PartyDataType.CHARACTER_NAME);
			}
			else
			{
				partyDataService.unsubscribe(plugin, PartyDataType.CHARACTER_NAME);
			}
		}
		if (sharePosition != positionShared)
		{
			positionShared = sharePosition;
			if (sharePosition)
			{
				partyDataService.subscribe(plugin, PartyDataType.COORD);
			}
			else
			{
				partyDataService.unsubscribe(plugin, PartyDataType.COORD);
			}
		}
		if (shareStats != statsShared)
		{
			statsShared = shareStats;
			started |= shareStats;
			if (shareStats)
			{
				partyDataService.subscribe(plugin, PartyDataType.ENERGY, PartyDataType.SPEC);
				partyDataService.subscribe(plugin, Skill.HITPOINTS, Skill.PRAYER);
			}
			else
			{
				partyDataService.unsubscribe(plugin, PartyDataType.ENERGY, PartyDataType.SPEC);
				partyDataService.unsubscribe(plugin, Skill.HITPOINTS, Skill.PRAYER);
			}
		}
		PartyMember local = partyService.getLocalMember();
		if (started && local != null)
		{
			// the party only sends these when they change, so ask everyone, us included, to send theirs now
			UserSync sync = new UserSync();
			sync.setMemberId(local.getMemberId());
			partyService.send(sync);
		}
	}
}

package com.homebase.party;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.Text;

/**
 * The party's members, one per player. When a player logs out and back in, RuneLite's party server
 * can keep their old connection for a while before telling everyone it left, so the same player shows
 * up twice; only the newest connection, which is the live one, is kept.
 */
public final class PartyMembers
{
	private PartyMembers()
	{
	}

	public static List<PartyMember> current(PartyService party)
	{
		return newestPerName(party.getMembers(), PartyMember::getDisplayName);
	}

	/**
	 * @return the player's live party member, or null if they aren't in the party
	 */
	public static PartyMember byName(PartyService party, String name)
	{
		if (name == null)
		{
			return null;
		}
		String key = key(name);
		PartyMember found = null;
		for (PartyMember member : party.getMembers())
		{
			if (member.getDisplayName() != null && key(member.getDisplayName()).equals(key))
			{
				// members are listed in the order they joined, so the last match is the newest
				found = member;
			}
		}
		return found;
	}

	/**
	 * @param members in the order they joined
	 * @param nameOf each member's display name, or null if it isn't known yet
	 */
	static <T> List<T> newestPerName(List<T> members, Function<T, String> nameOf)
	{
		Map<String, T> byName = new LinkedHashMap<>();
		List<T> unnamed = new ArrayList<>();
		for (T member : members)
		{
			String name = nameOf.apply(member);
			if (name == null)
			{
				unnamed.add(member);
				continue;
			}
			String key = key(name);
			// removed first so the player moves to where their newest connection joined
			byName.remove(key);
			byName.put(key, member);
		}
		List<T> out = new ArrayList<>(byName.values());
		out.addAll(unnamed);
		return out;
	}

	private static String key(String name)
	{
		return Text.toJagexName(name).toLowerCase(Locale.ROOT);
	}
}

package com.homebase.party;

import com.homebase.HomebaseConfig;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.LongPredicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.PartyData;

/**
 * Who in the party is actually playing. RuneLite's party server doesn't reliably tell everyone when a
 * member leaves, so a member who logged out could stay "online" for ages. Instead each member says
 * when they're going offline, and sends a small "still here" every so often while they play; anyone
 * not heard from for a while counts as offline, which also covers crashes and closed windows.
 * <p>
 * The same message carries where the member is. RuneLite's party only sends a position after the
 * player has moved, and what it sends is where they were at its last update, so someone who logs in
 * and stands still has no position at all and someone who has stopped walking shows a little way back.
 */
@Singleton
public class Presence
{
	static final long HEARTBEAT_MS = 30_000;

	/**
	 * A little over two heartbeats, so one lost message doesn't drop anyone.
	 */
	static final long TIMEOUT_MS = 75_000;

	/**
	 * The least time between messages while a member is on the move.
	 */
	static final long POSITION_GAP_MS = 3_000;

	private final Client client;
	private final PartyService party;
	private final WSClient wsClient;
	private final HomebaseConfig config;

	private final Map<Long, Long> lastHeard = new ConcurrentHashMap<>();

	/**
	 * Members who said they were going offline, until they're heard from again.
	 */
	private final Set<Long> gone = ConcurrentHashMap.newKeySet();

	/**
	 * Where members last said they were.
	 */
	private final Map<Long, WorldPoint> positions = new ConcurrentHashMap<>();

	/**
	 * Members who have chosen not to share their position.
	 */
	private final Set<Long> hiddenPositions = ConcurrentHashMap.newKeySet();

	/**
	 * Members who have sent their special attack. RuneLite's party has it as 0 until they do, and a
	 * member on an older version of the plugin may never send it.
	 */
	private final Set<Long> specKnown = ConcurrentHashMap.newKeySet();
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private volatile long lastSent;
	private volatile WorldPoint lastSentPosition;
	private Set<Long> lastOnline = new HashSet<>();

	/**
	 * Which party members count as part of the group; anyone else is never shown as online.
	 */
	private volatile LongPredicate trusted = memberId -> true;

	@Inject
	Presence(Client client, PartyService party, WSClient wsClient, HomebaseConfig config)
	{
		this.client = client;
		this.party = party;
		this.wsClient = wsClient;
		this.config = config;
	}

	public void start()
	{
		wsClient.registerMessage(HomebasePresence.class);
	}

	public void stop()
	{
		wsClient.unregisterMessage(HomebasePresence.class);
		lastHeard.clear();
		gone.clear();
		positions.clear();
		hiddenPositions.clear();
		specKnown.clear();
		listeners.clear();
		lastSent = 0;
		lastSentPosition = null;
	}

	/**
	 * Called when who's online may have changed, from any thread.
	 */
	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public void setTrusted(LongPredicate trusted)
	{
		this.trusted = trusted;
	}

	/**
	 * A member was just heard from, by any message.
	 */
	public void heard(long memberId)
	{
		lastHeard.put(memberId, System.currentTimeMillis());
		gone.remove(memberId);
	}

	@Subscribe
	public void onHomebasePresence(HomebasePresence message)
	{
		if (message.isOnline())
		{
			heard(message.getMemberId());
			notePosition(message.getMemberId(), message.getCoord());
		}
		else
		{
			gone.add(message.getMemberId());
			lastHeard.remove(message.getMemberId());
			notifyListeners();
		}
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		// give them until their first "still here" arrives
		heard(event.getMemberId());
		// and send ours soon, so they can see where we are even if we're standing still
		lastSent = 0;
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		lastHeard.remove(event.getMemberId());
		gone.remove(event.getMemberId());
		positions.remove(event.getMemberId());
		hiddenPositions.remove(event.getMemberId());
		specKnown.remove(event.getMemberId());
	}

	@Subscribe
	public void onPartyData(PartyData message)
	{
		if (message.getSpecEnergy() != null)
		{
			specKnown.add(message.getMemberId());
		}
	}

	/**
	 * @return true if the member's special attack as the party has it is real, rather than the 0 it
	 * starts as
	 */
	public boolean knowsSpec(long memberId)
	{
		return specKnown.contains(memberId);
	}

	private void notePosition(long memberId, Integer coord)
	{
		if (coord == null)
		{
			return;
		}
		if (coord == HomebasePresence.NO_POSITION)
		{
			hiddenPositions.add(memberId);
			positions.remove(memberId);
		}
		else
		{
			hiddenPositions.remove(memberId);
			positions.put(memberId, WorldPoint.fromCoord(coord));
		}
	}

	/**
	 * Send "still here" when it's due, and tell listeners when someone has gone quiet. Runs about once
	 * a second on the client thread.
	 *
	 * @param safe whether we're in the group's party with nobody else in it
	 * @param sharing whether this account may send anything to it
	 */
	public void tick(boolean safe, boolean sharing)
	{
		long now = System.currentTimeMillis();
		if (sharing && client.getGameState() == GameState.LOGGED_IN)
		{
			boolean sharePosition = config.sharePosition();
			WorldPoint here = sharePosition ? localPosition() : null;
			if (isSendDue(now - lastSent, !Objects.equals(here, lastSentPosition)))
			{
				send(true, coordToSend(sharePosition, here));
				lastSentPosition = here;
			}
		}
		Set<Long> online = new HashSet<>();
		if (safe)
		{
			for (PartyMember member : party.getMembers())
			{
				if (isOnline(member))
				{
					online.add(member.getMemberId());
				}
			}
		}
		if (!online.equals(lastOnline))
		{
			lastOnline = online;
			notifyListeners();
		}
	}

	/**
	 * @return what to tell the group about where we are. Just after logging in the game may not have us
	 * yet, which is different from choosing not to share, so it says nothing rather than hide us.
	 */
	static Integer coordToSend(boolean sharePosition, WorldPoint here)
	{
		if (!sharePosition)
		{
			return HomebasePresence.NO_POSITION;
		}
		return here == null ? null : HomebasePresence.packCoord(here);
	}

	/**
	 * Tell the group we're going, just before leaving the party.
	 */
	public void sendOffline()
	{
		send(false, null);
		lastSentPosition = null;
		// so the next login says "still here" straight away
		lastSent = 0;
	}

	/**
	 * @return where the member is. Our own is read straight from the game, since it's what we send
	 * everyone else. Anyone else's is what they told us if they have, or failing that what RuneLite's
	 * party last sent, which is all a member on an older version of the plugin shares. Null if neither
	 * has said yet. Call it on the client thread.
	 */
	public WorldPoint positionOf(PartyMember member)
	{
		PartyMember local = party.getLocalMember();
		if (local != null && local.getMemberId() == member.getMemberId())
		{
			return localPosition();
		}
		return position(member.getMemberId(), member.getCoord());
	}

	WorldPoint position(long memberId, WorldPoint fromParty)
	{
		if (hiddenPositions.contains(memberId))
		{
			return null;
		}
		WorldPoint told = positions.get(memberId);
		return told != null ? told : fromParty;
	}

	/**
	 * @param sinceLastSent how long ago we last sent anything
	 * @param moved whether we've moved since then
	 */
	static boolean isSendDue(long sinceLastSent, boolean moved)
	{
		return sinceLastSent >= HEARTBEAT_MS || (moved && sinceLastSent >= POSITION_GAP_MS);
	}

	/**
	 * @return where we are, or null if the game doesn't have us yet. An instance such as a raid is given
	 * as the real place it's a copy of, and a boat's deck, which has coordinates of its own, as where
	 * the boat is. Call it on the client thread.
	 */
	public WorldPoint localPosition()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}
		LocalPoint where = player.getLocalLocation();
		WorldView view = player.getWorldView();
		if (view != null && !view.isTopLevel())
		{
			WorldEntity boat = client.getTopLevelWorldView().worldEntities().byIndex(view.getId());
			if (boat != null)
			{
				where = boat.getLocalLocation();
			}
		}
		return where == null ? null : WorldPoint.fromLocalInstance(client, where);
	}

	/**
	 * @return true if the member is playing: RuneLite has them logged in, they haven't said they're
	 * going, and they've been heard from recently
	 */
	public boolean isOnline(PartyMember member)
	{
		if (member == null || !member.isLoggedIn())
		{
			return false;
		}
		PartyMember local = party.getLocalMember();
		if (local != null && local.getMemberId() == member.getMemberId())
		{
			return client.getGameState() == GameState.LOGGED_IN;
		}
		return trusted.test(member.getMemberId()) && isOnline(member.getMemberId(), System.currentTimeMillis());
	}

	boolean isOnline(long memberId, long now)
	{
		if (gone.contains(memberId))
		{
			return false;
		}
		Long heard = lastHeard.get(memberId);
		return heard != null && now - heard < TIMEOUT_MS;
	}

	private void send(boolean online, Integer coord)
	{
		PartyMember local = party.getLocalMember();
		if (local == null)
		{
			return;
		}
		HomebasePresence message = new HomebasePresence(online, coord);
		message.setMemberId(local.getMemberId());
		party.send(message);
		lastSent = System.currentTimeMillis();
	}

	private void notifyListeners()
	{
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}
}

package com.homebase.pings;

import com.homebase.HomebaseConfig;
import com.homebase.data.GroupIndex;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines every monster the group has highlighted, in the colour of whoever highlighted it.
 */
@Singleton
public class GroupHighlightOverlay extends Overlay
{
	private final Client client;
	private final HomebaseConfig config;
	private final GroupIndex index;
	private final ModelOutlineRenderer outlines;

	@Inject
	private GroupHighlightOverlay(Client client, HomebaseConfig config, GroupIndex index, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.config = config;
		this.index = index;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView view = client.getTopLevelWorldView();
		if (!config.npcHighlights() || client.getGameState() != GameState.LOGGED_IN || view == null)
		{
			return null;
		}
		boolean names = config.tileNames();
		for (GroupIndex.Highlight highlight : index.highlights())
		{
			if (highlight.getWorld() != client.getWorld())
			{
				continue;
			}
			NPC npc = PingOverlay.npcAt(view, highlight.getIndex(), highlight.getId());
			if (npc == null)
			{
				continue;
			}
			outlines.drawOutline(npc, 2, highlight.getColor(), 4);
			if (names)
			{
				String text = highlight.getName();
				Point at = npc.getCanvasTextLocation(graphics, text, npc.getLogicalHeight() + 25);
				if (at != null)
				{
					OverlayUtil.renderTextLocation(graphics, at, text, highlight.getColor());
				}
			}
		}
		return null;
	}
}

package com.homebase.pings;

import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.HighlightsData;
import com.homebase.data.Section;
import java.util.ArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;

/**
 * Highlights monsters for the whole group. Shift + right-click a monster and choose Group highlight;
 * everyone on the same world sees it outlined in your colour until it dies or you remove it. With
 * Keep highlights after death on, it stays highlighted through dying: a monster that respawns comes
 * back with the same index, which is how a highlight knows it.
 */
@Singleton
public class GroupHighlights
{
	private static final String HIGHLIGHT = "Group highlight";
	private static final String UNHIGHLIGHT = "Group unhighlight";

	private final Client client;
	private final HomebaseConfig config;
	private final LocalCollector collector;

	@Inject
	private GroupHighlights(Client client, HomebaseConfig config, LocalCollector collector)
	{
		this.client = client;
		this.config = config;
		this.collector = collector;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.npcHighlights() || event.getType() != MenuAction.EXAMINE_NPC.getId()
			|| !client.isKeyPressed(KeyCode.KC_SHIFT) || collector.getMemberId() == null)
		{
			return;
		}
		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null)
		{
			return;
		}
		HighlightsData data = mine();
		boolean highlighted = data.getWorld() == client.getWorld() && data.contains(npc.getIndex(), npc.getId());
		client.getMenu().createMenuEntry(-1)
			.setOption(highlighted ? UNHIGHLIGHT : HIGHLIGHT)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggle(npc));
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC) || collector.getMemberId() == null || config.keepHighlights())
		{
			return;
		}
		NPC npc = (NPC) actor;
		HighlightsData data = collector.shared(Section.HIGHLIGHTS, HighlightsData.class);
		if (data != null && data.getNpcs() != null && data.remove(npc.getIndex(), npc.getId()))
		{
			collector.share(Section.HIGHLIGHTS, data);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN || collector.getMemberId() == null)
		{
			return;
		}
		// monsters on the world we left mean nothing here
		HighlightsData data = collector.shared(Section.HIGHLIGHTS, HighlightsData.class);
		if (data != null && data.getNpcs() != null && !data.getNpcs().isEmpty() && data.getWorld() != client.getWorld())
		{
			data.getNpcs().clear();
			data.setWorld(client.getWorld());
			collector.share(Section.HIGHLIGHTS, data);
		}
	}

	/**
	 * Share our highlights again with the new colour. Runs on the client thread.
	 */
	public void colorChanged()
	{
		if (collector.getMemberId() == null)
		{
			return;
		}
		HighlightsData data = collector.shared(Section.HIGHLIGHTS, HighlightsData.class);
		if (data != null)
		{
			data.setColor(config.tileColor().getRGB() & 0xFFFFFF);
			collector.share(Section.HIGHLIGHTS, data);
		}
	}

	private void toggle(NPC npc)
	{
		HighlightsData data = mine();
		if (data.getWorld() != client.getWorld())
		{
			data.getNpcs().clear();
			data.setWorld(client.getWorld());
		}
		data.setColor(config.tileColor().getRGB() & 0xFFFFFF);
		data.toggle(npc.getIndex(), npc.getId());
		collector.share(Section.HIGHLIGHTS, data);
	}

	private HighlightsData mine()
	{
		HighlightsData data = collector.shared(Section.HIGHLIGHTS, HighlightsData.class);
		if (data == null)
		{
			data = new HighlightsData();
		}
		if (data.getNpcs() == null)
		{
			data.setNpcs(new ArrayList<>());
		}
		return data;
	}
}

package com.homebase.pings;

import java.awt.Color;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Something a group member pointed at, shown for a few seconds.
 */
@Value
public class Ping
{
	long memberId;
	String name;
	Color color;
	int world;

	/**
	 * Where it is, in the template map when inside an instance.
	 */
	WorldPoint point;

	/**
	 * The monster pointed at, or -1 for a tile.
	 */
	int npcIndex;
	int npcId;

	long createdAt;

	public boolean isNpc()
	{
		return npcIndex >= 0;
	}

	/**
	 * @return how far through its life the ping is, from 0 when made to 1 when it's gone
	 */
	public float age(long now, long lifetimeMs)
	{
		return Math.min(1f, Math.max(0f, (now - createdAt) / (float) lifetimeMs));
	}
}

package com.homebase.pings;

import com.homebase.HomebaseConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Shows group pings on the minimap too, so one behind the camera still gets noticed.
 */
@Singleton
public class PingMinimapOverlay extends Overlay
{
	private final Client client;
	private final PingService pings;
	private final HomebaseConfig config;

	@Inject
	private PingMinimapOverlay(Client client, PingService pings, HomebaseConfig config)
	{
		this.client = client;
		this.pings = pings;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView view = client.getTopLevelWorldView();
		if (!config.pingMinimap() || client.getGameState() != GameState.LOGGED_IN || view == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		long lifetime = pings.lifetimeMs();
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (Ping ping : pings.active())
		{
			if (ping.getWorld() != client.getWorld())
			{
				continue;
			}
			float age = ping.age(now, lifetime);
			NPC npc = PingOverlay.npcFor(view, ping);
			if (npc != null)
			{
				draw(graphics, npc.getLocalLocation(), ping.getColor(), age);
				continue;
			}
			for (LocalPoint local : PingOverlay.localPoints(view, ping.getPoint()))
			{
				draw(graphics, local, ping.getColor(), age);
			}
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		return null;
	}

	private void draw(Graphics2D graphics, LocalPoint local, Color color, float age)
	{
		Point at = local == null ? null : Perspective.localToMinimap(client, local);
		if (at == null)
		{
			return;
		}
		int x = at.getX();
		int y = at.getY();
		graphics.setColor(Color.BLACK);
		graphics.fillOval(x - 4, y - 4, 9, 9);
		graphics.setColor(PingOverlay.fade(color, age, 255));
		graphics.fillOval(x - 3, y - 3, 7, 7);
		// a ring that keeps spreading out while the ping lasts
		int r = 4 + (int) (((age * 3) % 1f) * 8);
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.setColor(PingOverlay.fade(color, age, 200));
		graphics.drawOval(x - r, y - r, r * 2, r * 2);
	}
}

package com.homebase.pings;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Draws group pings in the game world: a pulsing outline on a pinged monster, or a filled tile with a
 * ripple, each with the pinger's name, fading out over the ping's life.
 */
@Singleton
public class PingOverlay extends Overlay
{
	/**
	 * Share of a ping's life the ripple takes.
	 */
	private static final float RIPPLE = 0.35f;

	/**
	 * The highest index the game gives a monster.
	 */
	private static final int MAX_NPC_INDEX = 65535;

	private final Client client;
	private final PingService pings;
	private final ModelOutlineRenderer outlines;

	@Inject
	private PingOverlay(Client client, PingService pings, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.pings = pings;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView view = client.getTopLevelWorldView();
		if (client.getGameState() != GameState.LOGGED_IN || view == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		long lifetime = pings.lifetimeMs();
		for (Ping ping : pings.active())
		{
			if (ping.getWorld() != client.getWorld())
			{
				continue;
			}
			float age = ping.age(now, lifetime);
			NPC npc = npcFor(view, ping);
			if (npc != null)
			{
				drawNpc(graphics, npc, ping, age);
			}
			else
			{
				for (LocalPoint local : localPoints(view, ping.getPoint()))
				{
					drawTile(graphics, local, ping, age);
				}
			}
		}
		return null;
	}

	private void drawNpc(Graphics2D graphics, NPC npc, Ping ping, float age)
	{
		// a quick double pulse at the start, then a steady outline that fades
		double pulse = age < RIPPLE ? Math.abs(Math.sin(age / RIPPLE * Math.PI * 2)) : 0;
		outlines.drawOutline(npc, 3 + (int) Math.round(pulse * 3), fade(ping.getColor(), age, 255), 4);
		String text = ping.getName();
		Point at = npc.getCanvasTextLocation(graphics, text, npc.getLogicalHeight() + 40);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, fade(ping.getColor(), age, 255));
		}
	}

	private void drawTile(Graphics2D graphics, LocalPoint local, Ping ping, float age)
	{
		Polygon poly = Perspective.getCanvasTilePoly(client, local);
		if (poly == null)
		{
			return;
		}
		Color color = ping.getColor();
		graphics.setStroke(new BasicStroke(2f));
		graphics.setColor(fade(color, age, 90));
		graphics.fill(poly);
		graphics.setColor(fade(color, age, 255));
		graphics.draw(poly);

		if (age < RIPPLE)
		{
			// a ring spreading out from the tile, so the eye catches it
			float t = age / RIPPLE;
			graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) (200 * (1 - t))));
			graphics.draw(scaled(poly, 1 + 2.5 * t));
		}

		String text = ping.getName();
		Point at = Perspective.getCanvasTextLocation(client, graphics, local, text, 120);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, fade(color, age, 255));
		}
	}

	static NPC npcFor(WorldView view, Ping ping)
	{
		return ping.isNpc() ? npcAt(view, ping.getNpcIndex(), ping.getNpcId()) : null;
	}

	/**
	 * @return the monster at an index another player sent, if it's still the same kind of monster
	 */
	static NPC npcAt(WorldView view, int index, int npcId)
	{
		// sent by another client, so it might not be a real index
		if (index < 0 || index > MAX_NPC_INDEX)
		{
			return null;
		}
		NPC npc = view.npcs().byIndex(index);
		// the index is only the same monster while it's the same kind
		return npc != null && npc.getId() == npcId ? npc : null;
	}

	/**
	 * @return where a template point is in the scene; inside instances one template tile can be in
	 * several places, or none
	 */
	static List<LocalPoint> localPoints(WorldView view, WorldPoint point)
	{
		List<LocalPoint> out = new ArrayList<>();
		for (WorldPoint wp : WorldPoint.toLocalInstance(view, point))
		{
			if (wp.getPlane() != view.getPlane())
			{
				continue;
			}
			LocalPoint local = LocalPoint.fromWorld(view, wp);
			if (local != null)
			{
				out.add(local);
			}
		}
		return out;
	}

	/**
	 * @return the colour faded for a ping's age: bright for most of its life, then quickly gone
	 */
	static Color fade(Color color, float age, int alpha)
	{
		float left = 1 - age * age;
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, (int) (alpha * left))));
	}

	private static Polygon scaled(Polygon poly, double factor)
	{
		Rectangle bounds = poly.getBounds();
		double cx = bounds.getCenterX();
		double cy = bounds.getCenterY();
		Polygon out = new Polygon();
		for (int i = 0; i < poly.npoints; i++)
		{
			out.addPoint((int) Math.round(cx + (poly.xpoints[i] - cx) * factor), (int) Math.round(cy + (poly.ypoints[i] - cy) * factor));
		}
		return out;
	}
}

package com.homebase.pings;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.party.GroupSync;
import com.homebase.party.HomebasePing;
import com.homebase.party.Presence;
import java.awt.Color;
import java.awt.Point;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.SoundEffectID;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.util.HotkeyListener;

/**
 * Middle-click the ground or a monster, or hold the ping key and left-click it, and everyone in the
 * group sees it marked in your colour for a few seconds. A middle-click does nothing in game; a ping
 * key click is swallowed so nothing happens, the same way RuneLite's Party plugin handles its pings.
 */
@Singleton
public class PingService
{
	/**
	 * Clicks closer together than this send one ping.
	 */
	private static final long SEND_GAP_MS = 400;

	/**
	 * Pings arriving closer together than this play one sound.
	 */
	private static final long SOUND_GAP_MS = 1_000;

	/**
	 * A middle press that moves further than this, or is held longer, is turning the camera.
	 */
	private static final int CLICK_SLOP_PX = 5;
	private static final long CLICK_MAX_MS = 500;

	/**
	 * Pings kept per member, so nobody can fill the screen.
	 */
	private static final int MAX_PINGS_PER_MEMBER = 3;

	private static final int MAX_NAME = 20;

	private final Client client;
	private final ClientThread clientThread;
	private final HomebaseConfig config;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final KeyManager keyManager;
	private final MouseManager mouseManager;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final Presence presence;

	private final HotkeyListener hotkey;
	private final MouseAdapter middleClick;

	/**
	 * Pings still showing, oldest first. They arrive on the party's thread and are drawn on the client
	 * thread, so every use locks the list.
	 */
	private final List<Ping> pings = new ArrayList<>();

	private volatile boolean keyHeld;
	private Point pressedAt;
	private long pressedTime;
	private long lastSent;
	private volatile long lastSoundAt;

	@Inject
	private PingService(Client client, ClientThread clientThread, HomebaseConfig config, PartyService partyService,
		WSClient wsClient, KeyManager keyManager, MouseManager mouseManager, GroupSync groupSync, GroupIndex index,
		Presence presence)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.keyManager = keyManager;
		this.mouseManager = mouseManager;
		this.groupSync = groupSync;
		this.index = index;
		this.presence = presence;
		middleClick = new MouseAdapter()
		{
			@Override
			public MouseEvent mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isMiddleMouseButton(e))
				{
					pressedAt = e.getPoint();
					pressedTime = System.currentTimeMillis();
				}
				return e;
			}

			@Override
			public MouseEvent mouseReleased(MouseEvent e)
			{
				// the event is passed on untouched either way, so dragging still turns the camera
				if (SwingUtilities.isMiddleMouseButton(e) && pressedAt != null)
				{
					boolean click = pressedAt.distance(e.getPoint()) <= CLICK_SLOP_PX
						&& System.currentTimeMillis() - pressedTime <= CLICK_MAX_MS;
					pressedAt = null;
					if (click && config.pingButton() == HomebaseConfig.PingButton.MIDDLE_CLICK)
					{
						clientThread.invoke(PingService.this::pingHovered);
					}
				}
				return e;
			}
		};
		hotkey = new HotkeyListener(config::pingKey)
		{
			@Override
			public void hotkeyPressed()
			{
				keyHeld = true;
			}

			@Override
			public void hotkeyReleased()
			{
				keyHeld = false;
			}
		};
	}

	public void start()
	{
		wsClient.registerMessage(HomebasePing.class);
		keyManager.registerKeyListener(hotkey);
		mouseManager.registerMouseListener(middleClick);
	}

	public void stop()
	{
		mouseManager.unregisterMouseListener(middleClick);
		keyManager.unregisterKeyListener(hotkey);
		wsClient.unregisterMessage(HomebasePing.class);
		keyHeld = false;
		synchronized (pings)
		{
			pings.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!keyHeld || config.pingButton() != HomebaseConfig.PingButton.KEY_AND_CLICK || client.isMenuOpen())
		{
			return;
		}
		if (ping(event.getMenuEntry().getNpc()))
		{
			event.consume();
		}
	}

	/**
	 * Ping whatever the mouse is over: the monster whose option is on top of the menu, or else the
	 * tile under the cursor. Runs on the client thread.
	 */
	private void pingHovered()
	{
		if (client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		// the last entry is the one a left-click would choose, which belongs to what's on top
		ping(entries.length == 0 ? null : entries[entries.length - 1].getNpc());
	}

	/**
	 * @return true if the click was on the game world, so it was a ping (sent unless it came too soon
	 * after the last one)
	 */
	private boolean ping(NPC npc)
	{
		PartyMember local = partyService.getLocalMember();
		WorldView view = client.getTopLevelWorldView();
		if (!config.pings() || !groupSync.isSharing() || local == null || view == null)
		{
			return false;
		}

		LocalPoint where;
		if (npc != null)
		{
			where = npc.getLocalLocation();
		}
		else
		{
			// only clicks on the game world, not on the inventory or other interfaces
			if (!onScene())
			{
				return false;
			}
			Tile tile = view.getSelectedSceneTile();
			where = tile == null ? null : tile.getLocalLocation();
		}
		if (where == null)
		{
			return false;
		}

		long now = System.currentTimeMillis();
		if (now - lastSent < SEND_GAP_MS)
		{
			return true;
		}
		lastSent = now;
		WorldPoint point = WorldPoint.fromLocalInstance(client, where);
		HomebasePing ping = new HomebasePing(client.getWorld(), point.getX(), point.getY(), point.getPlane(),
			npc == null ? -1 : npc.getIndex(), npc == null ? -1 : npc.getId(), config.tileColor().getRGB() & 0xFFFFFF);
		ping.setMemberId(local.getMemberId());
		// the party sends it back to us too, which is how our own ping shows up
		partyService.send(ping);
		return true;
	}

	private boolean onScene()
	{
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			if ("Walk here".equals(entry.getOption()))
			{
				return true;
			}
		}
		return false;
	}

	@Subscribe
	public void onHomebasePing(HomebasePing message)
	{
		// a Group Ironman group's party only listens to the group's members
		if (!config.pings() || !groupSync.isGroupParty() || !groupSync.isTrusted(message.getMemberId()))
		{
			return;
		}
		presence.heard(message.getMemberId());
		PartyMember member = partyService.getMemberById(message.getMemberId());
		String name = member == null ? null : Clean.text(member.getDisplayName(), MAX_NAME);
		// and only to members whose data has arrived, so their pings have a colour and a name
		if (name == null || index.memberId(name) == null)
		{
			return;
		}
		Ping ping = new Ping(message.getMemberId(), name, new Color(message.getColor() & 0xFFFFFF), message.getWorld(),
			new WorldPoint(message.getX(), message.getY(), message.getPlane()), message.getNpcIndex(), message.getNpcId(),
			System.currentTimeMillis());
		synchronized (pings)
		{
			int mine = 0;
			for (int i = pings.size() - 1; i >= 0; i--)
			{
				if (pings.get(i).getMemberId() == ping.getMemberId() && ++mine >= MAX_PINGS_PER_MEMBER)
				{
					pings.remove(i);
				}
			}
			pings.add(ping);
		}
		long now = System.currentTimeMillis();
		if (config.pingSound() && now - lastSoundAt >= SOUND_GAP_MS)
		{
			lastSoundAt = now;
			clientThread.invokeLater(() -> client.playSoundEffect(SoundEffectID.SMITH_ANVIL_TINK));
		}
	}

	/**
	 * @return the pings still showing, oldest first
	 */
	public List<Ping> active()
	{
		long now = System.currentTimeMillis();
		long lifetime = lifetimeMs();
		synchronized (pings)
		{
			for (Iterator<Ping> it = pings.iterator(); it.hasNext(); )
			{
				if (now - it.next().getCreatedAt() >= lifetime)
				{
					it.remove();
				}
			}
			return new ArrayList<>(pings);
		}
	}

	public long lifetimeMs()
	{
		return Math.max(1, config.pingSeconds()) * 1000L;
	}
}

package com.homebase.requests;

import com.homebase.data.RequestData;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Finishes requests from what actually happens in game, so nobody can just say they're done. The
 * member who took a request on delivers it one of two ways:
 * <ul>
 * <li>putting the item in group storage, where it's kept for the member who asked, and the request is
 * done once they take it out. Only one member can have group storage open at a time, so the changes
 * seen there are our own.</li>
 * <li>trading it to the member who asked, which counts when the trade is accepted.</li>
 * </ul>
 * Amounts add up, so a request for 500 can be delivered as 200 and then 300.
 */
@Singleton
public class RequestDelivery
{
	private static final String TRADE_ACCEPTED = "Accepted trade.";

	/**
	 * Ticks after the trade screens close to wait for the game's "Accepted trade." message.
	 */
	private static final int TRADE_GRACE_TICKS = 2;

	private final Client client;
	private final ItemManager itemManager;
	private final RequestService requests;

	/**
	 * What group storage held at the last change, or null while it's closed.
	 */
	private Map<Integer, Integer> lastCounts;

	/**
	 * Who we're trading with and what we're offering, kept until the trade is accepted.
	 */
	private String tradePartner;
	private Map<Integer, Integer> offered = new HashMap<>();
	private boolean tradeOpen;
	private int tradeClosedTick;

	@Inject
	private RequestDelivery(Client client, ItemManager itemManager, RequestService requests)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.requests = requests;
	}

	/**
	 * Forget any storage or trade in progress, when the plugin stops.
	 */
	public void reset()
	{
		lastCounts = null;
		tradePartner = null;
		offered = new HashMap<>();
		tradeOpen = false;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.TRADEOFFER)
		{
			// the offer empties as the trade goes through, so only changes made on the first screen count
			Map<Integer, Integer> offer = counts(event.getItemContainer());
			if (!offer.isEmpty() || visible(InterfaceID.Trademain.TITLE))
			{
				offered = offer;
			}
			return;
		}
		if (event.getContainerId() != InventoryID.INV_GROUP_TEMP)
		{
			return;
		}
		Map<Integer, Integer> now = counts(event.getItemContainer());
		Map<Integer, Integer> before = lastCounts;
		lastCounts = now;
		// the first look after opening is only where we start from
		if (before == null || !requests.canEdit())
		{
			return;
		}
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			int added = e.getValue() - before.getOrDefault(e.getKey(), 0);
			if (added > 0)
			{
				deposited(e.getKey(), added);
			}
		}
		for (Map.Entry<Integer, Integer> e : before.entrySet())
		{
			int taken = e.getValue() - now.getOrDefault(e.getKey(), 0);
			if (taken > 0)
			{
				withdrawn(e.getKey(), taken);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (lastCounts != null && !visible(InterfaceID.SharedBank.ITEMS))
		{
			lastCounts = null;
		}

		String partner = partnerFrom(InterfaceID.Trademain.TITLE);
		if (partner == null)
		{
			partner = partnerFrom(InterfaceID.Tradeconfirm.TRADEOPPONENT);
		}
		if (partner != null)
		{
			if (!tradeOpen)
			{
				// a new trade: forget the last one's offer
				offered = new HashMap<>();
			}
			tradeOpen = true;
			tradePartner = partner;
		}
		else if (tradeOpen)
		{
			tradeOpen = false;
			tradeClosedTick = client.getTickCount();
		}
		else if (tradePartner != null && client.getTickCount() - tradeClosedTick > TRADE_GRACE_TICKS)
		{
			// declined, or closed without trading
			tradePartner = null;
			offered = new HashMap<>();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// only the game's own message counts, not a player typing the same words
		boolean fromGame = event.getType() == ChatMessageType.TRADE || event.getType() == ChatMessageType.GAMEMESSAGE;
		if (tradePartner == null || !fromGame || !TRADE_ACCEPTED.equals(Text.removeTags(event.getMessage()).trim()))
		{
			return;
		}
		String partner = tradePartner;
		Map<Integer, Integer> gave = offered;
		tradePartner = null;
		offered = new HashMap<>();
		if (!requests.canEdit())
		{
			return;
		}
		for (Map.Entry<Integer, Integer> e : gave.entrySet())
		{
			traded(partner, e.getKey(), e.getValue());
		}
	}

	/**
	 * We put some of an item in group storage: if it's for a request we took on, keep it for whoever
	 * asked.
	 */
	private void deposited(int itemId, int amount)
	{
		String name = nameOf(itemId);
		for (RequestService.Request request : requests.list())
		{
			RequestData data = request.getData();
			boolean sameReservation = data.getReservedItemId() == 0 || data.getReservedItemId() == itemId;
			boolean stillNeeded = data.getDelivered() + data.getReservedQuantity() < data.asked();
			if (!data.isDone() && takenByMe(data) && sameReservation && stillNeeded && sameItem(data.getItem(), name))
			{
				requests.keep(request.getId(), itemId, amount);
				return;
			}
		}
	}

	/**
	 * We took some of an item out of group storage: if it was kept for us, we've received it.
	 */
	private void withdrawn(int itemId, int amount)
	{
		for (RequestService.Reservation reservation : requests.reservationsFor(itemId))
		{
			if (requests.isMe(reservation.getRequestedBy()))
			{
				requests.receive(reservation.getRequestId(), amount, true);
				return;
			}
		}
		// or we put it in for someone and took it back out, so it's no longer there to hold
		for (RequestService.Request request : requests.list())
		{
			RequestData data = request.getData();
			if (data.isReserved() && data.getReservedItemId() == itemId && takenByMe(data))
			{
				requests.takeBack(request.getId(), amount);
				return;
			}
		}
	}

	/**
	 * We handed items to someone in a trade: if it's what they asked us for, they've received it.
	 */
	private void traded(String partner, int itemId, int quantity)
	{
		String name = nameOf(itemId);
		for (RequestService.Request request : requests.list())
		{
			RequestData data = request.getData();
			if (!data.isDone() && takenByMe(data) && sameName(partner, data.getRequestedByName()) && sameItem(data.getItem(), name))
			{
				requests.receive(request.getId(), quantity, false);
				return;
			}
		}
	}

	/**
	 * @return true if we took the request on, and it isn't our own
	 */
	private boolean takenByMe(RequestData data)
	{
		return requests.isMe(data.getAssignedTo()) && !requests.isMe(data.getRequestedBy());
	}

	private String nameOf(int itemId)
	{
		return Text.removeTags(itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName());
	}

	/**
	 * @return the name of the player we're trading with, from a trade screen's title, or null if that
	 * screen isn't open
	 */
	private String partnerFrom(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		if (widget == null || widget.isHidden() || widget.getText() == null)
		{
			return null;
		}
		return partnerName(widget.getText());
	}

	/**
	 * @return the player's name from a trade screen title such as "Trading With: Bonscott Kid"
	 */
	static String partnerName(String title)
	{
		String text = Text.removeTags(title.replace("<br>", " "));
		int colon = text.indexOf(':');
		String name = (colon >= 0 ? text.substring(colon + 1) : text).trim();
		return name.isEmpty() ? null : name;
	}

	private boolean visible(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget != null && !widget.isHidden();
	}

	/**
	 * @return true if what was asked for, as typed, is this item
	 */
	static boolean sameItem(String asked, String itemName)
	{
		return asked != null && itemName != null && normalize(asked).equals(normalize(itemName));
	}

	/**
	 * @return true if two player names are the same player, however their spaces are written
	 */
	static boolean sameName(String a, String b)
	{
		return a != null && b != null && Text.toJagexName(a).equalsIgnoreCase(Text.toJagexName(b));
	}

	private static String normalize(String text)
	{
		return text.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	private static Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0)
				{
					out.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return out;
	}
}

package com.homebase.requests;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.homebase.collect.LocalCollector;
import com.homebase.data.Checkable;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.data.Ids;
import com.homebase.data.RequestData;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncEngine;
import com.homebase.sync.SyncRecord;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Creates and updates item requests. Requests are shared records, so any member can change them and
 * the newest change wins.
 */
@Slf4j
@Singleton
public class RequestService
{
	public static final String TYPE = "request";

	private static final int MAX_ITEM = 60;
	private static final int MAX_NOTE = 140;
	private static final int MAX_NAME = 20;

	@Value
	public static class Request
	{
		String id;
		RequestData data;
	}

	/**
	 * An item waiting in group storage for the member who asked for it.
	 */
	@Value
	public static class Reservation
	{
		String requestId;
		String item;
		String requestedBy;
		String requestedByName;

		/**
		 * How many are kept; anything more in group storage is free for anyone.
		 */
		int quantity;
	}

	private final LocalCollector collector;
	private final GroupIndex groupIndex;
	private final Gson gson;

	private volatile SyncEngine engine;
	private volatile boolean dirty = true;
	private volatile Map<Integer, List<Reservation>> reservations = Collections.emptyMap();

	@Inject
	private RequestService(LocalCollector collector, GroupIndex groupIndex, Gson gson)
	{
		this.collector = collector;
		this.groupIndex = groupIndex;
		this.gson = gson;
	}

	public void setEngine(SyncEngine engine)
	{
		this.engine = engine;
		dirty = true;
	}

	/**
	 * Group data changed, which may reserve or release items.
	 */
	public void invalidate()
	{
		dirty = true;
	}

	/**
	 * @return the requests an item in group storage is kept for, if any. Cheap enough to call for
	 * every menu entry and every frame.
	 */
	public synchronized List<Reservation> reservationsFor(int itemId)
	{
		if (dirty)
		{
			dirty = false;
			reservations = buildReservations();
		}
		return reservations.getOrDefault(itemId, Collections.emptyList());
	}

	private Map<Integer, List<Reservation>> buildReservations()
	{
		Map<Integer, List<Reservation>> out = new HashMap<>();
		for (Request request : list())
		{
			RequestData data = request.getData();
			// only kept for, and by, people in the group
			if (data.isReserved() && groupIndex.isMember(data.getRequestedBy())
				&& (data.getAssignedTo() == null || groupIndex.isMember(data.getAssignedTo())))
			{
				out.computeIfAbsent(data.getReservedItemId(), id -> new ArrayList<>()).add(new Reservation(request.getId(),
					data.getItem(), data.getRequestedBy(), data.getRequestedByName(), data.getReservedQuantity()));
			}
		}
		return out;
	}

	/**
	 * The member who took the request on put the item in group storage: keep it for the requester.
	 */
	public void keep(String id, int itemId, int amount)
	{
		update(id, data -> data.keep(itemId, amount));
	}

	/**
	 * The member who put the item in group storage took some of it back out.
	 */
	public void takeBack(String id, int amount)
	{
		update(id, data -> data.takeBack(amount));
	}

	/**
	 * The requester got some of what they asked for, out of group storage or by trade.
	 */
	public void receive(String id, int amount, boolean fromStorage)
	{
		update(id, data -> data.receive(amount, fromStorage));
	}

	/**
	 * Requests can only be changed while logged in, since every change is signed with who made it.
	 */
	public boolean canEdit()
	{
		return engine != null && collector.getMemberId() != null && collector.getLocalName() != null;
	}

	/**
	 * @return true if the member id is the logged in player
	 */
	public boolean isMe(String memberId)
	{
		return memberId != null && memberId.equals(collector.getMemberId());
	}

	/**
	 * @return open requests newest first, then finished ones newest first
	 */
	public List<Request> list()
	{
		SyncEngine engine = this.engine;
		List<Request> out = new ArrayList<>();
		if (engine == null)
		{
			return out;
		}
		String prefix = Keys.sharedPrefix(TYPE);
		for (SyncRecord record : engine.getStore().withPrefix(prefix))
		{
			RequestData data = decode(record);
			if (data != null && !Strings.isNullOrEmpty(data.getItem()))
			{
				out.add(new Request(record.getKey().substring(prefix.length()), data));
			}
		}
		out.sort(Comparator
			.comparing((Request r) -> r.getData().isDone())
			.thenComparing(Comparator.comparingLong((Request r) -> r.getData().getCreatedAt()).reversed()));
		return out;
	}

	public void create(String item, int quantity, String note)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		String myName = collector.getLocalName();
		if (engine == null || me == null || myName == null || Strings.isNullOrEmpty(item))
		{
			return;
		}
		String cleanItem = Clean.text(item, MAX_ITEM);
		if (cleanItem == null)
		{
			return;
		}
		RequestData data = new RequestData();
		data.setItem(cleanItem);
		data.setQuantity(Math.max(1, quantity));
		data.setNote(Clean.text(note, MAX_NOTE));
		data.setRequestedBy(me);
		data.setRequestedByName(myName);
		data.setCreatedAt(System.currentTimeMillis());
		String id = Ids.random();
		engine.publish(Keys.shared(TYPE, id), me, gson.toJsonTree(data));
	}

	/**
	 * Take a request on.
	 */
	public void claim(String id)
	{
		update(id, data ->
		{
			data.setAssignedTo(collector.getMemberId());
			data.setAssignedToName(collector.getLocalName());
		});
	}

	/**
	 * Give a request back so someone else can take it.
	 */
	public void unclaim(String id)
	{
		update(id, data ->
		{
			data.setAssignedTo(null);
			data.setAssignedToName(null);
			data.setReservedItemId(0);
			data.setReservedQuantity(0);
		});
	}

	public void delete(String id)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		if (engine != null && me != null)
		{
			engine.delete(Keys.shared(TYPE, id), me);
		}
	}

	/**
	 * Describe a change someone else made, for the chat box, or null if it isn't worth a message.
	 */
	public String describeChange(SyncRecord record)
	{
		if (record.isDeleted() || !record.getKey().startsWith(Keys.sharedPrefix(TYPE)))
		{
			return null;
		}
		RequestData data = decode(record);
		if (data == null || Strings.isNullOrEmpty(data.getItem()))
		{
			return null;
		}
		String what = data.getQuantity() > 1 ? data.getQuantity() + " x " + data.getItem() : data.getItem();
		if (data.isReserved())
		{
			String kept = data.getReservedQuantity() > 1 ? data.getReservedQuantity() + " x " + data.getItem() : data.getItem();
			return name(data.getAssignedToName()) + " put " + kept + " in group storage for " + name(data.getRequestedByName()) + ".";
		}
		if (data.isDone())
		{
			return name(data.getAssignedToName()) + " finished " + what + " for " + name(data.getRequestedByName()) + ".";
		}
		if (data.getAssignedTo() != null)
		{
			return name(data.getAssignedToName()) + " is getting " + what + " for " + name(data.getRequestedByName()) + ".";
		}
		return name(data.getRequestedByName()) + " requested " + what + ".";
	}

	private void update(String id, Consumer<RequestData> change)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		if (engine == null || me == null)
		{
			return;
		}
		String key = Keys.shared(TYPE, id);
		RequestData data = decode(engine.getStore().get(key));
		if (data == null)
		{
			return;
		}
		change.accept(data);
		engine.publish(key, me, gson.toJsonTree(data));
	}

	private RequestData decode(SyncRecord record)
	{
		if (record == null || record.getData() == null)
		{
			return null;
		}
		try
		{
			RequestData data = Checkable.checked(gson.fromJson(record.getData(), RequestData.class));
			if (data != null)
			{
				// written by other players' clients, so never trust it for display
				data.setItem(Clean.text(data.getItem(), MAX_ITEM));
				data.setNote(Clean.text(data.getNote(), MAX_NOTE));
				data.setRequestedByName(Clean.text(data.getRequestedByName(), MAX_NAME));
				data.setAssignedToName(Clean.text(data.getAssignedToName(), MAX_NAME));
			}
			return data;
		}
		catch (RuntimeException e)
		{
			log.debug("Unreadable request {}", record.getKey(), e);
			return null;
		}
	}

	private static String name(String name)
	{
		return Strings.isNullOrEmpty(name) ? "Someone" : name;
	}
}

package com.homebase.storage;

import com.google.gson.JsonObject;
import com.homebase.collect.LocalCollector;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncEngine;
import com.homebase.sync.SyncRecord;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Items in group storage marked as needing to be returned. Storage is mostly for giving each other
 * things, so taking something out only leaves you owing it if it's been marked as belonging there.
 */
@Singleton
public class ReturnTags
{
	private static final String TYPE = "return";

	private final LocalCollector collector;
	private volatile SyncEngine engine;

	@Inject
	private ReturnTags(LocalCollector collector)
	{
		this.collector = collector;
	}

	public void setEngine(SyncEngine engine)
	{
		this.engine = engine;
	}

	public boolean canEdit()
	{
		return engine != null && collector.getMemberId() != null;
	}

	/**
	 * @return each marked item, and when it was marked
	 */
	public Map<Integer, Long> marked()
	{
		SyncEngine engine = this.engine;
		Map<Integer, Long> out = new HashMap<>();
		if (engine == null)
		{
			return out;
		}
		String prefix = Keys.sharedPrefix(TYPE);
		for (SyncRecord record : engine.getStore().withPrefix(prefix))
		{
			int item = itemOf(record.getKey().substring(prefix.length()));
			if (item > 0)
			{
				out.put(item, record.getVersion());
			}
		}
		return out;
	}

	public void mark(int item)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		if (engine != null && me != null && item > 0)
		{
			JsonObject data = new JsonObject();
			data.addProperty("item", item);
			engine.publish(Keys.shared(TYPE, String.valueOf(item)), me, data);
		}
	}

	public void unmark(int item)
	{
		SyncEngine engine = this.engine;
		String me = collector.getMemberId();
		if (engine != null && me != null && item > 0)
		{
			engine.delete(Keys.shared(TYPE, String.valueOf(item)), me);
		}
	}

	/**
	 * @return the item a key's id names, or 0 if another member's client sent something that isn't one
	 */
	static int itemOf(String id)
	{
		try
		{
			return Math.max(0, Integer.parseInt(id));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.homebase.storage;

import com.homebase.data.StorageLogData;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import lombok.Value;
import net.runelite.api.Item;

/**
 * Works out what changed in group storage, and what the group's logs say happened and what's still out.
 */
public final class StorageHistory
{
	/**
	 * More kinds of item than an inventory and worn equipment hold. A save can't move this many in one
	 * direction, so a change this big means what we saw wasn't really what storage held.
	 */
	static final int MAX_KINDS_PER_SAVE = 40;

	private StorageHistory()
	{
	}

	/**
	 * Some of one item going in or out of group storage.
	 */
	@Value
	static class Change
	{
		int item;

		/**
		 * Above 0 when put in, below 0 when taken out.
		 */
		int amount;
	}

	/**
	 * One member's log, as read for the panel.
	 */
	@Value
	public static class MemberLog
	{
		String name;
		StorageLogData log;

		/**
		 * When the log was written. No entry in it can be newer than this.
		 */
		long updatedAt;
	}

	/**
	 * A line of the history: who put in or took out how many of what, and when.
	 */
	@Value
	public static class Line
	{
		String who;
		int item;
		int amount;
		long at;
	}

	/**
	 * Some of a marked item a member has taken out and not put back, and when they last took some.
	 */
	@Value
	public static class Owed
	{
		String who;
		int item;
		long amount;
		long at;
	}

	/**
	 * @return how many of each item the slots hold, wherever they are
	 */
	static Map<Integer, Integer> counts(Item[] slots)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (slots != null)
		{
			for (Item item : slots)
			{
				if (item != null && item.getId() > 0 && item.getQuantity() > 0)
				{
					out.merge(item.getId(), item.getQuantity(), (a, b) -> (int) Math.min((long) a + b, Integer.MAX_VALUE));
				}
			}
		}
		return out;
	}

	/**
	 * @return what changed from one look at group storage to a later one, by item. Items only count by
	 * how many there are, so moving them between slots is no change.
	 */
	static List<Change> changes(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		TreeSet<Integer> items = new TreeSet<>(before.keySet());
		items.addAll(after.keySet());
		List<Change> out = new ArrayList<>();
		for (int item : items)
		{
			int amount = after.getOrDefault(item, 0) - before.getOrDefault(item, 0);
			if (amount != 0)
			{
				out.add(new Change(item, amount));
			}
		}
		return out;
	}

	/**
	 * @return false if no one save could have made these changes
	 */
	static boolean possible(List<Change> changes)
	{
		int in = 0;
		int out = 0;
		for (Change change : changes)
		{
			if (change.getAmount() > 0)
			{
				in++;
			}
			else
			{
				out++;
			}
		}
		return in <= MAX_KINDS_PER_SAVE && out <= MAX_KINDS_PER_SAVE;
	}

	/**
	 * @return every member's entries together, newest first
	 */
	public static List<Line> lines(List<MemberLog> logs)
	{
		List<Line> out = new ArrayList<>();
		for (MemberLog member : logs)
		{
			for (StorageLogData.Entry entry : member.getLog().getEntries())
			{
				out.add(new Line(member.getName(), entry.getItem(), entry.getAmount(), timeOf(entry, member)));
			}
		}
		out.sort(Comparator.comparingLong(Line::getAt).reversed());
		return out;
	}

	/**
	 * Something is owed when it's marked as needing to be returned and a member has taken out more of
	 * it than they've put in, so taking back what you put in yourself doesn't count. Only their own
	 * entries count: someone else putting in the same item doesn't settle it. Neither do entries from
	 * before it was marked, since whoever took it then was free to keep it.
	 *
	 * @param marked each item marked as needing to be returned, and when it was marked
	 * @return what's still out, most recently taken first
	 */
	public static List<Owed> owed(List<MemberLog> logs, Map<Integer, Long> marked)
	{
		List<Owed> out = new ArrayList<>();
		for (MemberLog member : logs)
		{
			Map<Integer, Long> net = new HashMap<>();
			Map<Integer, Long> lastTaken = new HashMap<>();
			for (StorageLogData.Entry entry : member.getLog().getEntries())
			{
				Long markedAt = marked.get(entry.getItem());
				long at = timeOf(entry, member);
				if (markedAt == null || at < markedAt)
				{
					continue;
				}
				net.merge(entry.getItem(), (long) entry.getAmount(), Long::sum);
				if (entry.getAmount() < 0)
				{
					lastTaken.merge(entry.getItem(), at, Math::max);
				}
			}
			net.forEach((item, amount) ->
			{
				if (amount < 0)
				{
					out.add(new Owed(member.getName(), item, -amount, lastTaken.get(item)));
				}
			});
		}
		out.sort(Comparator.comparingLong(Owed::getAt).reversed().thenComparingInt(Owed::getItem));
		return out;
	}

	private static long timeOf(StorageLogData.Entry entry, MemberLog member)
	{
		return Math.min(entry.getAt(), member.getUpdatedAt());
	}
}

package com.homebase.storage;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Follows one member's time with group storage open and says what each save changed.
 * <p>
 * While it's open the game only shows a temporary copy of storage. Changes count once they're saved, and
 * can be lost until then, so only a save produces anything. Everything is compared with what storage
 * held when it was opened or last saved, so opening and closing it, putting something in and taking it
 * back, or moving items around all come to nothing.
 */
final class StorageSession
{
	/**
	 * Ticks after the interface closes to wait for its save to show up.
	 */
	static final int CLOSE_GRACE_TICKS = 5;

	/**
	 * What storage held when opened or last saved, or null while nothing is being followed.
	 */
	private Map<Integer, Integer> saved;

	/**
	 * What it holds now, as far as we've seen.
	 */
	private Map<Integer, Integer> current;
	private int closedTicks;

	/**
	 * True until the tick it was opened on ends. The first look can be the copy left from last time it
	 * was open, with the game's fresh one just behind it, and nobody can change anything that quickly,
	 * so everything until then is just what storage holds. Otherwise another member's save made while
	 * it was closed would be counted as ours.
	 */
	private boolean opening;

	/**
	 * The interface was drawn from what the game sent. It's the one time an empty storage can be
	 * believed: an empty container on its own can just mean it hasn't been filled in yet. Only while
	 * it's closing is it ignored, since by then the temporary copy may already be gone.
	 */
	void built(Map<Integer, Integer> now, boolean open)
	{
		if (open || saved == null)
		{
			look(now);
		}
	}

	/**
	 * The game reported a change in the container. It can arrive just after the interface closes, if the
	 * last change and leaving happened on the same tick, but it never starts anything then.
	 */
	void changed(Map<Integer, Integer> now, boolean open)
	{
		if (!now.isEmpty() && (open || saved != null))
		{
			look(now);
		}
	}

	private void look(Map<Integer, Integer> now)
	{
		if (saved == null)
		{
			opening = true;
		}
		if (opening)
		{
			saved = now;
		}
		current = now;
	}

	/**
	 * Call once a game tick, after that tick's changes.
	 *
	 * @param open true if the interface is open
	 * @param saving true if the game has shown that it's saving
	 * @return what was saved, if a save just happened
	 */
	List<StorageHistory.Change> tick(boolean open, boolean saving)
	{
		opening = false;
		List<StorageHistory.Change> out = Collections.emptyList();
		if (saving && saved != null)
		{
			List<StorageHistory.Change> changes = StorageHistory.changes(saved, current);
			if (StorageHistory.possible(changes))
			{
				out = changes;
			}
			saved = current;
		}
		if (open || saving)
		{
			closedTicks = 0;
		}
		else if (saved != null && ++closedTicks > CLOSE_GRACE_TICKS)
		{
			reset();
		}
		return out;
	}

	void reset()
	{
		saved = null;
		current = null;
		closedTicks = 0;
		opening = false;
	}
}

package com.homebase.storage;

import com.homebase.collect.LocalCollector;
import com.homebase.data.Section;
import com.homebase.data.StorageLogData;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Adds to our group storage log each time the game saves storage, and shares the log with the group.
 * Only one member can have group storage open at a time, so the changes seen there are our own.
 */
@Singleton
public class StorageWatcher
{
	private final Client client;
	private final LocalCollector collector;
	private final StorageSession session = new StorageSession();

	/**
	 * Set when the game's "Saving..." message closes, for the next game tick. By then the game has
	 * reported every change that came before the save.
	 */
	private boolean saveFinished;

	@Inject
	private StorageWatcher(Client client, LocalCollector collector)
	{
		this.client = client;
		this.collector = collector;
	}

	/**
	 * Forget storage in progress, when the plugin stops.
	 */
	public void reset()
	{
		session.reset();
		saveFinished = false;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV_GROUP_TEMP && event.getItemContainer() != null)
		{
			session.changed(StorageHistory.counts(event.getItemContainer().getItems()), isOpen());
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.GROUP_IRONMAN_STORAGE_BUILD)
		{
			ItemContainer storage = client.getItemContainer(InventoryID.INV_GROUP_TEMP);
			if (storage != null)
			{
				session.built(StorageHistory.counts(storage.getItems()), isOpen());
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.LOADING_ICON_MODAL)
		{
			// it's closing, so it no longer counts as showing, but its text is still there
			Widget text = client.getWidget(InterfaceID.LoadingIconModal.TEXT);
			saveFinished |= text != null && isSavingText(text.getText());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean saving = saveFinished || savingShown();
		saveFinished = false;
		add(session.tick(isOpen(), saving));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// the interface is gone without a save, so its changes are too
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	private void add(List<StorageHistory.Change> changes)
	{
		if (changes.isEmpty() || collector.getMemberId() == null)
		{
			return;
		}
		StorageLogData log = collector.shared(Section.STORAGE_LOG, StorageLogData.class);
		if (log == null)
		{
			log = new StorageLogData();
		}
		long now = System.currentTimeMillis();
		for (StorageHistory.Change change : changes)
		{
			log.add(change.getItem(), change.getAmount(), now);
		}
		collector.share(Section.STORAGE_LOG, log);
	}

	private boolean isOpen()
	{
		Widget items = client.getWidget(InterfaceID.SharedBank.ITEMS);
		return items != null && !items.isHidden();
	}

	/**
	 * @return true while the game's "Saving..." message is on screen. Its text can stay behind after it
	 * closes, which would turn later changes into saves if it counted.
	 */
	private boolean savingShown()
	{
		Widget text = client.getWidget(InterfaceID.LoadingIconModal.TEXT);
		return text != null && !text.isHidden() && isSavingText(text.getText());
	}

	/**
	 * @return true if the game's loading message is the one it shows while saving group storage
	 */
	static boolean isSavingText(String text)
	{
		return text != null && text.toLowerCase(Locale.ROOT).contains("saving");
	}
}

package com.homebase.sync;

import com.google.gson.JsonElement;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Every client's local copy of the group's data. Thread safe.
 */
public class GroupStore
{
	private final Map<String, SyncRecord> records = new HashMap<>();
	private final List<Listener> listeners = new CopyOnWriteArrayList<>();

	/**
	 * Told about every record stored, along with the copy it replaced.
	 */
	public interface Listener
	{
		/**
		 * @param previous the copy we had before, or null if this key is new to us
		 */
		void changed(SyncRecord previous, SyncRecord current);
	}

	public void addListener(Listener listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Listener listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Store a record if it is newer than the copy we have.
	 *
	 * @return true if the record was stored
	 */
	public boolean offer(SyncRecord record)
	{
		SyncRecord previous;
		synchronized (this)
		{
			previous = records.get(record.getKey());
			if (!record.supersedes(previous))
			{
				return false;
			}
			records.put(record.getKey(), record);
		}
		notifyListeners(previous, record);
		return true;
	}

	/**
	 * Write a new version of a key, guaranteed to be newer than any copy we have seen.
	 *
	 * @return the record written, or null if the data is unchanged
	 */
	public SyncRecord write(String key, String author, JsonElement data, boolean deleted, long now)
	{
		SyncRecord record;
		SyncRecord current;
		synchronized (this)
		{
			current = records.get(key);
			if (current != null && current.isDeleted() == deleted && current.getAuthor().equals(author)
				&& (deleted || current.getData().equals(data)))
			{
				return null;
			}
			long version = current == null ? now : Math.max(now, current.getVersion() + 1);
			record = new SyncRecord(key, version, author, deleted, deleted ? null : data);
			records.put(key, record);
		}
		notifyListeners(current, record);
		return record;
	}

	/**
	 * @return the record for a key, or null if missing or deleted
	 */
	public synchronized SyncRecord get(String key)
	{
		SyncRecord record = records.get(key);
		return record == null || record.isDeleted() ? null : record;
	}

	/**
	 * @return live records whose key starts with the prefix
	 */
	public synchronized List<SyncRecord> withPrefix(String prefix)
	{
		List<SyncRecord> out = new ArrayList<>();
		for (SyncRecord record : records.values())
		{
			if (!record.isDeleted() && record.getKey().startsWith(prefix))
			{
				out.add(record);
			}
		}
		return out;
	}

	/**
	 * @return every record including tombstones, for saving to disk
	 */
	public synchronized List<SyncRecord> all()
	{
		return new ArrayList<>(records.values());
	}

	/**
	 * @return key to version for everything we hold, which is what we tell peers we have
	 */
	public synchronized Map<String, Long> versions()
	{
		Map<String, Long> out = new HashMap<>(records.size());
		for (SyncRecord record : records.values())
		{
			out.put(record.getKey(), record.getVersion());
		}
		return out;
	}

	/**
	 * @return records we hold that the peer is missing or has an older copy of
	 */
	public synchronized List<SyncRecord> newerThan(Map<String, Long> peer)
	{
		List<SyncRecord> out = new ArrayList<>();
		for (SyncRecord record : records.values())
		{
			Long theirs = peer.get(record.getKey());
			if (theirs == null || record.getVersion() > theirs)
			{
				out.add(record);
			}
		}
		return out;
	}

	/**
	 * @return true if the peer has any key we are missing or hold an older copy of
	 */
	public synchronized boolean isBehind(Map<String, Long> peer)
	{
		for (Map.Entry<String, Long> entry : peer.entrySet())
		{
			SyncRecord ours = records.get(entry.getKey());
			if (entry.getValue() != null && (ours == null || entry.getValue() > ours.getVersion()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Forget tombstones older than the cutoff.
	 *
	 * @return number of tombstones removed
	 */
	public synchronized int purgeDeleted(long cutoff)
	{
		int before = records.size();
		records.values().removeIf(record -> record.isDeleted() && record.getVersion() < cutoff);
		return before - records.size();
	}

	private void notifyListeners(SyncRecord previous, SyncRecord current)
	{
		for (Listener listener : listeners)
		{
			listener.changed(previous, current);
		}
	}
}

package com.homebase.sync;

/**
 * Record keys. Every key belongs to one of three namespaces:
 * <ul>
 *     <li>{@code m:<memberId>:<section>} - data owned by one member, only that member may write it</li>
 *     <li>{@code g:<name>} - data about the group as a whole, such as the group storage</li>
 *     <li>{@code s:<type>:<id>} - shared items any member can edit, such as requests and goals</li>
 * </ul>
 */
public final class Keys
{
	static final String MEMBER = "m:";
	static final String GROUP = "g:";
	static final String SHARED = "s:";
	private static final int MAX_KEY_LENGTH = 128;

	private Keys()
	{
	}

	public static String member(String memberId, String section)
	{
		return MEMBER + memberId + ':' + section;
	}

	public static String group(String name)
	{
		return GROUP + name;
	}

	public static String shared(String type, String id)
	{
		return SHARED + type + ':' + id;
	}

	public static String sharedPrefix(String type)
	{
		return SHARED + type + ':';
	}

	/**
	 * @return the owning member of a member key, or null for any other key
	 */
	public static String memberOf(String key)
	{
		if (!key.startsWith(MEMBER))
		{
			return null;
		}
		int end = key.indexOf(':', MEMBER.length());
		return end < 0 ? null : key.substring(MEMBER.length(), end);
	}

	/**
	 * @return the section of a member key, or null for any other key
	 */
	public static String sectionOf(String key)
	{
		if (!key.startsWith(MEMBER))
		{
			return null;
		}
		int end = key.indexOf(':', MEMBER.length());
		return end < 0 ? null : key.substring(end + 1);
	}

	/**
	 * @return true if the key is in one of the namespaces and not too long
	 */
	public static boolean isValid(String key)
	{
		if (key == null || key.isEmpty() || key.length() > MAX_KEY_LENGTH)
		{
			return false;
		}
		if (key.startsWith(MEMBER))
		{
			return memberOf(key) != null;
		}
		return key.startsWith(GROUP) || key.startsWith(SHARED);
	}
}

package com.homebase.sync;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;

/**
 * Records waiting to be broadcast to the party.
 * <p>
 * When several online members all hold data a newcomer is missing, each of them queues it with a small
 * random delay. Whoever's delay runs out first sends it, and everyone else sees that broadcast and drops
 * their own copy instead of sending a duplicate.
 */
public class OutboundQueue
{
	private static final class Pending
	{
		final SyncRecord record;
		final long dueAt;

		Pending(SyncRecord record, long dueAt)
		{
			this.record = record;
			this.dueAt = dueAt;
		}
	}

	private final Map<String, Pending> pending = new LinkedHashMap<>();

	public synchronized void offer(SyncRecord record, long dueAt)
	{
		Pending existing = pending.get(record.getKey());
		if (existing == null)
		{
			pending.put(record.getKey(), new Pending(record, dueAt));
			return;
		}
		SyncRecord newest = record.supersedes(existing.record) ? record : existing.record;
		pending.put(record.getKey(), new Pending(newest, Math.min(dueAt, existing.dueAt)));
	}

	/**
	 * Someone broadcast a record, so we no longer need to send our copy if it is the same or older.
	 */
	public synchronized void seen(SyncRecord record)
	{
		Pending existing = pending.get(record.getKey());
		if (existing != null && !existing.record.supersedes(record))
		{
			pending.remove(record.getKey());
		}
	}

	/**
	 * Remove and return records that are due, up to roughly {@code budget} in size. At least one due
	 * record is always returned so that a single oversized record can't block the queue.
	 */
	public synchronized List<SyncRecord> takeDue(long now, int budget, ToIntFunction<SyncRecord> sizer)
	{
		List<SyncRecord> out = new ArrayList<>();
		int used = 0;
		for (Iterator<Pending> it = pending.values().iterator(); it.hasNext(); )
		{
			Pending entry = it.next();
			if (entry.dueAt > now)
			{
				continue;
			}
			int size = sizer.applyAsInt(entry.record);
			if (!out.isEmpty() && used + size > budget)
			{
				// left for the next batch, but a smaller record further on may still fit in this one
				continue;
			}
			out.add(entry.record);
			used += size;
			it.remove();
		}
		return out;
	}
}

package com.homebase.sync;

import com.google.gson.JsonElement;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import java.util.function.ToIntFunction;

/**
 * Decides what to send and what to accept. Has no networking of its own: the party transport feeds it
 * peers' messages and broadcasts whatever {@link #takeDue} hands back.
 * <p>
 * The protocol is gossip. Members tell each other which version of every key they hold, and anyone
 * holding a newer copy sends it. Because whoever receives data also holds it, information hops between
 * members who are never online at the same time.
 */
public class SyncEngine
{
	static final long RELAY_DELAY_MIN_MS = 300;
	static final long RELAY_DELAY_MAX_MS = 2500;

	/**
	 * Records stamped further in the future than this are rejected, so a broken clock can't publish a
	 * version nobody can ever replace.
	 */
	static final long MAX_CLOCK_AHEAD_MS = TimeUnit.DAYS.toMillis(1);

	private final GroupStore store;
	private final OutboundQueue queue = new OutboundQueue();
	private final LongSupplier clock;
	private final Random random;

	public SyncEngine(GroupStore store, LongSupplier clock, Random random)
	{
		this.store = store;
		this.clock = clock;
		this.random = random;
	}

	public GroupStore getStore()
	{
		return store;
	}

	/**
	 * @return key to version for everything we hold
	 */
	public Map<String, Long> summary()
	{
		return store.versions();
	}

	/**
	 * A peer told us what it holds. Queue everything we have that is newer.
	 *
	 * @return true if the peer holds something newer than us, meaning we should send our own summary
	 */
	public boolean onSummary(Map<String, Long> peer)
	{
		long now = clock.getAsLong();
		for (SyncRecord record : store.newerThan(peer))
		{
			queue.offer(record, now + relayDelay());
		}
		return store.isBehind(peer);
	}

	/**
	 * A peer broadcast records.
	 *
	 * @return how many were newer than ours and stored
	 */
	public int onRecords(Collection<SyncRecord> records)
	{
		long now = clock.getAsLong();
		int accepted = 0;
		for (SyncRecord record : records)
		{
			if (!isAcceptable(record, now))
			{
				continue;
			}
			queue.seen(record);
			if (store.offer(record))
			{
				accepted++;
			}
		}
		return accepted;
	}

	/**
	 * Load records from the save file. Nothing is queued, since peers will ask for what they lack.
	 */
	public void load(Collection<SyncRecord> records)
	{
		long now = clock.getAsLong();
		for (SyncRecord record : records)
		{
			if (isAcceptable(record, now))
			{
				store.offer(record);
			}
		}
	}

	/**
	 * Write local data and queue it to send straight away. Does nothing if the data is unchanged.
	 *
	 * @return the record written, or null if nothing changed
	 */
	public SyncRecord publish(String key, String author, JsonElement data)
	{
		return write(key, author, data, false);
	}

	public SyncRecord delete(String key, String author)
	{
		return write(key, author, null, true);
	}

	public List<SyncRecord> takeDue(int budget, ToIntFunction<SyncRecord> sizer)
	{
		return queue.takeDue(clock.getAsLong(), budget, sizer);
	}

	private SyncRecord write(String key, String author, JsonElement data, boolean deleted)
	{
		long now = clock.getAsLong();
		SyncRecord record = store.write(key, author, data, deleted, now);
		if (record != null)
		{
			queue.offer(record, now);
		}
		return record;
	}

	static boolean isAcceptable(SyncRecord record, long now)
	{
		if (record == null || !Keys.isValid(record.getKey()) || record.getAuthor() == null || record.getAuthor().isEmpty())
		{
			return false;
		}
		if (record.getVersion() <= 0 || record.getVersion() > now + MAX_CLOCK_AHEAD_MS)
		{
			return false;
		}
		if (!record.isDeleted() && record.getData() == null)
		{
			return false;
		}
		// member data can only be written by the member it belongs to
		String owner = Keys.memberOf(record.getKey());
		return owner == null || owner.equals(record.getAuthor());
	}

	private long relayDelay()
	{
		return RELAY_DELAY_MIN_MS + (long) (random.nextDouble() * (RELAY_DELAY_MAX_MS - RELAY_DELAY_MIN_MS));
	}
}

package com.homebase.sync;

import com.google.gson.JsonElement;
import com.google.gson.annotations.SerializedName;
import lombok.Value;

/**
 * One versioned piece of group data, such as a member's bank or the group storage.
 * <p>
 * The version is the time the data was captured, taken from the clock of whoever wrote it. When two
 * copies of the same key meet, the higher version wins, so data can be relayed between members in any
 * order and everyone ends up with the newest copy.
 */
@Value
public class SyncRecord
{
	@SerializedName("k")
	String key;

	@SerializedName("v")
	long version;

	/**
	 * Member id of whoever wrote this version.
	 */
	@SerializedName("a")
	String author;

	/**
	 * Deleted records are kept as tombstones so that an older copy relayed later can't bring them back.
	 */
	@SerializedName("x")
	boolean deleted;

	@SerializedName("d")
	JsonElement data;

	public boolean supersedes(SyncRecord other)
	{
		if (other == null)
		{
			return true;
		}
		if (version != other.version)
		{
			return version > other.version;
		}
		// same timestamp from two writers: pick one consistently so every client agrees
		return author.compareTo(other.author) > 0;
	}
}

package com.homebase.sync;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;

/**
 * Encoding for party messages and the save file.
 * <p>
 * Party messages are compressed, since banks and collection logs are large and the party service is
 * shared with every other RuneLite user.
 */
public final class WireCodec
{
	public static final Type SUMMARY_TYPE = new TypeToken<Map<String, Long>>()
	{
	}.getType();

	public static final Type RECORDS_TYPE = new TypeToken<List<SyncRecord>>()
	{
	}.getType();

	/**
	 * Refuse to inflate messages beyond this, so a malformed message can't exhaust memory.
	 */
	static final int MAX_INFLATED_BYTES = 4 << 20;

	/**
	 * Deepest nesting allowed in a message. Ours never go past a handful of levels, and Gson reads
	 * nesting by calling itself, so a message nested thousands deep could crash the thread reading it.
	 */
	static final int MAX_DEPTH = 32;

	private static final int SAVE_FORMAT = 1;

	private static final int CHUNK_BYTES = 4096;

	private WireCodec()
	{
	}

	public static String pack(String json)
	{
		byte[] input = json.getBytes(StandardCharsets.UTF_8);
		Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION);
		try
		{
			deflater.setInput(input);
			deflater.finish();
			ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(64, input.length / 4));
			byte[] chunk = new byte[CHUNK_BYTES];
			while (!deflater.finished())
			{
				int length = deflater.deflate(chunk);
				out.write(chunk, 0, length);
			}
			return Base64.getEncoder().encodeToString(out.toByteArray());
		}
		finally
		{
			deflater.end();
		}
	}

	public static String unpack(String packed) throws IOException
	{
		if (packed == null)
		{
			throw new IOException("missing payload");
		}
		byte[] input;
		try
		{
			input = Base64.getDecoder().decode(packed);
		}
		catch (IllegalArgumentException e)
		{
			throw new IOException("bad base64", e);
		}
		Inflater inflater = new Inflater();
		try
		{
			inflater.setInput(input);
			// capped, so a huge payload can't allocate past the limit before a byte is inflated
			ByteArrayOutputStream out = new ByteArrayOutputStream((int) Math.min(input.length * 4L, MAX_INFLATED_BYTES));
			byte[] chunk = new byte[CHUNK_BYTES];
			while (!inflater.finished())
			{
				int length = inflater.inflate(chunk);
				if (length == 0 && (inflater.needsInput() || inflater.needsDictionary()))
				{
					throw new IOException("truncated payload");
				}
				out.write(chunk, 0, length);
				if (out.size() > MAX_INFLATED_BYTES)
				{
					throw new IOException("payload too large");
				}
			}
			String json = new String(out.toByteArray(), StandardCharsets.UTF_8);
			if (nestedTooDeep(json))
			{
				throw new IOException("payload nested too deeply");
			}
			return json;
		}
		catch (DataFormatException e)
		{
			throw new IOException("bad payload", e);
		}
		finally
		{
			inflater.end();
		}
	}

	/**
	 * @return true if the JSON's brackets nest deeper than {@link #MAX_DEPTH}, not counting any inside
	 * strings
	 */
	static boolean nestedTooDeep(String json)
	{
		int depth = 0;
		boolean inString = false;
		for (int i = 0; i < json.length(); i++)
		{
			char c = json.charAt(i);
			if (inString)
			{
				if (c == '\\')
				{
					// skip whatever is escaped, which may be a quote
					i++;
				}
				else if (c == '"')
				{
					inString = false;
				}
			}
			else if (c == '"')
			{
				inString = true;
			}
			else if (c == '[' || c == '{')
			{
				if (++depth > MAX_DEPTH)
				{
					return true;
				}
			}
			else if (c == ']' || c == '}')
			{
				depth--;
			}
		}
		return false;
	}

	private static final class SaveFile
	{
		int format;
		List<SyncRecord> records;
	}

	public static void writeSave(Gson gson, Writer writer, List<SyncRecord> records)
	{
		SaveFile save = new SaveFile();
		save.format = SAVE_FORMAT;
		save.records = records;
		gson.toJson(save, writer);
	}

	/**
	 * @return records from a save file, or null if the file is from an unknown format
	 */
	public static List<SyncRecord> readSave(Gson gson, Reader reader)
	{
		SaveFile save = gson.fromJson(reader, SaveFile.class);
		if (save == null || save.format != SAVE_FORMAT || save.records == null)
		{
			return null;
		}
		return save.records;
	}
}

package com.homebase.tiles;

import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.Section;
import com.homebase.data.TilesData;
import java.util.ArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;

/**
 * Marks tiles for the whole group. Shift + right-click a tile and choose Group mark; everyone in the
 * group sees it in your colour. Tiles in instances are stored at their template location, so a tile
 * marked in one raid shows up in the same spot in everyone's raid.
 */
@Singleton
public class GroupTiles
{
	private static final String MARK = "Group mark";
	private static final String UNMARK = "Group unmark";
	private static final String WALK_HERE = "Walk here";

	private final Client client;
	private final HomebaseConfig config;
	private final LocalCollector collector;

	@Inject
	private GroupTiles(Client client, HomebaseConfig config, LocalCollector collector)
	{
		this.client = client;
		this.config = config;
		this.collector = collector;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.groupTiles() || event.getType() != MenuAction.WALK.getId() || !WALK_HERE.equals(event.getOption())
			|| !client.isKeyPressed(KeyCode.KC_SHIFT) || collector.getMemberId() == null)
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		Tile tile = view == null ? null : view.getSelectedSceneTile();
		if (tile == null)
		{
			return;
		}
		WorldPoint point = templatePoint(tile.getLocalLocation());
		if (point == null)
		{
			return;
		}
		boolean marked = mine().contains(point.getX(), point.getY(), point.getPlane());
		client.getMenu().createMenuEntry(-1)
			.setOption(marked ? UNMARK : MARK)
			.setTarget("Tile")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggle(point));
	}

	/**
	 * Share our tiles again with the new colour. Runs on the client thread.
	 */
	public void colorChanged()
	{
		if (collector.getMemberId() == null)
		{
			return;
		}
		TilesData data = collector.shared(Section.TILES, TilesData.class);
		if (data != null)
		{
			data.setColor(config.tileColor().getRGB() & 0xFFFFFF);
			collector.share(Section.TILES, data);
		}
	}

	private void toggle(WorldPoint point)
	{
		TilesData data = mine();
		data.setColor(config.tileColor().getRGB() & 0xFFFFFF);
		data.toggle(point.getX(), point.getY(), point.getPlane());
		collector.share(Section.TILES, data);
	}

	private TilesData mine()
	{
		TilesData data = collector.shared(Section.TILES, TilesData.class);
		if (data == null)
		{
			data = new TilesData();
		}
		if (data.getTiles() == null)
		{
			data.setTiles(new ArrayList<>());
		}
		return data;
	}

	/**
	 * @return where the tile is in the game's template map, which is where it is in the world unless
	 * we're in an instance
	 */
	private WorldPoint templatePoint(LocalPoint local)
	{
		return local == null ? null : WorldPoint.fromLocalInstance(client, local);
	}
}

package com.homebase.ui;

import java.util.concurrent.TimeUnit;

/**
 * Rough ages such as "5m ago", for when something was last seen or changed.
 */
final class Ago
{
	private Ago()
	{
	}

	/**
	 * @return how long ago the time was, or "never" for 0
	 */
	static String format(long timestamp)
	{
		if (timestamp <= 0)
		{
			return "never";
		}
		long seconds = TimeUnit.MILLISECONDS.toSeconds(System.currentTimeMillis() - timestamp);
		if (seconds < 60)
		{
			return "just now";
		}
		long minutes = seconds / 60;
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		long hours = minutes / 60;
		if (hours < 48)
		{
			return hours + "h ago";
		}
		return hours / 24 + "d ago";
	}
}

