/**
 * One group member: who they are, whether they're online with live bars, and when expanded
 * everything we know about them in rows that open one at a time.
 */
class MemberCard extends JPanel
{
	/**
	 * Gold, for a level 99 and for new collection log slots.
	 */
	private static final Color MAXED = new Color(0xFFD54F);

	/**
	 * The brown of the in-game skills tab.
	 */
	private static final Color SKILL_TILE = new Color(62, 53, 41);

	/**
	 * Diary tiers shortened, so all four fit beside the region's name.
	 */
	private static final String[] TIER_LABELS = {"E", "M", "H", "El"};

	private static final int DIARY_REGION_WIDTH = 100;

	/**
	 * Where text wraps inside an open section, which is indented further than a card's own text.
	 */
	private static final int SECTION_TEXT_WIDTH = Ui.TEXT_WIDTH - 9;

	/**
	 * Newest collection log slots listed above the pages.
	 */
	private static final int RECENT_SLOTS_SHOWN = 5;

	/**
	 * Longest text shown from other players' data: player names, then boss and furniture names, then
	 * quest, collection log page and item names.
	 */
	private static final int MAX_NAME = 20;
	private static final int MAX_SHORT_TEXT = 40;
	private static final int MAX_LONG_TEXT = 60;

	/**
	 * Skills in the order of the in-game skills tab, read across three columns.
	 */
	private static final List<Skill> SKILL_ORDER = Arrays.asList(
		Skill.ATTACK, Skill.HITPOINTS, Skill.MINING,
		Skill.STRENGTH, Skill.AGILITY, Skill.SMITHING,
		Skill.DEFENCE, Skill.HERBLORE, Skill.FISHING,
		Skill.RANGED, Skill.THIEVING, Skill.COOKING,
		Skill.PRAYER, Skill.CRAFTING, Skill.FIREMAKING,
		Skill.MAGIC, Skill.FLETCHING, Skill.WOODCUTTING,
		Skill.RUNECRAFT, Skill.SLAYER, Skill.FARMING,
		Skill.CONSTRUCTION, Skill.HUNTER, Skill.SAILING);

	/**
	 * Shared by every card so open sections survive the panel being rebuilt.
	 */
	static class Context
	{
		final ItemSprites itemSprites;
		final SkillIconManager skillIconManager;
		final Set<String> openSections;
		final Consumer<String> toggleSection;

		/**
		 * Whether cards show live bars, which the player can turn off.
		 */
		final BooleanSupplier showBars;

		Context(ItemSprites itemSprites, SkillIconManager skillIconManager, Set<String> openSections,
			Consumer<String> toggleSection, BooleanSupplier showBars)
		{
			this.showBars = showBars;
			this.itemSprites = itemSprites;
			this.skillIconManager = skillIconManager;
			this.openSections = openSections;
			this.toggleSection = toggleSection;
		}
	}

	private final JLabel nameLabel;
	private final JLabel statusLabel = Ui.small("", ColorScheme.MEDIUM_GRAY_COLOR);
	private final JPanel bars = new JPanel(new GridLayout(1, 4, 3, 0));
	private final Ui.Meter hpBar = Ui.bar(Ui.HP_FG, Ui.HP_BG);
	private final Ui.Meter prayerBar = Ui.bar(Ui.PRAY_FG, Ui.PRAY_BG);
	private final Ui.Meter runBar = Ui.bar(Ui.RUN_FG, Ui.RUN_BG);
	private final Ui.Meter specBar = Ui.bar(Ui.SPEC_FG, Ui.SPEC_BG);
	private final BooleanSupplier showBars;
	private final ProfileData profile;
	private final long profileUpdatedAt;

	MemberCard(String memberId, GroupView view, boolean expanded, Runnable onToggle, Context context)
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		showBars = context.showBars;

		profile = view.get(memberId, Section.PROFILE, ProfileData.class);
		profileUpdatedAt = view.updatedAt(memberId, Section.PROFILE);
		SkillsData skills = view.get(memberId, Section.SKILLS, SkillsData.class);

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		top.setBorder(new EmptyBorder(7, 8, 7, 8));
		Ui.hover(top, ColorScheme.DARKER_GRAY_COLOR, ColorScheme.DARKER_GRAY_HOVER_COLOR);
		Ui.clickable(top, onToggle);
		top.setToolTipText(expanded ? "Click to close" : "Click for everything we know about them");

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		nameLabel = Ui.title(profile == null ? "Unknown" : Clean.text(profile.getName(), MAX_NAME));
		nameLabel.setIconTextGap(6);
		header.add(nameLabel, BorderLayout.CENTER);
		header.add(statusLabel, BorderLayout.EAST);
		top.add(align(header));

		if (skills != null)
		{
			int combat = Experience.getCombatLevel(skills.getLevel(Skill.ATTACK), skills.getLevel(Skill.STRENGTH),
				skills.getLevel(Skill.DEFENCE), skills.getLevel(Skill.HITPOINTS), skills.getLevel(Skill.MAGIC),
				skills.getLevel(Skill.RANGED), skills.getLevel(Skill.PRAYER));
			JLabel levels = Ui.small("Combat " + combat + "  ·  Total " + QuantityFormatter.formatNumber(skills.getTotalLevel()),
				ColorScheme.LIGHT_GRAY_COLOR);
			// lines up with the name, past the online dot
			levels.setBorder(new EmptyBorder(2, 13, 0, 0));
			top.add(align(levels));
		}

		bars.setOpaque(false);
		bars.setBorder(new EmptyBorder(6, 0, 0, 0));
		hpBar.setToolTipText("Hitpoints");
		prayerBar.setToolTipText("Prayer");
		runBar.setToolTipText("Run energy");
		specBar.setToolTipText("Special attack");
		bars.add(hpBar);
		bars.add(prayerBar);
		bars.add(runBar);
		bars.add(specBar);
		top.add(align(bars));
		add(top, BorderLayout.NORTH);

		if (expanded)
		{
			add(buildDetails(memberId, view, skills, context), BorderLayout.CENTER);
		}

		updateLive(null, false, false);
	}

	String getMemberName()
	{
		return profile == null ? null : profile.getName();
	}

	/**
	 * Refresh the parts that change every tick for online members.
	 *
	 * @param live their party data, or null if they aren't in the party right now
	 * @param isLocal true if this card is the logged in player
	 * @param knowsSpec true if their special attack has arrived, which an older version of the plugin
	 * may never send
	 */
	void updateLive(PartyMember live, boolean isLocal, boolean knowsSpec)
	{
		boolean online = isLocal || (live != null && live.isLoggedIn());
		nameLabel.setIcon(new Ui.Dot(online ? Ui.ONLINE : Ui.AWAY));
		if (online)
		{
			int world = profile == null ? 0 : profile.getWorld();
			statusLabel.setText(world > 0 ? "World " + world : "Online");
			statusLabel.setForeground(Ui.ONLINE);
		}
		else
		{
			statusLabel.setText("Seen " + Ago.format(profileUpdatedAt));
			statusLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		}

		if (showBars.getAsBoolean() && live != null && live.isLoggedIn() && live.getStatBase(Skill.HITPOINTS) > 0)
		{
			int hp = live.getStatBoost(Skill.HITPOINTS);
			int maxHp = live.getStatBase(Skill.HITPOINTS);
			int prayer = live.getStatBoost(Skill.PRAYER);
			int maxPrayer = live.getStatBase(Skill.PRAYER);
			hpBar.set(hp, maxHp, hp + "/" + maxHp);
			prayerBar.set(prayer, maxPrayer, prayer + "/" + maxPrayer);
			runBar.set(live.getRunEnergy(), 100, live.getRunEnergy() + "%");
			specBar.set(knowsSpec ? live.getSpecEnergy() : 0, 100, knowsSpec ? live.getSpecEnergy() + "%" : "-");
			bars.setVisible(true);
		}
		else
		{
			bars.setVisible(false);
		}
	}

	private static JPanel buildDetails(String memberId, GroupView view, SkillsData skills, Context context)
	{
		JPanel details = new JPanel();
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		details.setBorder(new EmptyBorder(0, 8, 8, 8));

		if (skills != null && addFoldRow(details, "Skills", "Total " + QuantityFormatter.formatNumber(skills.getTotalLevel())
			+ "  ·  " + Ago.format(view.updatedAt(memberId, Section.SKILLS)), memberId + ":" + Section.SKILLS.getKey(), context))
		{
			addContent(details, skillGrid(skills, context.skillIconManager));
		}

		addQuests(details, memberId, view, context);
		addDiaries(details, memberId, view, context);
		addCombatAchievements(details, memberId, view);
		addCollectionLog(details, memberId, view, context);
		addKillCounts(details, memberId, view, context);
		addHouse(details, memberId, view, context);
		details.add(Box.createVerticalStrut(6));
		addItems(details, "Inventory", ItemGrid::itemCount, memberId, Section.INVENTORY, view, context);
		addItems(details, "Equipment", count -> count + " worn", memberId, Section.EQUIPMENT, view, context);
		addCollapsible(details, "Bank", memberId, Section.BANK, view, context);
		addCollapsible(details, "Seed vault", memberId, Section.SEED_VAULT, view, context);
		addCollapsible(details, "Looting bag", memberId, Section.LOOTING_BAG, view, context);

		Ui.alignChildrenLeft(details);
		return details;
	}

	/**
	 * A row that opens a section, with a little space under it.
	 */
	static void addSectionRow(JPanel parent, String title, String summary, String id, Context context)
	{
		parent.add(Ui.sectionRow(title, summary, context.openSections.contains(id), () -> context.toggleSection.accept(id)));
		parent.add(Box.createVerticalStrut(2));
	}

	/**
	 * A row for a section that starts open and can be folded away, such as skills. Folding is
	 * remembered while RuneLite is open.
	 *
	 * @return true if the section is open
	 */
	static boolean addFoldRow(JPanel parent, String title, String summary, String id, Context context)
	{
		String folded = id + ":folded";
		boolean open = !context.openSections.contains(folded);
		parent.add(Ui.sectionRow(title, summary, open, () -> context.toggleSection.accept(folded)));
		parent.add(Box.createVerticalStrut(2));
		return open;
	}

	/**
	 * What an open section shows, indented a little under its row.
	 */
	static void addContent(JPanel parent, JComponent content)
	{
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setOpaque(false);
		wrap.setBorder(new EmptyBorder(2, 6, 6, 6));
		wrap.add(content, BorderLayout.CENTER);
		parent.add(wrap);
	}

	/**
	 * The inventory or worn equipment, which are small enough to start open.
	 */
	private static void addItems(JPanel parent, String title, IntFunction<String> countText, String memberId, Section section,
		GroupView view, Context context)
	{
		ItemsData items = view.get(memberId, section, ItemsData.class);
		if (items == null)
		{
			return;
		}
		List<Item> slots = items.toItems();
		int count = ItemGrid.countFilled(slots);
		if (addFoldRow(parent, title, countText.apply(count) + "  ·  " + Ago.format(view.updatedAt(memberId, section)),
			memberId + ":" + section.getKey(), context) && count > 0)
		{
			parent.add(new ItemGrid(slots, context.itemSprites));
			parent.add(Box.createVerticalStrut(4));
		}
	}

	/**
	 * Big containers start collapsed, so a full bank doesn't bury everything below it.
	 */
	private static void addCollapsible(JPanel parent, String title, String memberId, Section section,
		GroupView view, Context context)
	{
		ItemsData items = view.get(memberId, section, ItemsData.class);
		if (items == null || items.isEmpty())
		{
			return;
		}
		List<Item> slots = items.toItems();
		String id = memberId + ":" + section.getKey();
		addSectionRow(parent, title, ItemGrid.itemCount(ItemGrid.countFilled(slots)) + " · " + Ago.format(view.updatedAt(memberId, section)), id, context);
		if (context.openSections.contains(id))
		{
			parent.add(new ItemGrid(slots, context.itemSprites));
			parent.add(Box.createVerticalStrut(4));
		}
	}

	private static void addQuests(JPanel parent, String memberId, GroupView view, Context context)
	{
		QuestsData quests = view.get(memberId, Section.QUESTS, QuestsData.class);
		if (quests == null || quests.getQuests() == null)
		{
			return;
		}
		int mini = quests.countMiniquests(QuestsData.FINISHED);
		String id = memberId + ":" + Section.QUESTS.getKey();
		addSectionRow(parent, "Quests", quests.count(QuestsData.FINISHED) + " done" + (mini > 0 ? " + " + mini + " mini" : ""), id, context);
		if (!context.openSections.contains(id))
		{
			return;
		}
		TreeMap<String, String> sorted = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Map.Entry<String, String> e : quests.getQuests().entrySet())
		{
			String name = Clean.text(e.getKey(), MAX_LONG_TEXT);
			if (name != null)
			{
				sorted.put(name, e.getValue());
			}
		}
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 1));
		list.setOpaque(false);
		for (Map.Entry<String, String> e : sorted.entrySet())
		{
			boolean done = QuestsData.FINISHED.equals(e.getValue());
			JLabel quest = Ui.small((done ? "✓ " : "… ") + e.getKey() + (QuestsData.isMiniquest(e.getKey()) ? " (mini)" : ""),
				done ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
			list.add(quest);
		}
		addContent(parent, list);
	}

	private static void addDiaries(JPanel parent, String memberId, GroupView view, Context context)
	{
		DiariesData diaries = view.get(memberId, Section.DIARIES, DiariesData.class);
		if (diaries == null || diaries.getDone() == null)
		{
			return;
		}
		String id = memberId + ":" + Section.DIARIES.getKey();
		int total = DiariesData.REGIONS.size() * DiariesData.TIERS.size();
		addSectionRow(parent, "Achievement diaries", diaries.countDone() + "/" + total, id, context);
		if (!context.openSections.contains(id))
		{
			return;
		}
		JPanel grid = new JPanel(new GridLayout(0, 1, 0, 1));
		grid.setOpaque(false);
		for (String region : DiariesData.REGIONS)
		{
			JPanel row = new JPanel(new BorderLayout());
			row.setOpaque(false);
			JLabel name = Ui.small(region, ColorScheme.LIGHT_GRAY_COLOR);
			// a fixed width, so every region's tiers line up in columns
			name.setPreferredSize(new Dimension(DIARY_REGION_WIDTH, name.getPreferredSize().height));
			name.setToolTipText(region);
			row.add(name, BorderLayout.WEST);
			JPanel tiers = new JPanel(new GridLayout(1, DiariesData.TIERS.size(), 2, 0));
			tiers.setOpaque(false);
			for (int tier = 0; tier < DiariesData.TIERS.size(); tier++)
			{
				boolean done = diaries.isDone(region, tier);
				JLabel cell = Ui.small(TIER_LABELS[tier], done ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);
				cell.setHorizontalAlignment(SwingConstants.CENTER);
				cell.setOpaque(true);
				cell.setBackground(done ? ColorScheme.PROGRESS_COMPLETE_COLOR.darker() : ColorScheme.DARK_GRAY_COLOR);
				cell.setToolTipText(region + " " + DiariesData.TIERS.get(tier) + (done ? ": done" : ": not done"));
				tiers.add(cell);
			}
			row.add(tiers, BorderLayout.CENTER);
			grid.add(row);
		}
		addContent(parent, grid);
	}

	private static void addCombatAchievements(JPanel parent, String memberId, GroupView view)
	{
		CombatAchievementsData ca = view.get(memberId, Section.COMBAT_ACHIEVEMENTS, CombatAchievementsData.class);
		if (ca == null)
		{
			return;
		}
		String tier = ca.tierName();
		JPanel row = Ui.infoRow("Combat achievements", ca.getPoints() + " pts" + (tier == null ? "" : " · " + tier));
		row.setToolTipText(ca.getTasks() + " tasks done. " + (tier == null ? "No tier reached yet." : "Highest tier reached: " + tier + "."));
		parent.add(row);
		parent.add(Box.createVerticalStrut(2));
	}

	private static void addCollectionLog(JPanel parent, String memberId, GroupView view, Context context)
	{
		CollectionLogData log = view.get(memberId, Section.COLLECTION_LOG, CollectionLogData.class);
		if (log == null)
		{
			return;
		}
		Map<String, CollectionLogData.Page> pages = log.getPages() == null ? new HashMap<>() : log.getPages();
		List<String> recent = log.getRecent() == null ? new ArrayList<>() : log.getRecent();
		String id = memberId + ":" + Section.COLLECTION_LOG.getKey();
		String counts = log.getObtained() > 0 && log.getTotal() > 0
			? QuantityFormatter.formatNumber(log.getObtained()) + "/" + QuantityFormatter.formatNumber(log.getTotal())
			: "";
		addSectionRow(parent, "Collection log", counts, id, context);
		if (!context.openSections.contains(id))
		{
			return;
		}
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 1));
		list.setOpaque(false);
		int shown = 0;
		for (String item : recent)
		{
			String name = Clean.text(item, MAX_LONG_TEXT);
			if (name != null && shown++ < RECENT_SLOTS_SHOWN)
			{
				list.add(Ui.small("New: " + name, MAXED));
			}
		}
		TreeMap<String, CollectionLogData.Page> sorted = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Map.Entry<String, CollectionLogData.Page> e : pages.entrySet())
		{
			String name = Clean.text(e.getKey(), MAX_LONG_TEXT);
			if (name != null && e.getValue() != null)
			{
				sorted.put(name, e.getValue());
			}
		}
		int listed = 0;
		for (Map.Entry<String, CollectionLogData.Page> e : sorted.entrySet())
		{
			CollectionLogData.Page page = e.getValue();
			int have = page.getItems() == null ? 0 : page.getItems().size();
			if (have == 0)
			{
				// only pages with something on them are worth showing
				continue;
			}
			boolean complete = have >= page.getSize() && page.getSize() > 0;
			JPanel row = valueRow(e.getKey(), have + "/" + page.getSize(), complete ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
			row.setToolTipText("Seen " + Ago.format(page.getSeen()));
			list.add(row);
			listed++;
		}
		if (listed == 0 && recent.isEmpty())
		{
			list.add(Ui.wrapped("Pages appear here once they open their collection log and click Search.", ColorScheme.MEDIUM_GRAY_COLOR, SECTION_TEXT_WIDTH));
		}
		addContent(parent, list);
	}

	private static void addKillCounts(JPanel parent, String memberId, GroupView view, Context context)
	{
		KillCountsData kills = view.get(memberId, Section.KILL_COUNTS, KillCountsData.class);
		if (kills == null || kills.getCounts() == null)
		{
			return;
		}
		List<Map.Entry<String, Integer>> rows = new ArrayList<>();
		for (Map.Entry<String, Integer> e : kills.getCounts().entrySet())
		{
			String name = Clean.text(e.getKey(), MAX_SHORT_TEXT);
			// a collection log page shows "kills: 0" for bosses never fought, which says nothing
			if (name != null && e.getValue() != null && e.getValue() > 0)
			{
				rows.add(new AbstractMap.SimpleEntry<>(name, e.getValue()));
			}
		}
		if (rows.isEmpty())
		{
			return;
		}
		rows.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
		String id = memberId + ":" + Section.KILL_COUNTS.getKey();
		addSectionRow(parent, "Kill counts", rows.size() + (rows.size() == 1 ? " boss" : " bosses"), id, context);
		if (!context.openSections.contains(id))
		{
			return;
		}
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 1));
		list.setOpaque(false);
		for (Map.Entry<String, Integer> e : rows)
		{
			list.add(valueRow(e.getKey(), QuantityFormatter.formatNumber(e.getValue()), Color.WHITE));
		}
		addContent(parent, list);
	}

	private static void addHouse(JPanel parent, String memberId, GroupView view, Context context)
	{
		HouseData house = view.get(memberId, Section.HOUSE, HouseData.class);
		if (house == null)
		{
			return;
		}
		List<String> furniture = house.getFurniture() == null ? new ArrayList<>() : house.getFurniture();
		List<Integer> costumes = house.getCostumes() == null ? new ArrayList<>() : house.getCostumes();
		String id = memberId + ":" + Section.HOUSE.getKey();
		addSectionRow(parent, "House", furniture.size() + " built" + (costumes.isEmpty() ? "" : " · " + costumes.size() + " costumes"), id, context);
		if (!context.openSections.contains(id))
		{
			return;
		}
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);
		for (String item : furniture)
		{
			String name = Clean.text(item, MAX_SHORT_TEXT);
			if (name != null)
			{
				content.add(align(Ui.small(name, ColorScheme.LIGHT_GRAY_COLOR)));
			}
		}
		if (!costumes.isEmpty())
		{
			List<Item> items = new ArrayList<>();
			for (Integer itemId : costumes)
			{
				if (itemId != null && itemId > 0)
				{
					items.add(new Item(itemId, 1));
				}
			}
			content.add(align(caption("Costume room")));
			content.add(align(new ItemGrid(items, context.itemSprites)));
		}
		addContent(parent, content);
	}

	/**
	 * Skills laid out like the in-game skills tab: icon and yellow level on a brown tile, gold at 99.
	 */
	private static JPanel skillGrid(SkillsData skills, SkillIconManager skillIconManager)
	{
		List<Skill> order = new ArrayList<>(SKILL_ORDER);
		for (Skill skill : Skill.values())
		{
			if (!order.contains(skill))
			{
				order.add(skill);
			}
		}

		JPanel grid = new JPanel(new GridLayout(0, 3, 2, 2));
		grid.setOpaque(false);
		for (Skill skill : order)
		{
			int level = skills.getLevel(skill);
			JLabel label = Ui.small(String.valueOf(level), level >= Experience.MAX_REAL_LEVEL ? MAXED : Color.YELLOW);
			label.setIcon(new ImageIcon(skillIconManager.getSkillImage(skill, true)));
			label.setIconTextGap(6);
			label.setOpaque(true);
			label.setBackground(SKILL_TILE);
			label.setBorder(new EmptyBorder(3, 6, 3, 4));
			label.setToolTipText(skill.getName() + ": " + QuantityFormatter.formatNumber(skills.getXp(skill)) + " xp");
			grid.add(label);
		}
		return grid;
	}

	/**
	 * A small grey heading over a block.
	 */
	private static JPanel caption(String title)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(6, 0, 3, 0));
		row.add(Ui.small(title, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.WEST);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private static JPanel valueRow(String name, String value, Color valueColor)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.add(Ui.small(name, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.CENTER);
		row.add(Ui.small(value, valueColor), BorderLayout.EAST);
		return row;
	}

	private static <T extends JComponent> T align(T component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		return component;
	}
}

package com.homebase.ui;

import com.google.common.base.Strings;
import com.homebase.data.RequestData;
import com.homebase.requests.RequestService;
import com.homebase.requests.RequestService.Request;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * Ask the group for items, and take on what others have asked for.
 */
class RequestsView extends JPanel
{
	private static final Color UNCLAIMED = new Color(0xFF9800);
	private static final Color TAKEN = new Color(0x42A5F5);
	private static final Color RESERVED = new Color(0x26C6DA);

	private static final int MAX_QUANTITY = 1_000_000;

	private final RequestService service;
	private final JTextField itemField = new JTextField();
	private final JTextField quantityField = new JTextField("1");
	private final JTextField noteField = new JTextField();
	private final JButton requestButton = Ui.primaryButton("Request", this::submit);
	private final JLabel formHint = Ui.muted("");
	private final JPanel list = new JPanel();

	RequestsView(RequestService service)
	{
		this.service = service;
		setLayout(new BorderLayout());
		setOpaque(false);

		JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
		form.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		form.setBorder(new EmptyBorder(8, 8, 8, 8));

		form.add(Ui.title("Ask the group"));
		form.add(Box.createVerticalStrut(6));
		quantityField.setColumns(4);
		JPanel itemRow = new JPanel(new BorderLayout(4, 0));
		itemRow.setOpaque(false);
		itemRow.add(Ui.field("Item", itemField), BorderLayout.CENTER);
		itemRow.add(Ui.field("Qty", quantityField), BorderLayout.EAST);

		form.add(itemRow);
		form.add(Box.createVerticalStrut(4));
		form.add(Ui.field("Note (optional)", noteField));
		form.add(Box.createVerticalStrut(8));
		itemField.addActionListener(e -> submit());
		JPanel buttonRow = new JPanel(new BorderLayout());
		buttonRow.setOpaque(false);
		buttonRow.add(requestButton, BorderLayout.CENTER);
		form.add(buttonRow);
		form.add(formHint);
		Ui.alignChildrenLeft(form);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		list.setBorder(new EmptyBorder(Ui.GAP, 0, 0, 0));

		add(form, BorderLayout.NORTH);
		add(list, BorderLayout.CENTER);
	}

	/**
	 * Redraw the list. The form is left alone so typing isn't interrupted.
	 */
	void refresh()
	{
		boolean canEdit = service.canEdit();
		requestButton.setEnabled(canEdit);
		formHint.setText(canEdit ? "" : "Log in to make or take on requests.");
		formHint.setVisible(!canEdit);

		list.removeAll();
		List<Request> requests = service.list();
		if (requests.isEmpty())
		{
			list.add(Ui.empty("No requests yet", "Ask for an item above and your group will see it."));
		}
		for (Request request : requests)
		{
			JPanel card = card(request, canEdit);
			card.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(card);
			list.add(Box.createVerticalStrut(Ui.GAP));
		}
		list.revalidate();
		list.repaint();
	}

	int openCount()
	{
		int open = 0;
		for (Request request : service.list())
		{
			if (!request.getData().isDone())
			{
				open++;
			}
		}
		return open;
	}

	private void submit()
	{
		String item = itemField.getText().trim();
		if (item.isEmpty() || !service.canEdit())
		{
			return;
		}
		int quantity;
		try
		{
			quantity = Math.min(MAX_QUANTITY, Math.max(1, Integer.parseInt(quantityField.getText().trim())));
		}
		catch (NumberFormatException e)
		{
			quantity = 1;
		}
		service.create(item, quantity, noteField.getText());
		itemField.setText("");
		quantityField.setText("1");
		noteField.setText("");
	}

	private JPanel card(Request request, boolean canEdit)
	{
		RequestData data = request.getData();
		Color stateColor = data.isDone() ? ColorScheme.PROGRESS_COMPLETE_COLOR
			: data.isReserved() ? RESERVED
			: data.getAssignedTo() != null ? TAKEN : UNCLAIMED;
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// a stripe down the left edge shows where the request stands at a glance
		card.setBorder(new CompoundBorder(BorderFactory.createMatteBorder(0, 3, 0, 0, stateColor), new EmptyBorder(7, 8, 7, 8)));

		JLabel title = Ui.title(data.getQuantity() > 1 ? data.getItem() + " ×" + data.getQuantity() : data.getItem());
		title.setForeground(data.isDone() ? ColorScheme.MEDIUM_GRAY_COLOR : Color.WHITE);
		card.add(title);

		card.add(Ui.small("For " + nameOrSomeone(data.getRequestedByName()) + "  ·  " + Ago.format(data.getCreatedAt()),
			ColorScheme.MEDIUM_GRAY_COLOR));
		if (!Strings.isNullOrEmpty(data.getNote()))
		{
			JLabel note = Ui.wrapped("“" + Ui.escapeHtml(data.getNote()) + "”", ColorScheme.LIGHT_GRAY_COLOR);
			note.setBorder(new EmptyBorder(3, 0, 0, 0));
			card.add(note);
		}

		JLabel status;
		if (data.isDone())
		{
			status = Ui.small("Done by " + nameOrSomeone(data.getAssignedToName()), stateColor);
		}
		else if (data.isReserved())
		{
			// the item waits in group storage, held back from everyone but the requester
			int kept = data.getReservedQuantity();
			status = Ui.small(service.isMe(data.getRequestedBy()) ? kept + " waiting for you in group storage"
				: kept + " in group storage for " + nameOrSomeone(data.getRequestedByName()), stateColor);
		}
		else if (data.getAssignedTo() != null)
		{
			// it's only done when the item turns up, so say how to finish it
			status = service.isMe(data.getAssignedTo())
				? Ui.wrapped("You're on it. Put it in group storage or trade it to "
				+ Ui.escapeHtml(nameOrSomeone(data.getRequestedByName())) + " to finish.", stateColor)
				: Ui.small(nameOrSomeone(data.getAssignedToName()) + " is on it", stateColor);
		}
		else
		{
			status = Ui.small("Nobody has taken this yet", stateColor);
		}
		status.setBorder(new EmptyBorder(4, 0, 0, 0));
		card.add(status);
		if (!data.isDone() && data.getDelivered() > 0)
		{
			card.add(Ui.small(data.getDelivered() + " of " + data.asked() + " received", ColorScheme.MEDIUM_GRAY_COLOR));
		}

		if (canEdit)
		{
			JPanel buttons = buttons(request);
			if (buttons != null)
			{
				card.add(buttons);
			}
		}

		Ui.alignChildrenLeft(card);
		// a card of only labels would otherwise be only as wide as its longest line
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * @return what the logged in player can do with the request, or null if nothing
	 */
	private JPanel buttons(Request request)
	{
		RequestData data = request.getData();
		String id = request.getId();
		boolean mine = service.isMe(data.getRequestedBy());
		boolean assignedToMe = service.isMe(data.getAssignedTo());
		JPanel grid = new JPanel(new GridLayout(1, 0, 4, 0));
		grid.setOpaque(false);
		// nobody can mark a request done: that happens when the item is put in group storage and
		// collected, or traded to whoever asked
		if (!data.isDone() && data.getAssignedTo() == null && !mine)
		{
			grid.add(Ui.button("I'll get it", () -> service.claim(id)));
		}
		if (!data.isDone() && !data.isReserved() && assignedToMe)
		{
			grid.add(Ui.button("Give back", () -> service.unclaim(id)));
		}
		if (mine || data.isDone())
		{
			grid.add(Ui.button(data.isDone() ? "Clear" : "Cancel", () -> service.delete(id)));
		}
		if (grid.getComponentCount() == 0)
		{
			return null;
		}
		// the grid gives the buttons equal widths, and the flow layout stops them stretching across the card
		JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(6, 0, 0, 0));
		row.add(grid);
		return row;
	}

	private static String nameOrSomeone(String name)
	{
		return Strings.isNullOrEmpty(name) ? "someone" : name;
	}
}

package com.homebase.ui;

import com.homebase.data.Clean;
import com.homebase.storage.StorageHistory;
import java.awt.Color;
import java.awt.Component;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntConsumer;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * The lists on the storage tab: what's owed back, and who put in or took out what.
 */
final class StorageHistoryView
{
	static final String UNMARK = "Doesn't need returning";

	private static final int MAX_OWED_SHOWN = 8;
	private static final int MAX_LINES_SHOWN = 30;

	/**
	 * Narrower than other wrapped text, since these rows sit inside the storage section and a list.
	 */
	static final int TEXT_WIDTH = Ui.TEXT_WIDTH - 9;

	/**
	 * Longest player and item names shown. Player names come from other members' data.
	 */
	private static final int MAX_NAME = 20;

	private static final String OWED_ID = "storage:owed";
	private static final String HISTORY_ID = "storage:history";

	private static final String WHO_COLOR = ColorUtil.toHexColor(Color.WHITE);
	private static final String TIME_COLOR = ColorUtil.toHexColor(ColorScheme.MEDIUM_GRAY_COLOR);

	private StorageHistoryView()
	{
	}

	/**
	 * Add what's owed back, if anything is.
	 *
	 * @param unmark called when someone says an item doesn't need returning after all, or null if they
	 * can't for now
	 * @param onNamesFound run on the Swing thread once item names we didn't have yet have been looked up
	 */
	static void addOwed(JPanel parent, List<StorageHistory.Owed> owed, IntConsumer unmark, MemberCard.Context context,
		Runnable onNamesFound)
	{
		if (owed.isEmpty() || !MemberCard.addFoldRow(parent, "Owed back", String.valueOf(owed.size()), OWED_ID, context))
		{
			return;
		}
		Set<Integer> shownItems = new HashSet<>();
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		for (StorageHistory.Owed entry : owed.subList(0, Math.min(MAX_OWED_SHOWN, owed.size())))
		{
			shownItems.add(entry.getItem());
			JLabel row = Ui.wrapped(text(entry), ColorScheme.LIGHT_GRAY_COLOR, TEXT_WIDTH);
			// all of an item can be out, so it may not be in the grid to right-click there
			if (unmark != null)
			{
				row.setComponentPopupMenu(Ui.rightClickMenu(UNMARK, () -> unmark.accept(entry.getItem())));
			}
			addRow(list, row);
		}
		if (owed.size() > MAX_OWED_SHOWN)
		{
			addRow(list, Ui.muted("and " + (owed.size() - MAX_OWED_SHOWN) + " more"));
		}
		MemberCard.addContent(parent, list);
		lookUpMissingNames(shownItems, context, onNamesFound);
	}

	/**
	 * Add who put in or took out what, if anyone has changed anything.
	 *
	 * @param onNamesFound run on the Swing thread once item names we didn't have yet have been looked up
	 */
	static void addHistory(JPanel parent, List<StorageHistory.MemberLog> logs, MemberCard.Context context, Runnable onNamesFound)
	{
		List<StorageHistory.Line> lines = StorageHistory.lines(logs);
		if (lines.isEmpty() || !MemberCard.addFoldRow(parent, "History", String.valueOf(lines.size()), HISTORY_ID, context))
		{
			return;
		}
		Set<Integer> shownItems = new HashSet<>();
		List<String> rows = new ArrayList<>();
		for (StorageHistory.Line line : lines.subList(0, Math.min(MAX_LINES_SHOWN, lines.size())))
		{
			shownItems.add(line.getItem());
			rows.add(text(line));
		}
		addRows(parent, rows, lines.size() - rows.size());
		lookUpMissingNames(shownItems, context, onNamesFound);
	}

	private static void lookUpMissingNames(Set<Integer> items, MemberCard.Context context, Runnable onNamesFound)
	{
		// asking only when a name is missing, since the panel is drawn again once they're found
		if (items.stream().anyMatch(item -> ItemNames.known(item) == null))
		{
			context.itemSprites.lookUpNames(items, onNamesFound);
		}
	}

	static void addRows(JPanel parent, List<String> rows)
	{
		addRows(parent, rows, 0);
	}

	private static void addRows(JPanel parent, List<String> rows, int older)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		for (String row : rows)
		{
			addRow(list, Ui.wrapped(row, ColorScheme.LIGHT_GRAY_COLOR, TEXT_WIDTH));
		}
		if (older > 0)
		{
			addRow(list, Ui.muted("and " + older + " older"));
		}
		MemberCard.addContent(parent, list);
	}

	private static void addRow(JPanel list, JLabel row)
	{
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		list.add(row);
	}

	/**
	 * @return the history line as HTML, such as "Mundell took out Shark ×5 · 2h ago"
	 */
	static String text(StorageHistory.Line line)
	{
		return who(line.getWho()) + (line.getAmount() > 0 ? " put in " : " took out ")
			+ thing(line.getItem(), Math.abs((long) line.getAmount())) + when(line.getAt());
	}

	/**
	 * @return the owed line as HTML, such as "Mundell: Shark ×5 · 2h ago"
	 */
	static String text(StorageHistory.Owed owed)
	{
		return who(owed.getWho()) + ": " + thing(owed.getItem(), owed.getAmount()) + when(owed.getAt());
	}

	private static String who(String name)
	{
		String clean = Clean.text(name, MAX_NAME);
		return "<span style='color:" + WHO_COLOR + "'>" + (clean == null ? "Someone" : Ui.escapeHtml(clean)) + "</span>";
	}

	private static String thing(int item, long amount)
	{
		return Ui.escapeHtml(ItemNames.get(item)) + (amount > 1 ? " ×" + QuantityFormatter.formatNumber(amount) : "");
	}

	private static String when(long at)
	{
		return " <nobr><span style='color:" + TIME_COLOR + "'>· " + Ago.format(at) + "</span></nobr>";
	}
}

package com.homebase.ui;

import com.homebase.HomebasePlugin;
import com.homebase.bounties.BountyService;
import com.homebase.data.BountyData;
import com.homebase.data.Clean;
import com.homebase.data.GroupView;
import com.homebase.data.ItemsData;
import com.homebase.data.ProfileData;
import com.homebase.data.Section;
import com.homebase.data.StorageLogData;
import com.homebase.goals.GoalService;
import com.homebase.requests.RequestService;
import com.homebase.storage.ReturnTags;
import com.homebase.storage.StorageHistory;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Item;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.QuantityFormatter;

/**
 * Everything about group storage in one place: what's owed back, what's under a bounty or held for a
 * request, the items themselves and who has put in or taken out what. Bounties and requests are only
 * summed up here, and are changed on their own tabs.
 */
class StorageView extends JPanel
{
	private static final int MAX_NAME = 20;

	private static final String BOUNTIES_ID = "storage:bounties";
	private static final String HELD_ID = "storage:held";
	private static final String ITEMS_ID = "storage:items";

	private final HomebasePlugin plugin;
	private final Supplier<GroupView> views;
	private final ReturnTags returnTags;
	private final BountyService bounties;
	private final GoalService goals;
	private final RequestService requests;
	private final MemberCard.Context context;
	private final Runnable onNamesFound;

	StorageView(HomebasePlugin plugin, Supplier<GroupView> views, ReturnTags returnTags, BountyService bounties,
		GoalService goals, RequestService requests, MemberCard.Context context, Runnable onNamesFound)
	{
		this.plugin = plugin;
		this.views = views;
		this.returnTags = returnTags;
		this.bounties = bounties;
		this.goals = goals;
		this.requests = requests;
		this.context = context;
		this.onNamesFound = onNamesFound;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
	}

	void refresh()
	{
		removeAll();
		GroupView view = views.get();
		ItemsData storage = view == null ? null : view.get(null, Section.GROUP_STORAGE, ItemsData.class);
		if (storage == null)
		{
			add(Ui.empty("Nothing seen yet", "Group Ironman groups see their group storage here once someone in the group "
				+ "has opened it."));
			return;
		}
		List<Item> slots = storage.toItems();
		Map<Integer, Long> marked = returnTags.marked();
		boolean canMark = returnTags.canEdit();
		Map<String, String> names = memberNames(view);
		List<StorageHistory.MemberLog> logs = logs(view);
		List<StorageHistory.Owed> owed = StorageHistory.owed(logs, marked);
		List<String> bountyLines = bountyLines(names);
		List<String> heldLines = heldLines(slots);

		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(7, 8, 8, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		card.add(header(view, ItemGrid.countFilled(slots)));
		String summary = summary(owed.size(), bountyLines.size(), heldLines.size());
		if (summary != null)
		{
			card.add(Ui.wrapped(summary, ColorScheme.LIGHT_GRAY_COLOR, StorageHistoryView.TEXT_WIDTH));
		}

		StorageHistoryView.addOwed(card, owed, canMark ? returnTags::unmark : null, context, onNamesFound);
		if (!bountyLines.isEmpty() && MemberCard.addFoldRow(card, "Bounties", String.valueOf(bountyLines.size()), BOUNTIES_ID, context))
		{
			StorageHistoryView.addRows(card, bountyLines);
		}
		if (!heldLines.isEmpty() && MemberCard.addFoldRow(card, "Held for requests", String.valueOf(heldLines.size()), HELD_ID, context))
		{
			StorageHistoryView.addRows(card, heldLines);
		}

		if (MemberCard.addFoldRow(card, "Items", String.valueOf(ItemGrid.countFilled(slots)), ITEMS_ID, context))
		{
			MemberCard.addContent(card, new ItemGrid(slots, context.itemSprites,
				new ItemGrid.Marks(marked.keySet(), canMark ? returnTags::mark : null, returnTags::unmark)));
			if (marked.isEmpty() && canMark)
			{
				StorageHistoryView.addRows(card, Collections.singletonList(
					"Right-click an item that belongs in storage to have anyone who takes it owe it back."));
			}
		}
		StorageHistoryView.addHistory(card, logs, context, onNamesFound);
		Ui.alignChildrenLeft(card);
		add(card);
	}

	private JPanel header(GroupView view, int filled)
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.add(Ui.title("Group storage"), BorderLayout.CENTER);
		header.add(Ui.small(ItemGrid.itemCount(filled), ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		String author = view.authorOf(null, Section.GROUP_STORAGE);
		ProfileData seenBy = author == null ? null : view.get(author, Section.PROFILE, ProfileData.class);
		header.add(Ui.muted("Seen " + Ago.format(view.updatedAt(null, Section.GROUP_STORAGE))
			+ (seenBy == null ? "" : " by " + Clean.text(seenBy.getName(), MAX_NAME))), BorderLayout.SOUTH);
		header.setBorder(new EmptyBorder(0, 0, 4, 0));
		return header;
	}

	/**
	 * @return a line saying how much is going on, or null if there's nothing to say
	 */
	static String summary(int owed, int bountyCount, int held)
	{
		List<String> parts = new ArrayList<>();
		if (owed > 0)
		{
			parts.add(owed + " owed back");
		}
		if (bountyCount > 0)
		{
			parts.add(bountyCount + (bountyCount == 1 ? " bounty" : " bounties"));
		}
		if (held > 0)
		{
			parts.add(held + " held for requests");
		}
		return parts.isEmpty() ? null : String.join("  ·  ", parts);
	}

	private Map<String, String> memberNames(GroupView view)
	{
		Map<String, String> out = new HashMap<>();
		for (String id : view.memberIds())
		{
			ProfileData profile = view.get(id, Section.PROFILE, ProfileData.class);
			String name = profile != null && plugin.belongsToGroup(profile) ? Clean.text(profile.getName(), MAX_NAME) : null;
			if (name != null)
			{
				out.put(id, name);
			}
		}
		return out;
	}

	private List<StorageHistory.MemberLog> logs(GroupView view)
	{
		List<StorageHistory.MemberLog> logs = new ArrayList<>();
		for (String id : view.memberIds())
		{
			ProfileData profile = view.get(id, Section.PROFILE, ProfileData.class);
			StorageLogData log = view.get(id, Section.STORAGE_LOG, StorageLogData.class);
			if (profile != null && log != null && plugin.belongsToGroup(profile))
			{
				logs.add(new StorageHistory.MemberLog(profile.getName(), log, view.updatedAt(id, Section.STORAGE_LOG)));
			}
		}
		return logs;
	}

	/**
	 * @return a line for each bounty that's in force, such as "Rune scimitar: Mundell, until 70 Attack"
	 */
	private List<String> bountyLines(Map<String, String> names)
	{
		List<String> out = new ArrayList<>();
		for (BountyService.Bounty bounty : bounties.list())
		{
			BountyData data = bounty.getData();
			GoalService.Goal goal = goals.get(data.getGoalId());
			// only someone in the group can set one, and a deleted goal holds nothing back
			if (goal == null || !names.containsKey(data.getCreatedBy()) || data.getLocked() == null)
			{
				continue;
			}
			Set<String> locked = new LinkedHashSet<>();
			for (String id : data.getLocked())
			{
				if (bounties.isLocked(data, id))
				{
					locked.add(names.getOrDefault(id, "someone"));
				}
			}
			String item = data.getItemName();
			out.add(Ui.escapeHtml((item == null ? "item " + data.getItemId() : item)
				+ (data.getQuantity() > 0 ? " ×" + QuantityFormatter.formatNumber(data.getQuantity()) : "")
				+ ": " + (locked.isEmpty() ? "lifted for everyone" : String.join(", ", locked))
				+ ", until " + GoalService.title(goal.getData())));
		}
		return out;
	}

	/**
	 * @return a line for each request waiting in storage, such as "Rune scimitar ×2 for Mundell"
	 */
	private List<String> heldLines(List<Item> slots)
	{
		Set<Integer> items = new LinkedHashSet<>();
		for (Item item : slots)
		{
			if (item != null)
			{
				items.add(item.getId());
			}
		}
		List<String> out = new ArrayList<>();
		for (int item : items)
		{
			for (RequestService.Reservation held : requests.reservationsFor(item))
			{
				String name = held.getItem();
				String who = held.getRequestedByName();
				out.add(Ui.escapeHtml((name == null ? "item " + item : name)
					+ (held.getQuantity() > 1 ? " ×" + QuantityFormatter.formatNumber(held.getQuantity()) : "")
					+ " for " + (who == null ? "someone" : who)));
			}
		}
		return out;
	}
}

package com.homebase.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.PluginErrorPanel;

/**
 * The panel's shared look, so every tab is built from the same few pieces: cards, collapsible
 * section rows, bars, small labels and flat buttons. Colours and spacing follow RuneLite's own panels.
 */
final class Ui
{
	static final Color ONLINE = new Color(0x4CAF50);
	static final Color AWAY = new Color(0x9E9E9E);
	static final Color WARNING = new Color(0xFFA726);

	/**
	 * Bar colours used by RuneLite's Party panel, so members look the same in both.
	 */
	static final Color HP_FG = new Color(0, 146, 54, 230);
	static final Color HP_BG = new Color(102, 15, 16, 230);
	static final Color PRAY_FG = new Color(0, 149, 151);
	static final Color PRAY_BG = Color.BLACK;
	static final Color RUN_FG = new Color(0xC8A01E);
	static final Color RUN_BG = new Color(0x3A3220);
	static final Color SPEC_FG = new Color(0x8E5CC8);
	static final Color SPEC_BG = new Color(0x2B2140);

	/**
	 * Gap between cards.
	 */
	static final int GAP = 6;

	/**
	 * Width HTML labels wrap at, for text across a whole card. Swing draws an HTML width 1.3 times as
	 * wide as it says, so this comes out at 188 pixels of the 189 inside a card. Any wider and the end of
	 * the line is cut off.
	 */
	static final int TEXT_WIDTH = 145;

	private Ui()
	{
	}

	/**
	 * @return an empty card: a darker grey box for one entry in a list
	 */
	static JPanel card()
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(7, 8, 7, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		return card;
	}

	static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		return label;
	}

	static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	static JLabel muted(String text)
	{
		return small(text, ColorScheme.MEDIUM_GRAY_COLOR);
	}

	/**
	 * @return a small label that wraps inside the sidebar. The text is HTML, so anything other players
	 * typed must go through {@link #escapeHtml} first.
	 */
	static JLabel wrapped(String text, Color color)
	{
		return wrapped(text, color, TEXT_WIDTH);
	}

	/**
	 * @return the same, wrapping at a narrower width for text that's indented further than usual
	 */
	static JLabel wrapped(String text, Color color, int width)
	{
		return small("<html><body style='width:" + width + "px'>" + text + "</body></html>", color);
	}

	static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * @return a form input with its small grey label above it
	 */
	static JPanel field(String label, JComponent input)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 2));
		panel.setOpaque(false);
		panel.add(small(label, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.NORTH);
		panel.add(input, BorderLayout.CENTER);
		return panel;
	}

	/**
	 * Line up everything in a vertical box on the left. BoxLayout lines children up by their
	 * alignment, and panels and labels don't agree on it by default.
	 */
	static void alignChildrenLeft(Container parent)
	{
		for (Component child : parent.getComponents())
		{
			((JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
	}

	/**
	 * @return RuneLite's own empty-state message, a title and a line under it
	 */
	static JComponent empty(String title, String description)
	{
		PluginErrorPanel panel = new PluginErrorPanel();
		panel.setContent(title, description);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/**
	 * A row that opens and closes a section: an arrow, a title, and a short summary on the right.
	 * Lights up under the mouse like RuneLite's own list rows.
	 */
	static JPanel sectionRow(String title, String summary, boolean open, Runnable onToggle)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel left = small(title, Color.WHITE);
		left.setIcon(new Chevron(open));
		left.setIconTextGap(6);
		row.add(left, BorderLayout.WEST);
		if (summary != null)
		{
			row.add(small(summary, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		}
		hover(row, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		clickable(row, onToggle);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/**
	 * A plain row with a title on the left and a value on the right, for facts that don't open.
	 */
	static JPanel infoRow(String title, String value)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(small(title, Color.WHITE), BorderLayout.WEST);
		row.add(small(value, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/**
	 * @return a bar like the Party panel's hitpoints and prayer bars, with the numbers on it
	 */
	static Meter bar(Color fg, Color bg)
	{
		return new Meter(fg, bg);
	}

	/**
	 * A filled bar with its numbers centred across the whole bar. RuneLite's own bar gives its middle
	 * label only a third of the width, which cuts "46/50" short in narrow bars.
	 */
	static final class Meter extends JComponent
	{
		private static final int HEIGHT = 16;

		private final Color fg;
		private final Color bg;
		private int value;
		private int max = 1;
		private String label = "";

		Meter(Color fg, Color bg)
		{
			this.fg = fg;
			this.bg = bg;
			setFont(FontManager.getRunescapeSmallFont());
			setPreferredSize(new Dimension(0, HEIGHT));
			setMinimumSize(new Dimension(0, HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		}

		void set(int value, int max, String label)
		{
			this.max = Math.max(1, max);
			this.value = Math.max(0, Math.min(value, this.max));
			this.label = label == null ? "" : label;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			int w = getWidth();
			int h = getHeight();
			g.setColor(bg);
			g.fillRect(0, 0, w, h);
			g.setColor(fg);
			g.fillRect(0, 0, (int) ((long) w * value / max), h);
			g.setFont(getFont());
			FontMetrics fm = g.getFontMetrics();
			int x = (w - fm.stringWidth(label)) / 2;
			int y = (h - fm.getHeight()) / 2 + fm.getAscent();
			// a one pixel shadow, like the game's own text
			g.setColor(Color.BLACK);
			g.drawString(label, x + 1, y + 1);
			g.setColor(Color.WHITE);
			g.drawString(label, x, y);
		}
	}

	/**
	 * @return a flat button in the style of the sidebar, smaller than Swing's default
	 */
	static JButton button(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.setFocusPainted(false);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.DARK_GRAY_COLOR);
		button.setBorder(new EmptyBorder(4, 8, 4, 8));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		hover(button, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		button.addActionListener(e -> action.run());
		return button;
	}

	/**
	 * @return a form's main button, in RuneLite's orange
	 */
	static JButton primaryButton(String text, Runnable action)
	{
		JButton button = new JButton(text);
		primary(button);
		button.addActionListener(e -> action.run());
		return button;
	}

	/**
	 * Style a form's main button: the same flat look in RuneLite's orange.
	 */
	static void primary(JButton button)
	{
		button.setFocusPainted(false);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.BRAND_ORANGE.darker());
		button.setBorder(new EmptyBorder(6, 8, 6, 8));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		hover(button, ColorScheme.BRAND_ORANGE.darker(), ColorScheme.BRAND_ORANGE);
	}

	static JPopupMenu rightClickMenu(String option, Runnable onClick)
	{
		JMenuItem item = new JMenuItem(option);
		item.addActionListener(e -> onClick.run());
		JPopupMenu menu = new JPopupMenu();
		menu.add(item);
		return menu;
	}

	static void clickable(JComponent component, Runnable onClick)
	{
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.run();
			}
		});
	}

	static void hover(JComponent component, Color normal, Color hovered)
	{
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				component.setBackground(hovered);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				component.setBackground(normal);
			}
		});
	}

	/**
	 * A small filled circle, for online and connection status.
	 */
	static final class Dot implements Icon
	{
		private static final int SIZE = 7;

		private final Color color;

		Dot(Color color)
		{
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			g2.fillOval(x, y + 1, SIZE, SIZE);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return 9;
		}
	}

	/**
	 * The arrow on section rows, pointing right when closed and down when open.
	 */
	static final class Chevron implements Icon
	{
		private final boolean open;

		Chevron(boolean open)
		{
			this.open = open;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			int cy = y + 4;
			if (open)
			{
				g2.fillPolygon(new int[]{x, x + 8, x + 4}, new int[]{cy - 2, cy - 2, cy + 3}, 3);
			}
			else
			{
				g2.fillPolygon(new int[]{x + 2, x + 7, x + 2}, new int[]{cy - 4, cy, cy + 4}, 3);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 8;
		}

		@Override
		public int getIconHeight()
		{
			return 9;
		}
	}
}

package com.homebase.ui;

import com.homebase.data.UpdateEntry;
import com.homebase.updates.UpdateTracker;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * What each member has done since your last update: levels gained, quests finished, diaries completed.
 */
class UpdatesView extends JPanel
{
	private static final String BULLET = "<span style='color:#FF9800'>•</span> ";

	private final UpdateTracker tracker;

	UpdatesView(UpdateTracker tracker)
	{
		this.tracker = tracker;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
	}

	void refresh()
	{
		removeAll();
		List<UpdateEntry> entries = tracker.getEntries();
		if (entries.isEmpty())
		{
			add(Ui.empty("Nothing new yet", "When someone in your group levels up, finishes a quest or completes a diary, "
				+ "a summary appears here."));
		}
		for (UpdateEntry entry : entries)
		{
			JPanel card = card(entry);
			card.setAlignmentX(Component.LEFT_ALIGNMENT);
			add(card);
			add(Box.createVerticalStrut(Ui.GAP));
		}
		revalidate();
		repaint();
	}

	private static JPanel card(UpdateEntry entry)
	{
		JPanel card = Ui.card();

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.setBorder(new EmptyBorder(0, 0, 4, 0));
		header.add(Ui.title(entry.getName()), BorderLayout.CENTER);
		header.add(Ui.muted(Ago.format(entry.getTime())), BorderLayout.EAST);
		card.add(header, BorderLayout.NORTH);

		JPanel lines = new JPanel();
		lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
		lines.setOpaque(false);
		for (String change : entry.getChanges())
		{
			// long lines, such as a new collection log item, wrap rather than run off the edge
			JLabel line = Ui.wrapped(BULLET + Ui.escapeHtml(change), ColorScheme.LIGHT_GRAY_COLOR);
			line.setBorder(new EmptyBorder(1, 0, 1, 0));
			line.setAlignmentX(Component.LEFT_ALIGNMENT);
			lines.add(line);
		}
		card.add(lines, BorderLayout.CENTER);
		return card;
	}
}

package com.homebase.updates;

import com.homebase.data.Clean;
import com.homebase.data.FeedData;
import com.homebase.data.QuestsData;
import com.homebase.map.AreaNames;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.QuantityFormatter;

/**
 * Describes what changed between two copies of a member's data, in the words shown to players:
 * "Magic 15 → 32", "completed The Restless Ghost", "completed the Varrock Easy diary".
 */
public final class UpdateDiff
{
	/**
	 * More than this many quests, diaries, slots or bosses in one go are summarised as a count, so a
	 * member who was away for months doesn't fill the chat box.
	 */
	private static final int MAX_LISTED = 4;

	/**
	 * Longest item, monster or place name shown from another member's feed.
	 */
	private static final int MAX_FEED_TEXT = 60;

	private UpdateDiff()
	{
	}

	/**
	 * Skills that went up a level, in the order given.
	 *
	 * @param before skill display name to level, as we had it
	 * @param after skill display name to level, as it is now
	 */
	public static List<String> skills(Map<String, Integer> before, Map<String, Integer> after)
	{
		return skills(before, after, 1);
	}

	/**
	 * Skills that went up a level, leaving out any that are still below {@code minLevel}.
	 */
	public static List<String> skills(Map<String, Integer> before, Map<String, Integer> after, int minLevel)
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : after.entrySet())
		{
			Integer old = before.get(entry.getKey());
			if (old != null && entry.getValue() != null && entry.getValue() > old && entry.getValue() >= minLevel)
			{
				out.add(entry.getKey() + " " + old + " → " + entry.getValue());
			}
		}
		return out;
	}

	/**
	 * Quests finished since before.
	 *
	 * @param before quest name to state, as we had it
	 * @param after quest name to state, as it is now
	 */
	public static List<String> quests(Map<String, String> before, Map<String, String> after)
	{
		List<String> names = new ArrayList<>();
		for (Map.Entry<String, String> entry : after.entrySet())
		{
			if (QuestsData.FINISHED.equals(entry.getValue()) && !QuestsData.FINISHED.equals(before.get(entry.getKey())))
			{
				names.add(entry.getKey());
			}
		}
		Collections.sort(names);
		if (names.size() > MAX_LISTED)
		{
			return Collections.singletonList("completed " + names.size() + " quests");
		}
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			out.add("completed " + name);
		}
		return out;
	}

	/**
	 * Diary tiers completed since before.
	 *
	 * @param before region to completed tier bits, as we had it
	 * @param after region to completed tier bits, as it is now
	 * @param regions region names in display order
	 * @param tiers tier names, one per bit
	 */
	public static List<String> diaries(Map<String, Integer> before, Map<String, Integer> after, List<String> regions, List<String> tiers)
	{
		List<String> names = new ArrayList<>();
		for (String region : regions)
		{
			int was = before.getOrDefault(region, 0);
			int now = after.getOrDefault(region, 0);
			for (int tier = 0; tier < tiers.size(); tier++)
			{
				int bit = 1 << tier;
				if ((now & bit) != 0 && (was & bit) == 0)
				{
					names.add(region + " " + tiers.get(tier));
				}
			}
		}
		if (names.size() > MAX_LISTED)
		{
			return Collections.singletonList("completed " + names.size() + " diaries");
		}
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			out.add("completed the " + name + " diary");
		}
		return out;
	}

	/**
	 * Combat achievement tasks and tiers completed since before. A member we first saw with no tasks
	 * gets no line, since their tasks may simply not have loaded yet.
	 */
	public static List<String> combatAchievements(int tasksBefore, int tasksAfter, int tierBefore, int tierAfter, List<String> tiers)
	{
		List<String> out = new ArrayList<>();
		if (tasksBefore <= 0)
		{
			return out;
		}
		int done = tasksAfter - tasksBefore;
		if (done == 1)
		{
			out.add("completed a combat achievement");
		}
		else if (done > 1)
		{
			out.add("completed " + done + " combat achievements");
		}
		if (tierAfter > tierBefore && tierAfter >= 0 && tierAfter < tiers.size())
		{
			out.add("reached " + tiers.get(tierAfter) + " combat achievements");
		}
		return out;
	}

	/**
	 * Collection log slots filled since before.
	 *
	 * @param recentBefore newest slots as we had them, newest first
	 * @param recentAfter newest slots as they are now, newest first
	 */
	public static List<String> collectionLog(int obtainedBefore, int obtainedAfter, List<String> recentBefore, List<String> recentAfter)
	{
		// the slots newer than the newest one we already knew of
		List<String> names = new ArrayList<>();
		for (String name : recentAfter)
		{
			if (recentBefore.contains(name))
			{
				break;
			}
			names.add(name);
		}
		if (names.isEmpty())
		{
			int filled = obtainedBefore > 0 ? obtainedAfter - obtainedBefore : 0;
			if (filled == 1)
			{
				return Collections.singletonList("filled a collection log slot");
			}
			return filled > 1 ? Collections.singletonList("filled " + filled + " collection log slots") : Collections.emptyList();
		}
		if (names.size() > MAX_LISTED)
		{
			return Collections.singletonList("filled " + names.size() + " collection log slots");
		}
		// in the order they were filled
		Collections.reverse(names);
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			out.add("new collection log slot: " + name);
		}
		return out;
	}

	/**
	 * Bosses killed since before, by name. Bosses we hadn't seen a count for get no line, since the
	 * count may cover years of kills.
	 *
	 * @param before boss name to kill count, as we had it
	 * @param after boss name to kill count, as it is now
	 */
	public static List<String> killCounts(Map<String, Integer> before, Map<String, Integer> after)
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : new TreeMap<>(after).entrySet())
		{
			Integer old = before.get(entry.getKey());
			if (old != null && entry.getValue() != null && entry.getValue() > old)
			{
				out.add(entry.getKey() + " kill count " + old + " → " + entry.getValue());
			}
		}
		if (out.size() > MAX_LISTED)
		{
			return Collections.singletonList("kill counts went up for " + out.size() + " bosses");
		}
		return out;
	}

	/**
	 * Drops, pets and deaths since before.
	 *
	 * @param before the member's feed as we had it
	 * @param after their feed as it is now
	 * @param drops whether to include drops and pets
	 * @param minValue the least a drop must be worth to be included
	 * @param deaths whether to include deaths
	 */
	public static List<String> feed(List<FeedData.Entry> before, List<FeedData.Entry> after, boolean drops, long minValue, boolean deaths)
	{
		long newestSeen = 0;
		for (FeedData.Entry entry : before)
		{
			newestSeen = Math.max(newestSeen, entry.getAt());
		}
		List<String> gotten = new ArrayList<>();
		List<String> pets = new ArrayList<>();
		List<String> died = new ArrayList<>();
		for (FeedData.Entry entry : after)
		{
			if (entry.getAt() <= newestSeen || entry.getType() == null)
			{
				continue;
			}
			switch (entry.getType())
			{
				case FeedData.DROP:
					if (drops && entry.getValue() >= minValue)
					{
						String line = dropLine(entry);
						if (line != null)
						{
							gotten.add(line);
						}
					}
					break;
				case FeedData.PET:
					if (drops)
					{
						pets.add("got a pet!");
					}
					break;
				case FeedData.DEATH:
					if (deaths)
					{
						String place = Clean.text(entry.getName(), MAX_FEED_TEXT);
						died.add(place == null || AreaNames.UNKNOWN.equals(place) ? "died" : "died: " + place);
					}
					break;
				default:
					// a kind of entry from a newer version of the plugin
			}
		}
		List<String> out = new ArrayList<>();
		if (gotten.size() > MAX_LISTED)
		{
			out.add("got " + gotten.size() + " valuable drops");
		}
		else
		{
			out.addAll(gotten);
		}
		// too good to fold into a count
		out.addAll(pets);
		if (died.size() > MAX_LISTED)
		{
			out.add("died " + died.size() + " times");
		}
		else
		{
			out.addAll(died);
		}
		return out;
	}

	private static String dropLine(FeedData.Entry entry)
	{
		String item = Clean.text(entry.getName(), MAX_FEED_TEXT);
		if (item == null)
		{
			return null;
		}
		String source = Clean.text(entry.getSource(), MAX_FEED_TEXT);
		return "got " + (entry.getQuantity() > 1 ? QuantityFormatter.formatNumber(entry.getQuantity()) + " x " : "") + item
			+ (source == null ? "" : " from " + source)
			+ " (" + QuantityFormatter.quantityToStackSize(Math.max(0, entry.getValue())) + ")";
	}

	/**
	 * One line for the chat box, such as "bonscott1: Magic 15 -> 32, completed The Restless Ghost."
	 */
	public static String chatLine(String name, List<String> changes)
	{
		// the chat box font has no arrow
		return name + ": " + String.join(", ", changes).replace("→", "->") + ".";
	}
}

package com.homebase.updates;

import com.google.gson.Gson;
import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.Checkable;
import com.homebase.data.Clean;
import com.homebase.data.CollectionLogData;
import com.homebase.data.CombatAchievementsData;
import com.homebase.data.DiariesData;
import com.homebase.data.FeedData;
import com.homebase.data.KillCountsData;
import com.homebase.data.ProfileData;
import com.homebase.data.QuestsData;
import com.homebase.data.Section;
import com.homebase.data.SkillsData;
import com.homebase.data.UpdateEntry;
import com.homebase.sync.GroupStore;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncRecord;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Turns other members' new data into short summaries of what changed since the copy we had, such as
 * "bonscott1: Magic 15 → 32, completed The Restless Ghost, completed the Varrock Easy diary".
 * <p>
 * Changes for a member are gathered for a few seconds before summarising, so catching up on everything
 * that happened while you were away comes out as one line per member.
 */
@Slf4j
@Singleton
public class UpdateTracker
{
	private static final long GATHER_MS = 3_000;

	/**
	 * Most summaries kept.
	 */
	private static final int MAX_ENTRIES = 100;

	private static final int MAX_PLAYER_NAME = 20;
	private static final int MAX_QUEST_NAME = 60;
	private static final int MAX_ITEM_NAME = 60;
	private static final int MAX_BOSS_NAME = 40;

	private final ScheduledExecutorService executor;
	private final LocalCollector collector;
	private final Gson gson;
	private final HomebaseConfig config;

	/**
	 * Newest first.
	 */
	private final List<UpdateEntry> entries = new CopyOnWriteArrayList<>();
	private final Map<String, Pending> pending = new HashMap<>();
	private final List<Consumer<UpdateEntry>> listeners = new CopyOnWriteArrayList<>();

	private volatile GroupStore store;

	/**
	 * A member's records as they were before the first change in the current batch, and the batch timer.
	 */
	private static final class Pending
	{
		final Map<String, SyncRecord> before = new HashMap<>();
		ScheduledFuture<?> timer;
	}

	@Inject
	private UpdateTracker(ScheduledExecutorService executor, LocalCollector collector, Gson gson, HomebaseConfig config)
	{
		this.executor = executor;
		this.collector = collector;
		this.gson = gson;
		this.config = config;
	}

	public void addListener(Consumer<UpdateEntry> listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Consumer<UpdateEntry> listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Switch to a group's store, with the summaries saved for it.
	 */
	public synchronized void setGroup(GroupStore store, List<UpdateEntry> saved)
	{
		this.store = store;
		for (Pending p : pending.values())
		{
			if (p.timer != null)
			{
				p.timer.cancel(false);
			}
		}
		pending.clear();
		entries.clear();
		if (saved != null)
		{
			for (UpdateEntry entry : saved)
			{
				// summaries from earlier sessions were already seen
				entry.setAnnounced(true);
				entries.add(entry);
			}
		}
	}

	/**
	 * @return summaries, newest first
	 */
	public List<UpdateEntry> getEntries()
	{
		return Collections.unmodifiableList(entries);
	}

	/**
	 * @return summaries not yet shown in chat, oldest first, now marked as shown
	 */
	public List<UpdateEntry> takeUnannounced()
	{
		List<UpdateEntry> out = new ArrayList<>();
		for (UpdateEntry entry : entries)
		{
			if (!entry.isAnnounced())
			{
				entry.setAnnounced(true);
				out.add(0, entry);
			}
		}
		return out;
	}

	/**
	 * A record was stored. Called from the group store, on any thread.
	 */
	public void onRecordChanged(SyncRecord previous, SyncRecord current)
	{
		if (previous == null || previous.isDeleted() || current.isDeleted())
		{
			// the first copy we see of someone has nothing to compare against
			return;
		}
		String memberId = Keys.memberOf(current.getKey());
		String section = Keys.sectionOf(current.getKey());
		if (memberId == null || memberId.equals(collector.getMemberId()) || !isTracked(section))
		{
			return;
		}

		synchronized (this)
		{
			Pending p = pending.computeIfAbsent(memberId, k -> new Pending());
			p.before.putIfAbsent(section, previous);
			if (p.timer != null)
			{
				p.timer.cancel(false);
			}
			p.timer = executor.schedule(() -> summarise(memberId), GATHER_MS, TimeUnit.MILLISECONDS);
		}
	}

	private void summarise(String memberId)
	{
		Map<String, SyncRecord> before;
		GroupStore store;
		synchronized (this)
		{
			Pending p = pending.remove(memberId);
			store = this.store;
			if (p == null || store == null)
			{
				return;
			}
			before = p.before;
		}

		List<String> changes = describeChanges(memberId, before, store);
		if (changes.isEmpty())
		{
			return;
		}
		ProfileData profile = decodeCurrent(store, memberId, Section.PROFILE, ProfileData.class);
		String name = profile == null ? null : Clean.text(profile.getName(), MAX_PLAYER_NAME);
		UpdateEntry entry = new UpdateEntry(memberId, name == null ? "Someone" : name, System.currentTimeMillis(), changes, false);
		synchronized (this)
		{
			if (store != this.store)
			{
				// switched group while this was being worked out
				return;
			}
			entries.add(0, entry);
			while (entries.size() > MAX_ENTRIES)
			{
				entries.remove(entries.size() - 1);
			}
		}
		log.debug("Update for {}: {}", entry.getName(), changes);
		for (Consumer<UpdateEntry> listener : listeners)
		{
			listener.accept(entry);
		}
	}

	/**
	 * @return what changed in each section, from the copy we had before the batch to the one in the
	 * store now
	 */
	private List<String> describeChanges(String memberId, Map<String, SyncRecord> before, GroupStore store)
	{
		List<String> changes = new ArrayList<>();
		SyncRecord skillsBefore = before.get(Section.SKILLS.getKey());
		if (skillsBefore != null && config.updateLevels())
		{
			changes.addAll(UpdateDiff.skills(
				levels(decode(skillsBefore, SkillsData.class)),
				levels(decodeCurrent(store, memberId, Section.SKILLS, SkillsData.class)),
				config.updateMinLevel()));
		}
		SyncRecord questsBefore = before.get(Section.QUESTS.getKey());
		if (questsBefore != null && config.updateQuests())
		{
			changes.addAll(UpdateDiff.quests(
				quests(decode(questsBefore, QuestsData.class)),
				quests(decodeCurrent(store, memberId, Section.QUESTS, QuestsData.class))));
		}
		SyncRecord diariesBefore = before.get(Section.DIARIES.getKey());
		if (diariesBefore != null && config.updateQuests())
		{
			changes.addAll(UpdateDiff.diaries(
				diaries(decode(diariesBefore, DiariesData.class)),
				diaries(decodeCurrent(store, memberId, Section.DIARIES, DiariesData.class)),
				DiariesData.REGIONS, DiariesData.TIERS));
		}
		SyncRecord caBefore = before.get(Section.COMBAT_ACHIEVEMENTS.getKey());
		if (caBefore != null && config.updateQuests())
		{
			CombatAchievementsData was = decode(caBefore, CombatAchievementsData.class);
			CombatAchievementsData now = decodeCurrent(store, memberId, Section.COMBAT_ACHIEVEMENTS, CombatAchievementsData.class);
			if (was != null && now != null)
			{
				changes.addAll(UpdateDiff.combatAchievements(was.getTasks(), now.getTasks(), was.getTier(), now.getTier(),
					CombatAchievementsData.TIERS));
			}
		}
		SyncRecord logBefore = before.get(Section.COLLECTION_LOG.getKey());
		if (logBefore != null && config.updateCollectionLog())
		{
			CollectionLogData was = decode(logBefore, CollectionLogData.class);
			CollectionLogData now = decodeCurrent(store, memberId, Section.COLLECTION_LOG, CollectionLogData.class);
			if (was != null && now != null)
			{
				changes.addAll(UpdateDiff.collectionLog(was.getObtained(), now.getObtained(), itemNames(was.getRecent()),
					itemNames(now.getRecent())));
			}
		}
		SyncRecord killsBefore = before.get(Section.KILL_COUNTS.getKey());
		if (killsBefore != null && config.updateKillCounts())
		{
			changes.addAll(UpdateDiff.killCounts(
				kills(decode(killsBefore, KillCountsData.class)),
				kills(decodeCurrent(store, memberId, Section.KILL_COUNTS, KillCountsData.class))));
		}
		SyncRecord feedBefore = before.get(Section.FEED.getKey());
		if (feedBefore != null)
		{
			changes.addAll(UpdateDiff.feed(
				feed(decode(feedBefore, FeedData.class)),
				feed(decodeCurrent(store, memberId, Section.FEED, FeedData.class)),
				config.updateDrops(), config.dropMinValue(), config.updateDeaths()));
		}
		return changes;
	}

	private static boolean isTracked(String section)
	{
		return Section.SKILLS.getKey().equals(section) || Section.QUESTS.getKey().equals(section)
			|| Section.DIARIES.getKey().equals(section) || Section.COMBAT_ACHIEVEMENTS.getKey().equals(section)
			|| Section.COLLECTION_LOG.getKey().equals(section) || Section.KILL_COUNTS.getKey().equals(section)
			|| Section.FEED.getKey().equals(section);
	}

	private <T> T decodeCurrent(GroupStore store, String memberId, Section section, Class<T> type)
	{
		return decode(store.get(section.keyFor(memberId)), type);
	}

	private <T> T decode(SyncRecord record, Class<T> type)
	{
		if (record == null || record.getData() == null)
		{
			return null;
		}
		try
		{
			return Checkable.checked(gson.fromJson(record.getData(), type));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static Map<String, Integer> levels(SkillsData skills)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		if (skills != null && skills.getXp() != null)
		{
			for (Skill skill : Skill.values())
			{
				if (skills.getXp().containsKey(skill.name()))
				{
					out.put(skill.getName(), skills.getLevel(skill));
				}
			}
		}
		return out;
	}

	private static Map<String, String> quests(QuestsData quests)
	{
		Map<String, String> out = new HashMap<>();
		if (quests != null && quests.getQuests() != null)
		{
			for (Map.Entry<String, String> e : quests.getQuests().entrySet())
			{
				String name = Clean.text(e.getKey(), MAX_QUEST_NAME);
				if (name != null)
				{
					out.put(name, e.getValue());
				}
			}
		}
		return out;
	}

	/**
	 * Item names written by other players' clients, cleaned before they're shown.
	 */
	private static List<String> itemNames(List<String> raw)
	{
		List<String> out = new ArrayList<>();
		if (raw != null)
		{
			for (String name : raw)
			{
				String clean = Clean.text(name, MAX_ITEM_NAME);
				if (clean != null)
				{
					out.add(clean);
				}
			}
		}
		return out;
	}

	private static Map<String, Integer> kills(KillCountsData kills)
	{
		Map<String, Integer> out = new HashMap<>();
		if (kills != null && kills.getCounts() != null)
		{
			for (Map.Entry<String, Integer> e : kills.getCounts().entrySet())
			{
				String name = Clean.text(e.getKey(), MAX_BOSS_NAME);
				if (name != null && e.getValue() != null)
				{
					out.put(name, e.getValue());
				}
			}
		}
		return out;
	}

	private static List<FeedData.Entry> feed(FeedData feed)
	{
		return feed == null ? Collections.emptyList() : feed.getEntries();
	}

	private static Map<String, Integer> diaries(DiariesData diaries)
	{
		return diaries == null || diaries.getDone() == null ? Collections.emptyMap() : diaries.getDone();
	}
}

package com.homebase;

