	}

	@Test
	public void someoneOutsideTheGroupInThePartyStopsEveryoneUntilTheyLeave()
	{
		SimulatedClient mallory = party.outsider("Mallory");
		connect(alice, bob);
		aliceSetsABountyOnCoal();
		party.run(5 * SECOND);
		bob.disconnect();

