	@Test
	public void aBountyFromSomeoneWithNoProfileIsListedButHoldsNothingBack()
	{
		connect(alice, bob);
		party.run(5 * SECOND);
		String goal = goalFrom(alice);
		party.run(5 * SECOND);

		BountyData data = new BountyData();
		data.setItemId(COAL);
		data.setItemName("Coal");
		data.setGoalId(goal);
		data.setLocked(Collections.singletonList(bob.id()));
