		party.run(5 * SECOND);
		String bounty = bountyId(bob, COAL);
		alice.disconnect();
		bob.disconnect();

		// something Alice deleted, and something she changed, before going for good
		alice.connect();
		bob.connect();
		party.run(CATCH_UP);
		alice.bounties().delete(bounty);
		alice.requests().claim(ids[1]);
		party.run(5 * SECOND);
		alice.disconnect();

		carol.connect();
		party.run(CATCH_UP);
