/**
 * One member's RuneLite: the plugin's real sync, services and collector together with RuneLite's real party
 * service, websocket client, party data and event bus. Only the game and the disk are faked. It's wired up
 * the way {@link HomebasePlugin} does it, leaving out the panel and overlays, which need a game to draw on.
 * <p>
 * The sync reads the wall clock for its own short waits, such as the gap between summaries. Those are moved
 * back as simulated time passes, so they run out as they would in play.
 */
final class SimulatedClient
{
	private static final long TICK_MS = 600;
	private static final long FLUSH_MS = 1_000;
	private static final long SAVE_MS = 30_000;
	private static final long TOMBSTONE_LIFETIME_MS = TimeUnit.DAYS.toMillis(60);

	private final SimulatedParty party;
	private final Random random;
	private final Map<Skill, Integer> xp = new HashMap<>();
	private final List<Consumer<SimulatedClient>> onOpen = new ArrayList<>();

	private final Gson gson = RuneLiteAPI.GSON;

	private String name;
	private long accountHash;
	private String savedCopy;
	private boolean running;
	private GameState gameState = GameState.LOGGED_IN;
	private long clockAheadMs;
	private String secret;
	private String passphrase;
	private int tickCount;
	private long tickTimer;
	private long flushTimer;
	private long saveTimer;

	private Client client;
	private Injector injector;
	private EventBus bus;
	private WSClient wsClient;
	private PartyService partyService;
	private ClientThread clientThread;
	private GroupSync groupSync;
	private LiveSharing liveSharing;
	private Presence presence;
	private LocalCollector collector;
	private GroupIndex groupIndex;
	private GoalService goals;
	private BountyService bounties;
	private RequestService requests;
	private GroupStore store;
	private SyncEngine engine;
	private GroupView view;
	private boolean dirty;

	SimulatedClient(SimulatedParty party, String name, long accountHash, long seed)
	{
		this.party = party;
		this.name = name;
		this.accountHash = accountHash;
		this.random = new Random(seed);
		tickTimer = random.nextInt((int) TICK_MS);
		flushTimer = random.nextInt((int) FLUSH_MS);
		start();
	}

	/**
	 * RuneLite opens, with the group remembered from last time.
	 */
	private void start()
	{
		client = fakeClient();
		bus = new EventBus(party::noteError);
		HomebaseConfig config = fakeConfig();
		wsClient = construct(WSClient.class, bus, party.http(), HttpUrl.get("https://party.invalid/ws"), gson);
		partyService = construct(PartyService.class, client, wsClient, bus, null);
		injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toInstance(client);
			binder.bind(Gson.class).toInstance(gson);
			binder.bind(HomebaseConfig.class).toInstance(config);
			binder.bind(EventBus.class).toInstance(bus);
			binder.bind(WSClient.class).toInstance(wsClient);
			binder.bind(PartyService.class).toInstance(partyService);
			binder.bind(ScheduledExecutorService.class).toInstance(fake(ScheduledExecutorService.class, Collections.emptyMap()));
		});
		clientThread = injector.getInstance(ClientThread.class);
		groupSync = injector.getInstance(GroupSync.class);
		presence = injector.getInstance(Presence.class);
		collector = injector.getInstance(LocalCollector.class);
		groupIndex = injector.getInstance(GroupIndex.class);
		goals = injector.getInstance(GoalService.class);
		bounties = injector.getInstance(BountyService.class);
		requests = injector.getInstance(RequestService.class);
		liveSharing = injector.getInstance(LiveSharing.class);

		// the order HomebasePlugin starts them in
		groupSync.start();
		presence.start();
		bus.register(groupSync);
		bus.register(presence);
		bus.register(collector);
		HomebasePlugin plugin = new HomebasePlugin();
		String gim = passphrase == null ? party.groupName() : null;
		setGimGroup(plugin, gim);
		collector.setSharePolicy(plugin::belongsToGroup);
		collector.start();
		liveSharing.start(plugin);
		running = true;
		openGroup(plugin, gim);
	}

	/**
	 * What {@link HomebasePlugin} does when it opens a group, loading the saved copy straight away rather
	 * than on its executor.
	 */
	private void openGroup(HomebasePlugin plugin, String gim)
	{
		String partyPassphrase = gim == null ? passphrase : HomebasePlugin.gimPassphrase(gim, secret);
		store = new GroupStore();
		engine = new SyncEngine(store, () -> party.now() + clockAheadMs, new Random(random.nextLong()));
		dirty = false;
		store.addListener((previous, record) ->
		{
			dirty = true;
			groupIndex.invalidate();
			bounties.invalidate();
			requests.invalidate();
		});
		groupSync.setGroup(partyPassphrase, engine, gim);
		requests.setEngine(engine);
		collector.setEngine(engine);
		view = new GroupView(store, gson);
		groupIndex.setView(view, plugin::belongsToGroup);
		goals.setGroup(engine, view, plugin::belongsToGroup);
		bounties.setEngine(engine);
		onOpen.forEach(hook -> hook.accept(this));
		load();
	}

	private void load()
	{
		if (savedCopy == null)
		{
			return;
		}
		List<SyncRecord> records = WireCodec.readSave(gson, new StringReader(savedCopy));
		if (records != null)
		{
			engine.load(records);
			store.purgeDeleted(party.now() + clockAheadMs - TOMBSTONE_LIFETIME_MS);
		}
	}

	private void save()
	{
		if (dirty)
		{
			dirty = false;
			StringWriter writer = new StringWriter();
			WireCodec.writeSave(gson, writer, store.all());
			savedCopy = writer.toString();
		}
	}

	/**
	 * Run something each time the group opens, such as giving a service its engine.
	 */
	void onGroupOpened(Consumer<SimulatedClient> hook)
	{
		onOpen.add(hook);
		hook.accept(this);
	}

	/**
	 * This much time passes. Runs from {@link SimulatedParty#run}.
	 */
	void step(long millis)
	{
		if (!running)
		{
			return;
		}
		ageTimestamps(millis);
		tickTimer += millis;
		if (tickTimer >= TICK_MS)
		{
			tickTimer -= TICK_MS;
			if (gameState == GameState.LOGGED_IN)
			{
				tickCount++;
				bus.post(new GameTick());
			}
		}
		flushTimer += millis;
		if (flushTimer >= FLUSH_MS)
		{
			flushTimer -= FLUSH_MS;
			clientThread.invokeLater(() ->
			{
				liveSharing.update();
				groupSync.flush();
			});
		}
		saveTimer += millis;
		if (saveTimer >= SAVE_MS)
		{
			saveTimer -= SAVE_MS;
			save();
		}
		runClientThread();
	}

	/**
	 * @return true if there was anything to run
	 */
	boolean runClientThread()
	{
		if (!running)
		{
			return false;
		}
		try
		{
			Field waiting = ClientThread.class.getDeclaredField("invokes");
			waiting.setAccessible(true);
			boolean any = !((Collection<?>) waiting.get(clientThread)).isEmpty();
			Method invoke = ClientThread.class.getDeclaredMethod("invoke");
			invoke.setAccessible(true);
			invoke.invoke(clientThread);
			return any;
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	/**
	 * The player presses Connect.
	 */
	void connect()
	{
		groupSync.joinGroupParty();
		party.settle();
	}

	/**
	 * The player presses Disconnect.
	 */
	void disconnect()
	{
		groupSync.leaveGroupParty();
		party.settle();
	}

	/**
	 * The player joins a party some other way, such as through RuneLite's Party panel.
	 */
	/**
	 * RuneLite's own Party plugin turned on. It's what has the panel to type a party's name into, and it
	 * sends the character's name to any party.
	 */
	void turnOnPartyPlugin()
	{
		injector.getInstance(PartyDataService.class).subscribe(new HomebasePlugin(), PartyDataType.CHARACTER_NAME);
	}

	void joinPartyDirectly(String partyPassphrase)
	{
		partyService.changeParty(partyPassphrase);
		party.settle();
	}

	void logOut()
	{
		setGameState(GameState.LOGIN_SCREEN);
		party.settle();
	}

	void logIn()
	{
		setGameState(GameState.LOGGED_IN);
		party.settle();
	}

	/**
	 * Log out, and back in on a different account. The game's member list decides whether it's in the group.
	 */
	void logInOnAnotherAccount(String accountName)
	{
		logOut();
		// nobody gets through the login screen instantly
		party.run(5_000);
		name = accountName;
		accountHash = accountName.hashCode();
		logIn();
	}

	private void setGameState(GameState state)
	{
		gameState = state;
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		bus.post(event);
	}

	/**
	 * The player closes RuneLite's window. No plugin is stopped when that happens: all a plugin gets is the
	 * chance to act on {@link ClientShutdown}, so whatever hasn't reached the save file yet is gone unless it
	 * does. Saving is done here rather than by the plugin, so here it follows whether the plugin would. Stays
	 * closed until {@link #openRuneLite}.
	 */
	void closeRuneLite()
	{
		if (pluginActsOnClosing())
		{
			save();
		}
		wsClient.close();
		running = false;
		party.settle();
	}

	private static boolean pluginActsOnClosing()
	{
		for (Method method : HomebasePlugin.class.getDeclaredMethods())
		{
			if (method.isAnnotationPresent(Subscribe.class) && method.getParameterCount() == 1
				&& method.getParameterTypes()[0] == ClientShutdown.class)
			{
				return true;
			}
		}
		return false;
	}

	void openRuneLite()
	{
		gameState = GameState.LOGGED_IN;
		start();
		party.settle();
	}

	/**
	 * The plugin is turned off and on again, which saves on the way out and leaves the party.
	 */
	void restartPlugin()
	{
		groupSync.leaveGroupParty();
		save();
		running = false;
		party.settle();
		start();
		party.settle();
	}

	/**
	 * The save file is lost, as on a new computer. RuneLite has to be closed for it to matter.
	 */
	void loseSavedCopy()
	{
		savedCopy = null;
	}

	void setClockAhead(long millis)
	{
		clockAheadMs = millis;
	}

	/**
	 * Set the Group Ironman secret, which takes effect the next time RuneLite opens.
	 */
	void setSecret(String secret)
	{
		this.secret = secret;
	}

	/**
	 * Set a group passphrase, which takes effect the next time RuneLite opens.
	 */
	void setPassphrase(String passphrase)
	{
		this.passphrase = passphrase;
	}

	/**
	 * The player's level changes, which the game reports with the new experience.
	 */
	void setXp(Skill skill, int amount)
	{
		xp.put(skill, amount);
		bus.post(new StatChanged(skill, amount, 1, 1));
	}

	/**
	 * Lose the connection without RuneLite knowing it's coming.
	 */
	void loseConnection()
	{
		try
		{
			Field socket = WSClient.class.getDeclaredField("webSocket");
			socket.setAccessible(true);
			party.loseConnection((WebSocket) socket.get(wsClient));
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	String name()
	{
		return name;
	}

	String id()
	{
		return Ids.member(accountHash);
	}

	GroupSync.Status status()
	{
		return groupSync.getStatus();
	}

	GroupSync groupSync()
	{
		return groupSync;
	}

	LocalCollector collector()
	{
		return collector;
	}

	GroupIndex groupIndex()
	{
		return groupIndex;
	}

	GoalService goals()
	{
		return goals;
	}

	BountyService bounties()
	{
		return bounties;
	}

	RequestService requests()
	{
		return requests;
	}

	GroupStore store()
	{
		return store;
	}

	SyncEngine engine()
	{
		return engine;
	}

	GroupView view()
	{
		return view;
	}

	Gson gson()
	{
		return gson;
	}

	/**
	 * @return one of the plugin's own objects, as this client's injector makes it
	 */
	<T> T get(Class<T> type)
	{
		return injector.getInstance(type);
	}

	/**
	 * @return everything this client holds, deleted records included, in a form that can be compared
	 */
	List<String> recordsAsText()
	{
		List<String> out = new ArrayList<>();
		for (SyncRecord record : store.all())
		{
			out.add(record.getKey() + " v" + record.getVersion() + " by " + record.getAuthor()
				+ (record.isDeleted() ? " deleted" : " " + record.getData()));
		}
		Collections.sort(out);
		return out;
	}

	private void ageTimestamps(long millis)
	{
		age(groupSync, "lastSummaryAt", millis);
		age(groupSync, "loginScreenSince", millis);
		ageAll(groupSync, "listedAt", millis);
		ageAll(groupSync, "heardAt", millis);
		age(presence, "lastSent", millis);
		ageAll(presence, "lastHeard", millis);
		ageAll(collector, "lastPublished", millis);
	}

	private static void age(Object owner, String fieldName, long millis)
	{
		try
		{
			Field field = owner.getClass().getDeclaredField(fieldName);
			field.setAccessible(true);
			long value = field.getLong(owner);
			if (value > 0)
			{
				field.setLong(owner, value - millis);
			}
		}
		catch (NoSuchFieldException e)
		{
			// not every version keeps this one
		}
		catch (IllegalAccessException e)
		{
			throw new AssertionError(e);
		}
	}

	@SuppressWarnings("unchecked")
	private static <K> void ageAll(Object owner, String fieldName, long millis)
	{
		try
		{
			Field field = owner.getClass().getDeclaredField(fieldName);
			field.setAccessible(true);
			Map<K, Long> times = (Map<K, Long>) field.get(owner);
			times.replaceAll((key, value) -> value - millis);
		}
		catch (NoSuchFieldException e)
		{
			// not every version keeps this one
		}
		catch (IllegalAccessException e)
		{
			throw new AssertionError(e);
		}
	}

	private static void setGimGroup(HomebasePlugin plugin, String gim)
	{
		try
		{
			Field field = HomebasePlugin.class.getDeclaredField("gimGroup");
			field.setAccessible(true);
			field.set(plugin, gim);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	@SuppressWarnings("unchecked")
	private static <T> T construct(Class<T> type, Object... arguments)
	{
		try
		{
			Constructor<?> constructor = type.getDeclaredConstructors()[0];
			constructor.setAccessible(true);
			return (T) constructor.newInstance(arguments);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private Client fakeClient()
	{
		Map<String, Function<Object[], Object>> player = new HashMap<>();
		player.put("getName", args -> name);
		Player local = fake(Player.class, player);

		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getGameState", args -> gameState);
		answers.put("getAccountHash", args -> accountHash);
		answers.put("getLocalPlayer", args -> gameState == GameState.LOGGED_IN ? local : null);
		answers.put("getWorld", args -> 301);
		answers.put("getTickCount", args -> tickCount);
		answers.put("isClientThread", args -> true);
		answers.put("getIntStack", args -> new int[]{1});
		answers.put("getSkillExperience", args -> args[0] instanceof Skill ? xp.getOrDefault(args[0], 0) : 0);
		answers.put("getClanChannel", args -> loggedInToGroup() ? clanChannel() : null);
		answers.put("getClanSettings", args -> loggedInToGroup() ? clanSettings() : null);
		return fake(Client.class, answers);
	}

	private boolean loggedInToGroup()
	{
		return gameState == GameState.LOGGED_IN && party.isOnRoster(name);
	}

	private ClanChannel clanChannel()
	{
		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getName", args -> party.groupName());
		return fake(ClanChannel.class, answers);
	}

	private ClanSettings clanSettings()
	{
		List<ClanMember> members = new ArrayList<>();
		for (String member : party.roster())
		{
			Map<String, Function<Object[], Object>> answers = new HashMap<>();
			answers.put("getName", args -> member);
			members.add(fake(ClanMember.class, answers));
		}
		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getName", args -> party.groupName());
		answers.put("getMembers", args -> members);
		return fake(ClanSettings.class, answers);
	}

	/**
	 * @return settings that answer as they do for a player who has never changed them
	 */
	private static HomebaseConfig fakeConfig()
	{
		return (HomebaseConfig) Proxy.newProxyInstance(HomebaseConfig.class.getClassLoader(), new Class<?>[]{HomebaseConfig.class},
			(proxy, method, args) ->
			{
				if (method.isDefault())
				{
					return MethodHandles.privateLookupIn(HomebaseConfig.class, MethodHandles.lookup())
						.unreflectSpecial(method, HomebaseConfig.class)
						.bindTo(proxy)
						.invokeWithArguments(args == null ? new Object[0] : args);
				}
				return nothing(method.getReturnType());
			});
	}

	/**
	 * @return a stand-in that answers the named methods, and gives 0, false or null for the rest
	 */
	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, Map<String, Function<Object[], Object>> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) ->
		{
			Function<Object[], Object> answer = answers.get(method.getName());
			if (answer != null)
			{
				return answer.apply(args);
			}
			if (method.getName().equals("hashCode"))
			{
				return System.identityHashCode(proxy);
			}
			if (method.getName().equals("equals"))
			{
				return proxy == args[0];
			}
			if (method.getName().equals("toString"))
			{
				return type.getSimpleName();
			}
			return nothing(method.getReturnType());
		});
	}

	private static Object nothing(Class<?> returns)
	{
		if (returns == boolean.class)
		{
			return false;
		}
		if (returns == long.class)
		{
			return 0L;
		}
		if (returns == int.class)
		{
			return 0;
		}
		if (returns == double.class)
		{
			return 0D;
		}
		if (returns == float.class)
		{
			return 0F;
		}
		if (returns == short.class)
		{
			return (short) 0;
		}
		if (returns == byte.class)
		{
			return (byte) 0;
		}
		if (returns == char.class)
		{
			return (char) 0;
		}
		return null;
	}
}

package com.homebase;

import com.google.gson.Gson;
import com.homebase.party.HomebaseSyncMessage;
import com.homebase.sync.SyncRecord;
import com.homebase.sync.WireCodec;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Random;
import java.util.Set;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import okio.ByteString;
import static org.junit.Assert.assertEquals;

/**
 * Several members playing at once, all on one thread: stands in for RuneLite's party server and for time
 * passing, and leaves everything else to the real code. Each {@link SimulatedClient} runs the plugin's sync
 * and RuneLite's own party classes, and what they send each other goes through this class as the same bytes
 * they would send the real server.
 * <p>
 * The server isn't open source, so how it behaves here comes from what RuneLite's party client expects of
 * it: joining lists everyone already in the party, messages go to everyone including whoever sent them, and
 * a connection that closes can stay listed for a while before anyone is told it left.
 */
final class SimulatedParty
{
	static final long SECOND = 1_000;
	static final long MINUTE = 60 * SECOND;

	/**
	 * The smallest slice of time simulated.
	 */
	private static final long STEP_MS = 100;

	private static final class Delivery
	{
		final long at;
		final long order;
		final Connection to;
		final byte[] bytes;

		Delivery(long at, long order, Connection to, byte[] bytes)
		{
			this.at = at;
			this.order = order;
			this.to = to;
			this.bytes = bytes;
		}
	}

	/**
	 * Something a client sent the party, as the server saw it.
	 */
	static final class Sent
	{
		final String type;
		final int bytes;
		final String json;

		Sent(String type, int bytes, String json)
		{
			this.type = type;
			this.bytes = bytes;
			this.json = json;
		}
	}

	/**
	 * A client's connection to the server.
	 */
	private final class Connection implements WebSocket
	{
		final Request request;
		final WebSocketListener listener;
		long partyId;
		long memberId;
		boolean open = true;
		long lastDeliveryAt;

		Connection(Request request, WebSocketListener listener)
		{
			this.request = request;
			this.listener = listener;
		}

		@Override
		public Request request()
		{
			return request;
		}

		@Override
		public long queueSize()
		{
			return 0;
		}

		@Override
		public boolean send(String text)
		{
			throw new UnsupportedOperationException("the party only sends bytes");
		}

		@Override
		public boolean send(ByteString bytes)
		{
			if (open)
			{
				received(this, bytes.toByteArray());
			}
			return open;
		}

		@Override
		public boolean close(int code, String reason)
		{
			closed(this);
			return true;
		}

		@Override
		public void cancel()
		{
			closed(this);
		}
	}

	private final Gson gson = new Gson();
	private final Random random = new Random(20261105);
	private final Map<Long, List<Connection>> parties = new HashMap<>();
	private final PriorityQueue<Delivery> inFlight = new PriorityQueue<>(
		Comparator.<Delivery>comparingLong(d -> d.at).thenComparingLong(d -> d.order));
	private final List<SimulatedClient> clients = new ArrayList<>();
	private final Set<String> roster = new HashSet<>();
	private final List<Throwable> errors = new ArrayList<>();
	private final List<Sent> sent = new ArrayList<>();
	private final Map<Connection, Long> partsDue = new HashMap<>();
	private final String groupName = "HungryHorse";

	private long now = 1_790_000_000_000L;
	private long order;
	private long latencyMs;
	private long stayListedMs;

	/**
	 * @return a member of the group, logged in and not yet connected
	 */
	SimulatedClient member(String name)
	{
		roster.add(name);
		return addClient(name);
	}

	/**
	 * @return someone with the plugin who isn't in the group, logged in and not yet connected
	 */
	SimulatedClient outsider(String name)
	{
		return addClient(name);
	}

	private SimulatedClient addClient(String name)
	{
		SimulatedClient client = new SimulatedClient(this, name, 1_000L + clients.size(), random.nextLong());
		clients.add(client);
		return client;
	}

	String groupName()
	{
		return groupName;
	}

	/**
	 * @return the group's member list, as the game gives it
	 */
	Set<String> roster()
	{
		return roster;
	}

	boolean isOnRoster(String name)
	{
		for (String member : roster)
		{
			if (Text.toJagexName(member).equalsIgnoreCase(Text.toJagexName(name)))
			{
				return true;
			}
		}
		return false;
	}

	long now()
	{
		return now;
	}

	void noteError(Throwable error)
	{
		errors.add(error);
	}

	/**
	 * How long messages take to arrive, at most. Each connection still gets its messages in order.
	 */
	void setLatency(long latencyMs)
	{
		this.latencyMs = latencyMs;
	}

	/**
	 * How long a closed connection stays listed before the others are told it left.
	 */
	void setStayListed(long stayListedMs)
	{
		this.stayListedMs = stayListedMs;
	}

	/**
	 * Let time pass.
	 */
	void run(long millis)
	{
		for (long t = 0; t < millis; t += STEP_MS)
		{
			now += STEP_MS;
			removeDueParts();
			for (SimulatedClient client : clients)
			{
				client.step(STEP_MS);
			}
			settle();
		}
	}

	/**
	 * A long time goes by with nothing happening, such as weeks away from the game.
	 */
	void skip(long millis)
	{
		now += millis;
	}

	/**
	 * Everything that's due happens, until nothing more is.
	 */
	void settle()
	{
		boolean busy = true;
		while (busy)
		{
			busy = false;
			for (SimulatedClient client : clients)
			{
				busy |= client.runClientThread();
			}
			while (!inFlight.isEmpty() && inFlight.peek().at <= now)
			{
				Delivery delivery = inFlight.poll();
				if (delivery.to.open)
				{
					delivery.to.listener.onMessage(delivery.to, ByteString.of(delivery.bytes));
				}
				busy = true;
			}
		}
	}

	/**
	 * @return what every client has sent the party so far, as the server saw it
	 */
	List<Sent> sent()
	{
		return Collections.unmodifiableList(sent);
	}

	void forgetSent()
	{
		sent.clear();
	}

	/**
	 * @return each batch of records the clients have sent, as a receiver reads them
	 */
	List<List<SyncRecord>> recordBatches()
	{
		List<List<SyncRecord>> out = new ArrayList<>();
		for (String json : syncPayloads("R"))
		{
			out.add(gson.fromJson(json, WireCodec.RECORDS_TYPE));
		}
		return out;
	}

	/**
	 * @return the uncompressed text of every sync message of a type: "S" for a summary and "R" for records
	 */
	List<String> syncPayloads(String type)
	{
		List<String> out = new ArrayList<>();
		for (Sent message : sent)
		{
			if (!HomebaseSyncMessage.class.getSimpleName().equals(message.type))
			{
				continue;
			}
			HomebaseSyncMessage sync = gson.fromJson(message.json, HomebaseSyncMessage.class);
			if (type.equals(sync.getType()))
			{
				try
				{
					out.add(WireCodec.unpack(sync.getPayload()));
				}
				catch (IOException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		return out;
	}

	void assertNoErrors()
	{
		if (!errors.isEmpty())
		{
			throw new AssertionError("Something threw while the clients ran: " + errors, errors.get(0));
		}
	}

	/**
	 * Every client named holds exactly the same records, deleted ones included.
	 */
	static void assertSameRecords(SimulatedClient first, SimulatedClient... others)
	{
		for (SimulatedClient other : others)
		{
			assertEquals(first.name() + " and " + other.name() + " should hold the same records",
				first.recordsAsText(), other.recordsAsText());
		}
	}

	/**
	 * A client's connection fails, as it does when the network drops.
	 */
	void loseConnection(WebSocket socket)
	{
		Connection connection = (Connection) socket;
		connection.listener.onFailure(connection, new IOException("connection lost"), null);
		closed(connection);
	}

	/**
	 * @return an HTTP client whose websockets lead here
	 */
	OkHttpClient http()
	{
		return new OkHttpClient()
		{
			@Override
			public WebSocket newWebSocket(Request request, WebSocketListener listener)
			{
				return new Connection(request, listener);
			}
		};
	}

	private void received(Connection from, byte[] bytes)
	{
		Object message = invokeStatic("C2S", "parseFrom", new Class<?>[]{byte[].class}, (Object) bytes);
		if ((boolean) read(message, "hasJoin"))
		{
			Object join = read(message, "getJoin");
			joined(from, (long) read(join, "getPartyId"), (long) read(join, "getMemberId"));
		}
		else if ((boolean) read(message, "hasPart"))
		{
			closed(from);
		}
		else if ((boolean) read(message, "hasData"))
		{
			shared(from, read(message, "getData"));
		}
		else
		{
			throw new AssertionError("A message with nothing in it");
		}
	}

	private void joined(Connection connection, long partyId, long memberId)
	{
		connection.partyId = partyId;
		connection.memberId = memberId;
		List<Connection> party = parties.computeIfAbsent(partyId, id -> new ArrayList<>());
		for (Connection member : new ArrayList<>(party))
		{
			if (member.memberId == memberId)
			{
				// the same member reconnecting replaces their old connection
				party.remove(member);
				partsDue.remove(member);
				member.open = false;
				continue;
			}
			deliver(connection, userMessage("setJoin", "UserJoin", partyId, member.memberId));
			if (member.open)
			{
				deliver(member, userMessage("setJoin", "UserJoin", partyId, memberId));
			}
		}
		party.add(connection);
		deliver(connection, userMessage("setJoin", "UserJoin", partyId, memberId));
	}

	private void shared(Connection from, Object data)
	{
		String type = (String) read(data, "getType");
		Object body = read(data, "getData");
		String text = ((com.google.protobuf.ByteString) body).toStringUtf8();
		sent.add(new Sent(type, (int) read(data, "getSerializedSize"), text));
		Object message = invokeStatic("PartyData", "newBuilder", new Class<?>[0]);
		set(message, "setPartyId", long.class, from.partyId);
		set(message, "setMemberId", long.class, from.memberId);
		set(message, "setType", String.class, type);
		set(message, "setData", com.google.protobuf.ByteString.class, body);
		byte[] bytes = serverMessage("setData", "PartyData", read(message, "build"));
		for (Connection member : parties.getOrDefault(from.partyId, Collections.emptyList()))
		{
			if (member.open)
			{
				deliver(member, bytes);
			}
		}
	}

	private void closed(Connection connection)
	{
		if (!connection.open)
		{
			return;
		}
		connection.open = false;
		if (stayListedMs > 0)
		{
			partsDue.put(connection, now + stayListedMs);
		}
		else
		{
			part(connection);
		}
	}

	private void removeDueParts()
	{
		for (Connection connection : new ArrayList<>(partsDue.keySet()))
		{
			if (partsDue.get(connection) <= now)
			{
				partsDue.remove(connection);
				part(connection);
			}
		}
	}

	private void part(Connection connection)
	{
		List<Connection> party = parties.get(connection.partyId);
		if (party == null || !party.remove(connection))
		{
			return;
		}
		byte[] bytes = userMessage("setPart", "UserPart", connection.partyId, connection.memberId);
		for (Connection member : party)
		{
			if (member.open)
			{
				deliver(member, bytes);
			}
		}
	}

	private void deliver(Connection to, byte[] bytes)
	{
		long at = latencyMs == 0 ? now : now + (long) (random.nextDouble() * latencyMs);
		at = Math.max(at, to.lastDeliveryAt);
		to.lastDeliveryAt = at;
		inFlight.add(new Delivery(at, order++, to, bytes));
	}

	private static byte[] userMessage(String setter, String type, long partyId, long memberId)
	{
		Object user = invokeStatic(type, "newBuilder", new Class<?>[0]);
		set(user, "setPartyId", long.class, partyId);
		set(user, "setMemberId", long.class, memberId);
		return serverMessage(setter, type, read(user, "build"));
	}

	private static byte[] serverMessage(String setter, String type, Object inner)
	{
		Object message = invokeStatic("S2C", "newBuilder", new Class<?>[0]);
		set(message, setter, messageClass(type), inner);
		return (byte[]) read(read(message, "build"), "toByteArray");
	}

	/*
	 * RuneLite's generated party messages sit inside a class that can't be named from outside its package,
	 * and nothing can join that package since RuneLite's jar is signed, so they're reached by name.
	 */

	private static Class<?> messageClass(String name)
	{
		try
		{
			return Class.forName("net.runelite.client.party.Party$" + name);
		}
		catch (ClassNotFoundException e)
		{
			throw new AssertionError(e);
		}
	}

	private static Object invokeStatic(String type, String method, Class<?>[] parameters, Object... arguments)
	{
		try
		{
			return messageClass(type).getMethod(method, parameters).invoke(null, arguments);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static Object read(Object message, String method)
	{
		try
		{
			return message.getClass().getMethod(method).invoke(message);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static void set(Object builder, String method, Class<?> parameter, Object value)
	{
		try
		{
			builder.getClass().getMethod(method, parameter).invoke(builder, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.homebase;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncRecord;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.After;
import org.junit.Test;

/**
 * A member in the middle who has never heard of some of what passes through them, as anyone on an older
 * version hasn't. Records are written here by hand, exactly as a newer version writes them, so this only
 * uses what every version has and can be run against the version on the Plugin Hub as well.
 */
public class UnknownRecordsRelayTest
{
	private static final long SECOND = SimulatedParty.SECOND;
	private static final long CATCH_UP = 20 * SECOND;

	private final SimulatedParty party = new SimulatedParty();
	private final SimulatedClient alice = party.member("Alice");
	private final SimulatedClient bob = party.member("Bob");
	private final SimulatedClient carol = party.member("Carol");

	@After
	public void nothingThrew()
	{
		party.assertNoErrors();
	}

	private List<SyncRecord> publishNewerKinds()
	{
		long now = party.now();
		String me = alice.id();
		alice.engine().publish(Keys.member(me, "storagelog"), me,
			new JsonParser().parse("{\"entries\":[{\"item\":453,\"amount\":-5,\"at\":" + now + "}]}"));
		alice.engine().publish(Keys.member(me, "feed"), me,
			new JsonParser().parse("{\"entries\":[{\"at\":" + now + ",\"type\":\"drop\",\"name\":\"Draconic visage\",\"quantity\":1,\"value\":3000000,\"source\":\"Vorkath\"}]}"));
		alice.engine().publish(Keys.member(me, "pin"), me,
			new JsonParser().parse("{\"placed\":true,\"x\":3222,\"y\":3218,\"plane\":0,\"color\":2146368,\"at\":" + now + "}"));
		alice.engine().publish(Keys.shared("return", "453"), me, new JsonParser().parse("{\"item\":453}"));
		alice.engine().publish(Keys.shared("return", "385"), me, new JsonParser().parse("{\"item\":385}"));
		alice.engine().delete(Keys.shared("return", "385"), me);
		JsonObject profile = new JsonObject();
		profile.addProperty("name", "Alice");
		profile.addProperty("world", 301);
		profile.addProperty("groupName", party.groupName());
		profile.addProperty("color", 2146368);
		alice.engine().publish(Keys.member(me, "profile"), me, profile);

		List<SyncRecord> out = new ArrayList<>();
		for (String key : Arrays.asList(Keys.member(me, "storagelog"), Keys.member(me, "feed"), Keys.member(me, "pin"),
			Keys.shared("return", "453"), Keys.member(me, "profile")))
		{
			out.add(alice.store().get(key));
		}
		return out;
	}

	@Test
	public void recordsOfUnknownKindsGoThroughAMemberAndTheirSaveFileUnchanged()
	{
		party.run(5 * SECOND);
		List<SyncRecord> records = publishNewerKinds();
		alice.connect();
		bob.connect();
		party.run(CATCH_UP);
		alice.disconnect();

		// Bob restarts, so all he has to pass on is what went through his save file
		bob.restartPlugin();
		party.run(5 * SECOND);
		bob.connect();
		carol.connect();
		party.run(CATCH_UP);

		for (SyncRecord record : records)
		{
			assertEquals(record, carol.store().get(record.getKey()));
		}
		assertEquals("the delete is passed on too", 0, carol.store().withPrefix(Keys.shared("return", "385")).size());
		assertTrue(carol.recordsAsText().stream().anyMatch(text -> text.startsWith(Keys.shared("return", "385"))));
		SimulatedParty.assertSameRecords(bob, carol);
	}

	@Test
	public void aNewerCopyOfAnUnknownKindReplacesTheOldOneOnTheWayThrough()
	{
		party.run(5 * SECOND);
		String me = alice.id();
		alice.engine().publish(Keys.member(me, "pin"), me, new JsonParser().parse("{\"placed\":true,\"x\":1}"));
		alice.connect();
		bob.connect();
		party.run(CATCH_UP);

		alice.engine().publish(Keys.member(me, "pin"), me, new JsonParser().parse("{\"placed\":false,\"x\":2}"));
		party.run(5 * SECOND);
		alice.disconnect();
		carol.connect();
		party.run(CATCH_UP);

		SyncRecord pin = carol.store().get(Keys.member(me, "pin"));
		assertNotNull(pin);
		assertEquals(2, pin.getData().getAsJsonObject().get("x").getAsInt());
	}
}

package com.homebase.bounties;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class StorageHoldsTest
{
	@Test
	public void withdrawAmounts()
	{
		assertEquals(1, StorageHolds.amount("Withdraw-1", 8));
		assertEquals(5, StorageHolds.amount("Withdraw-5", 8));
		assertEquals(8, StorageHolds.amount("Withdraw-10", 8));
		assertEquals(3, StorageHolds.amount("Withdraw-3", 8));
		assertEquals(8, StorageHolds.amount("Withdraw-All", 8));
		assertEquals(7, StorageHolds.amount("Withdraw-All-but-1", 8));
		assertEquals(-1, StorageHolds.amount("Withdraw-X", 8));
	}

	@Test
	public void onlyWhatIsLeftOverCanBeTaken()
	{
		// 8 in storage, 5 held for someone: 3 are free for anyone
		assertEquals(3, StorageHolds.free(8, 5));
		assertTrue(StorageHolds.allowed("Withdraw-1", 8, 5));
		assertTrue(StorageHolds.allowed("Withdraw-3", 8, 5));
		assertFalse(StorageHolds.allowed("Withdraw-5", 8, 5));
		assertFalse(StorageHolds.allowed("Withdraw-10", 8, 5));
		assertFalse(StorageHolds.allowed("Withdraw-All", 8, 5));
		assertFalse(StorageHolds.allowed("Withdraw-All-but-1", 8, 5));
		// the amount typed after Withdraw-X can't be checked, so it goes while anything is held
		assertFalse(StorageHolds.allowed("Withdraw-X", 8, 5));
	}

	@Test
	public void fewerThanAskedForAreAllHeld()
	{
		assertEquals(0, StorageHolds.free(3, 5));
		assertFalse(StorageHolds.allowed("Withdraw-1", 3, 5));
	}

	@Test
	public void wholeStackHoldsEverything()
	{
		assertEquals(0, StorageHolds.free(40_000, StorageHolds.ALL));
		assertFalse(StorageHolds.allowed("Withdraw-1", 40_000, StorageHolds.ALL));
	}

	@Test
	public void nothingHeldLeavesEverything()
	{
		assertTrue(StorageHolds.allowed("Withdraw-All", 8, 0));
		assertTrue(StorageHolds.allowed("Withdraw-X", 8, 0));
	}
}

package com.homebase.collect;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ActivityCollectorTest
{
	@Test
	public void readsKillCountMessages()
	{
		assertArrayEquals(new String[]{"Vorkath", "12"}, ActivityCollector.parseKillCount("Your Vorkath kill count is: 12."));
		assertArrayEquals(new String[]{"Chambers of Xeric", "5"},
			ActivityCollector.parseKillCount("Your completed Chambers of Xeric count is: 5."));
		assertArrayEquals(new String[]{"Barrows", "1250"}, ActivityCollector.parseKillCount("Your Barrows chest count is: 1,250."));
		assertArrayEquals(new String[]{"Corrupted Gauntlet", "2"},
			ActivityCollector.parseKillCount("Your Corrupted Gauntlet completion count is: 2."));
		assertArrayEquals(new String[]{"Wintertodt", "100"}, ActivityCollector.parseKillCount("Your subdued Wintertodt count is: 100."));
		assertArrayEquals(new String[]{"K'ril Tsutsaroth", "40"},
			ActivityCollector.parseKillCount("Your K'ril Tsutsaroth kill count is: 40."));
	}

	@Test
	public void ignoresOtherMessages()
	{
