		assertEquals(GroupSync.rosterKey("Bonscott Kid"), GroupSync.rosterKey("bonscott\u00A0kid"));
		assertEquals(GroupSync.rosterKey("Mundell"), GroupSync.rosterKey("MUNDELL"));
