package com.homebase.storage;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.homebase.data.StorageLogData;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Item;
import org.junit.Test;

public class StorageHistoryTest
{
	private static final int SHARK = 385;
	private static final int COAL = 453;
	private static final int WHIP = 4151;

	static Map<Integer, Integer> items(int... idThenAmount)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (int i = 0; i < idThenAmount.length; i += 2)
		{
			out.put(idThenAmount[i], idThenAmount[i + 1]);
		}
		return out;
	}

	private static StorageHistory.Change change(int item, int amount)
	{
		return new StorageHistory.Change(item, amount);
	}

	private static StorageHistory.MemberLog member(String name, long updatedAt, long... itemAmountAt)
	{
		StorageLogData log = new StorageLogData();
		for (int i = 0; i < itemAmountAt.length; i += 3)
		{
			log.add((int) itemAmountAt[i], (int) itemAmountAt[i + 1], itemAmountAt[i + 2]);
		}
		return new StorageHistory.MemberLog(name, log, updatedAt);
	}

	@Test
	public void noChangeWhenNothingMoved()
	{
		assertTrue(StorageHistory.changes(items(), items()).isEmpty());
		assertTrue(StorageHistory.changes(items(SHARK, 5, COAL, 10), items(COAL, 10, SHARK, 5)).isEmpty());
	}

	@Test
	public void changesAreWhatWentInAndCameOut()
	{
		assertEquals(Collections.singletonList(change(SHARK, 3)), StorageHistory.changes(items(SHARK, 5), items(SHARK, 8)));
		assertEquals(Collections.singletonList(change(SHARK, -3)), StorageHistory.changes(items(SHARK, 5), items(SHARK, 2)));
		assertEquals(Collections.singletonList(change(WHIP, 1)), StorageHistory.changes(items(), items(WHIP, 1)));
		assertEquals(Collections.singletonList(change(WHIP, -1)), StorageHistory.changes(items(WHIP, 1), items()));
		assertEquals(Arrays.asList(change(SHARK, -5), change(COAL, 20)),
			StorageHistory.changes(items(SHARK, 5, COAL, 10), items(COAL, 30)));
	}

	@Test
	public void slotsDontMatterOnlyHowManyThereAre()
	{
		Map<Integer, Integer> before = StorageHistory.counts(new Item[]{new Item(SHARK, 1), new Item(-1, 0), new Item(SHARK, 1), new Item(COAL, 9)});
		Map<Integer, Integer> after = StorageHistory.counts(new Item[]{new Item(COAL, 9), new Item(SHARK, 1), null, new Item(SHARK, 1)});
		assertEquals(items(SHARK, 2, COAL, 9), before);
		assertTrue(StorageHistory.changes(before, after).isEmpty());
	}

	@Test
	public void countingEmptySlotsAndHugeStacksIsSafe()
	{
		assertTrue(StorageHistory.counts(null).isEmpty());
		assertTrue(StorageHistory.counts(new Item[]{new Item(0, 5), new Item(SHARK, 0)}).isEmpty());
		assertEquals(items(SHARK, Integer.MAX_VALUE),
			StorageHistory.counts(new Item[]{new Item(SHARK, Integer.MAX_VALUE), new Item(SHARK, 5)}));
	}

	@Test
	public void noSaveCanMoveMoreKindsThanSomeoneCarries()
	{
		List<StorageHistory.Change> most = new ArrayList<>();
		for (int i = 1; i <= StorageHistory.MAX_KINDS_PER_SAVE; i++)
		{
			most.add(change(i, -1));
		}
		assertTrue(StorageHistory.possible(most));
		// the same again in the other direction is a swap, which can be done
		for (int i = 1; i <= StorageHistory.MAX_KINDS_PER_SAVE; i++)
		{
			most.add(change(1000 + i, 1));
		}
		assertTrue(StorageHistory.possible(most));
		most.add(change(5000, -1));
		assertFalse(StorageHistory.possible(most));
	}

	@Test
	public void linesFromEveryMemberAreNewestFirst()
	{
		List<StorageHistory.Line> lines = StorageHistory.lines(Arrays.asList(
			member("Mundell", 400, SHARK, -5, 100, COAL, 20, 300),
			member("Fred", 400, WHIP, 1, 200)));
		assertEquals(Arrays.asList(
			new StorageHistory.Line("Mundell", COAL, 20, 300),
			new StorageHistory.Line("Fred", WHIP, 1, 200),
			new StorageHistory.Line("Mundell", SHARK, -5, 100)), lines);
	}

	@Test
	public void anEntryCantClaimToBeNewerThanTheLogItCameIn()
	{
		List<StorageHistory.MemberLog> logs = Collections.singletonList(member("Mundell", 500, SHARK, -5, Long.MAX_VALUE));
		assertEquals(500, StorageHistory.lines(logs).get(0).getAt());
		assertEquals(500, owedAllMarked(logs).get(0).getAt());
	}

	/**
	 * What's owed if every test item has been marked since before the logs began.
	 */
	private static List<StorageHistory.Owed> owedAllMarked(List<StorageHistory.MemberLog> logs)
	{
		Map<Integer, Long> marked = new HashMap<>();
		marked.put(SHARK, 0L);
		marked.put(COAL, 0L);
		marked.put(WHIP, 0L);
		return StorageHistory.owed(logs, marked);
	}

	@Test
	public void takingSomethingUnmarkedOwesNothing()
	{
		assertTrue(StorageHistory.owed(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100)),
			Collections.emptyMap()).isEmpty());
	}

	@Test
	public void onlyWhatsTakenAfterMarkingIsOwed()
	{
		Map<Integer, Long> marked = Collections.singletonMap(SHARK, 150L);
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 2, 200)),
			StorageHistory.owed(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100, SHARK, -2, 200)), marked));
	}

	@Test
	public void takenOutAndNotReturnedIsOwed()
	{
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 5, 100)),
			owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100))));
	}

	@Test
	public void putBackPartlyLeavesTheRestOwed()
	{
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 2, 100)),
			owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100, SHARK, 3, 200))));
	}

	@Test
	public void putBackInFullIsNoLongerOwed()
	{
		assertTrue(owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100, SHARK, 5, 200))).isEmpty());
		assertTrue(owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, -5, 100, SHARK, 9, 200))).isEmpty());
	}

	@Test
	public void takingBackWhatYouPutInIsntOwing()
	{
		assertTrue(owedAllMarked(Collections.singletonList(member("Mundell", 400, WHIP, 1, 100, WHIP, -1, 200))).isEmpty());
		assertTrue(owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, 100, 100, SHARK, -3, 200))).isEmpty());
	}

	@Test
	public void takingOutMoreThanYouPutInIsOwing()
	{
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 3, 200)),
			owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, 5, 100, SHARK, -8, 200))));
	}

	@Test
	public void onlyWhoeverTookItCanReturnIt()
	{
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 5, 100)),
			owedAllMarked(Arrays.asList(
				member("Mundell", 400, SHARK, -5, 100),
				member("Fred", 400, SHARK, 5, 200))));
	}

	@Test
	public void owedSaysWhenTheyLastTookSomeHoweverTheLogIsOrdered()
	{
		assertEquals(Collections.singletonList(new StorageHistory.Owed("Mundell", SHARK, 5, 300)),
			owedAllMarked(Collections.singletonList(member("Mundell", 400, SHARK, -3, 300, SHARK, -2, 100))));
	}

	@Test
	public void mostRecentlyTakenIsFirstAndAmountsDontOverflow()
	{
		List<StorageHistory.Owed> owed = owedAllMarked(Arrays.asList(
			member("Mundell", 400, SHARK, -1, 100),
			member("Fred", 400, COAL, -Integer.MAX_VALUE, 200, COAL, -Integer.MAX_VALUE, 300)));
		assertEquals(Arrays.asList(
			new StorageHistory.Owed("Fred", COAL, 2L * Integer.MAX_VALUE, 300),
			new StorageHistory.Owed("Mundell", SHARK, 1, 100)), owed);
	}
}

package com.homebase.storage;

import static com.homebase.storage.StorageHistoryTest.items;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class StorageSessionTest
{
	private static final int SHARK = 385;
	private static final int COAL = 453;

	private final StorageSession session = new StorageSession();

	private static List<StorageHistory.Change> just(int item, int amount)
	{
		return Collections.singletonList(new StorageHistory.Change(item, amount));
	}

	private List<StorageHistory.Change> saveAndLeave()
	{
		return session.tick(false, true);
	}

	private void open(int... idThenAmount)
	{
		session.built(items(idThenAmount), true);
		assertTrue(session.tick(true, false).isEmpty());
	}

	@Test
	public void openingAndClosingAddsNothing()
	{
		open(SHARK, 5);
		assertTrue(session.tick(false, false).isEmpty());
	}

	@Test
	public void savingWithoutChangingAnythingAddsNothing()
	{
		open(SHARK, 5);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void movingItemsAroundAddsNothing()
	{
		open(SHARK, 5, COAL, 10);
		session.changed(items(COAL, 10, SHARK, 5), true);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void putInAndTakenBackAddsNothing()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 8), true);
		session.changed(items(SHARK, 5), true);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void nothingCountsUntilItsSaved()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		assertTrue(session.tick(true, false).isEmpty());
		assertEquals(just(SHARK, -3), session.tick(true, true));
	}

	@Test
	public void everyChangeInASaveIsCounted()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		session.changed(items(SHARK, 2, COAL, 30), true);
		assertEquals(Arrays.asList(new StorageHistory.Change(SHARK, -3), new StorageHistory.Change(COAL, 30)), saveAndLeave());
	}

	@Test
	public void theSaveMessageShowingForSeveralTicksCountsOnce()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		assertEquals(just(SHARK, -3), session.tick(true, true));
		assertTrue(session.tick(true, true).isEmpty());
		assertTrue(session.tick(false, true).isEmpty());
	}

	@Test
	public void aSecondSaveOnlyCountsWhatChangedSinceTheFirst()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		assertEquals(just(SHARK, -3), session.tick(true, true));
		session.changed(items(SHARK, 4), true);
		assertEquals(just(SHARK, 2), session.tick(true, true));
	}

	@Test
	public void closingWithoutSavingLosesTheChanges()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		for (int i = 0; i <= StorageSession.CLOSE_GRACE_TICKS; i++)
		{
			assertTrue(session.tick(false, false).isEmpty());
		}
		// someone else then takes the rest, so this is where the next look starts from
		open(COAL, 1);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void theSaveCanShowUpJustAfterTheInterfaceCloses()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		for (int i = 0; i < StorageSession.CLOSE_GRACE_TICKS; i++)
		{
			assertTrue(session.tick(false, false).isEmpty());
		}
		assertEquals(just(SHARK, -3), saveAndLeave());
	}

	@Test
	public void aSaveLongAfterClosingIsSomethingElse()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		for (int i = 0; i <= StorageSession.CLOSE_GRACE_TICKS; i++)
		{
			session.tick(false, false);
		}
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void aChangeOnTheSameTickAsLeavingStillCounts()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 9), false);
		assertEquals(just(SHARK, 4), saveAndLeave());
	}

	@Test
	public void anEmptyContainerOnItsOwnIsntBelieved()
	{
		open(SHARK, 5);
		session.changed(items(), true);
		assertTrue(saveAndLeave().isEmpty());

		open(SHARK, 5);
		session.changed(items(), false);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void takingOutTheLastItemCountsOnceTheInterfaceShowsIt()
	{
		open(SHARK, 5);
		session.changed(items(), true);
		session.built(items(), true);
		assertEquals(just(SHARK, -5), saveAndLeave());
	}

	@Test
	public void theInterfaceBeingRedrawnWhileItClosesIsIgnored()
	{
		open(SHARK, 5);
		session.built(items(), false);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void puttingTheFirstThingsInEmptyStorageCounts()
	{
		open();
		session.changed(items(COAL, 30), true);
		assertEquals(just(COAL, 30), saveAndLeave());
	}

	@Test
	public void theStartingPointIsFoundWhicheverWayTheGameReportsIt()
	{
		// the container's report first, with no drawing of the interface yet
		session.changed(items(SHARK, 5), true);
		assertTrue(session.tick(true, false).isEmpty());
		session.changed(items(SHARK, 2), true);
		assertEquals(just(SHARK, -3), session.tick(true, true));

		// drawn before it counts as open
		StorageSession other = new StorageSession();
		other.built(items(COAL, 7), false);
		assertTrue(other.tick(true, false).isEmpty());
		other.changed(items(COAL, 9), true);
		assertEquals(just(COAL, 2), other.tick(true, true));
	}

	@Test
	public void aFreshCopyArrivingAsItOpensIsNotOurChange()
	{
		StorageSession session = new StorageSession();
		// drawn from the copy left from last time, then the game's fresh one with another member's save
		session.built(items(SHARK, 5), true);
		session.changed(items(SHARK, 2), true);
		assertTrue(session.tick(true, false).isEmpty());

		// what we then do ourselves still counts
		session.changed(items(SHARK, 1), true);
		assertEquals(just(SHARK, -1), session.tick(true, true));
	}

	@Test
	public void changesWhileItWasNeverOpenAreIgnored()
	{
		session.changed(items(SHARK, 5), false);
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void aSaveWithNothingFollowedAddsNothing()
	{
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void anImpossibleJumpIsDroppedAndTheNextSaveStartsFromIt()
	{
		int[] everything = new int[2 * (StorageHistory.MAX_KINDS_PER_SAVE + 1)];
		for (int i = 0; i < StorageHistory.MAX_KINDS_PER_SAVE + 1; i++)
		{
			everything[2 * i] = i + 1;
			everything[2 * i + 1] = 1;
		}
		open();
		session.changed(items(everything), true);
		assertTrue(session.tick(true, true).isEmpty());

		everything[1] = 2;
		session.changed(items(everything), true);
		assertEquals(just(1, 1), session.tick(true, true));
	}

	@Test
	public void resetForgetsEverything()
	{
		open(SHARK, 5);
		session.changed(items(SHARK, 2), true);
		session.reset();
		assertTrue(saveAndLeave().isEmpty());
	}

	@Test
	public void theSavingMessageIsToldFromTheLoadingOne()
	{
		assertTrue(StorageWatcher.isSavingText("Saving..."));
		assertTrue(StorageWatcher.isSavingText("<col=ffffff>saving...</col>"));
		assertFalse(StorageWatcher.isSavingText("Loading..."));
		assertFalse(StorageWatcher.isSavingText(null));
	}
}

package com.homebase.storage;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.homebase.HomebaseConfig;
import com.homebase.collect.LocalCollector;
import com.homebase.data.GroupView;
import com.homebase.data.Section;
import com.homebase.data.StorageLogData;
import com.homebase.sync.GroupStore;
import com.homebase.sync.SyncEngine;
import java.awt.Color;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;
import org.junit.Before;
import org.junit.Test;

/**
 * The real watcher, collector, event bus and store, with only the game itself faked: what goes on screen
 * and in the container is set by each test, and the same events the game sends are posted.
 */
public class StorageWatcherTest
{
	private static final int SHARK = 385;
	private static final int COAL = 453;

	private final Map<Integer, Widget> widgets = new HashMap<>();
	private final Map<Integer, ItemContainer> containers = new HashMap<>();
	private final GroupStore store = new GroupStore();
	private final EventBus bus = new EventBus();

	private LocalCollector collector;
	private StorageWatcher watcher;
	private String memberId;

	/**
	 * @return a stand-in that answers the named methods, and gives 0, false or null for the rest
	 */
	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, Map<String, Function<Object[], Object>> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) ->
		{
			Function<Object[], Object> answer = answers.get(method.getName());
			if (answer != null)
			{
				return answer.apply(args);
			}
			Class<?> returns = method.getReturnType();
			if (returns == boolean.class)
			{
				return false;
			}
			if (returns == long.class)
			{
				return 0L;
			}
			if (returns == int.class)
			{
				return method.getName().equals("hashCode") ? System.identityHashCode(proxy) : 0;
			}
			return returns == String.class ? type.getSimpleName() : null;
		});
	}

	private static Widget widget(String text)
	{
		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getText", args -> text);
		return fake(Widget.class, answers);
	}

	private static ItemContainer container(Item... items)
	{
		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getItems", args -> items);
		return fake(ItemContainer.class, answers);
	}

	@Before
	public void logIn()
	{
		Map<String, Function<Object[], Object>> player = new HashMap<>();
		player.put("getName", args -> "Mundell");
		Player local = fake(Player.class, player);

		Map<String, Function<Object[], Object>> answers = new HashMap<>();
		answers.put("getGameState", args -> GameState.LOGGED_IN);
		answers.put("getAccountHash", args -> 12345L);
		answers.put("getLocalPlayer", args -> local);
		answers.put("getWidget", args -> args.length == 1 ? widgets.get(args[0]) : null);
		answers.put("getItemContainer", args -> containers.get(args[0]));
		Client client = fake(Client.class, answers);

		Map<String, Function<Object[], Object>> settings = new HashMap<>();
		settings.put("tileColor", args -> Color.WHITE);
		HomebaseConfig config = fake(HomebaseConfig.class, settings);

		Injector injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toInstance(client);
			binder.bind(Gson.class).toInstance(new Gson());
			binder.bind(HomebaseConfig.class).toInstance(config);
		});
		collector = injector.getInstance(LocalCollector.class);
		watcher = injector.getInstance(StorageWatcher.class);
		bus.register(collector);
		bus.register(watcher);

		collector.setEngine(new SyncEngine(store, System::currentTimeMillis, new Random(1)));
		collector.start();
		tick();
		tick();
		memberId = collector.getMemberId();
		assertNotNull(memberId);
	}

	private void tick()
	{
		bus.post(new GameTick());
	}

	/**
	 * Group storage opens, drawn from what it holds.
	 */
	private void open(Item... items)
	{
		widgets.put(InterfaceID.SharedBank.ITEMS, widget(""));
		containers.put(InventoryID.INV_GROUP_TEMP, container(items));
		bus.post(new ScriptPostFired(ScriptID.GROUP_IRONMAN_STORAGE_BUILD));
		tick();
	}

	/**
	 * Something goes in or comes out, which the game reports and then draws.
	 */
	private void change(Item... items)
	{
		ItemContainer now = container(items);
		containers.put(InventoryID.INV_GROUP_TEMP, now);
		bus.post(new ItemContainerChanged(InventoryID.INV_GROUP_TEMP, now));
		bus.post(new ScriptPostFired(ScriptID.GROUP_IRONMAN_STORAGE_BUILD));
		tick();
	}

	private void close()
	{
		widgets.remove(InterfaceID.SharedBank.ITEMS);
		containers.remove(InventoryID.INV_GROUP_TEMP);
	}

	private void saveWhileMessageShows()
	{
		widgets.put(InterfaceID.LoadingIconModal.TEXT, widget("Saving..."));
		tick();
		widgets.remove(InterfaceID.LoadingIconModal.TEXT);
	}

	private void waitTicks(int ticks)
	{
		for (int i = 0; i < ticks; i++)
		{
			tick();
		}
	}

	private List<StorageLogData.Entry> log()
	{
		StorageLogData log = new GroupView(store, new Gson()).get(memberId, Section.STORAGE_LOG, StorageLogData.class);
		return log == null ? null : log.getEntries();
	}

	private static void assertEntries(List<StorageLogData.Entry> entries, int... itemThenAmount)
	{
		assertEquals(itemThenAmount.length / 2, entries.size());
		for (int i = 0; i < entries.size(); i++)
		{
			assertEquals(itemThenAmount[2 * i], entries.get(i).getItem());
			assertEquals(itemThenAmount[2 * i + 1], entries.get(i).getAmount());
			assertTrue(entries.get(i).getAt() > 0);
		}
	}

	@Test
	public void closingWithoutChangingAnythingAddsNoEntry()
