package com.homebase.ui;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Item;
import net.runelite.client.util.AsyncBufferedImage;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ItemGridTest
{
	private static final int COLUMN_STEP = 37;
	private static final int ROW_STEP = 33;

	/**
	 * Counts what the grid asks for, with no game behind it.
	 */
	private static final class CountingSprites extends ItemSprites
	{
		final Set<Integer> pictureIds = new HashSet<>();
		final Set<Integer> namedIds = new HashSet<>();
		int loads;

		CountingSprites()
		{
			super(null, null);
		}

		@Override
		AsyncBufferedImage load(Item item)
		{
			loads++;
			pictureIds.add(item.getId());
			return new AsyncBufferedImage(null, 36, 32, BufferedImage.TYPE_INT_ARGB);
		}

		@Override
		void lookUpNames(Collection<Integer> itemIds, Runnable done)
		{
			namedIds.addAll(itemIds);
			done.run();
		}
	}

	private static List<Item> items(int count)
	{
		List<Item> items = new ArrayList<>();
		for (int id = 1; id <= count; id++)
		{
			items.add(new Item(id, 1));
		}
		return items;
	}

	private static void paint(ItemGrid.Tiles tiles, int clipY, int clipHeight)
	{
		Dimension size = tiles.getPreferredSize();
		BufferedImage canvas = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.setClip(0, clipY, size.width, clipHeight);
		tiles.paintComponent(g);
		g.dispose();
	}

	@Test
	public void aFullBankOnlyAsksForWhatsOnScreen()
	{
		CountingSprites sprites = new CountingSprites();
		ItemGrid.Tiles tiles = new ItemGrid.Tiles(items(1000), sprites, ItemGrid.NO_MARKS);

		// six rows' height of a bank, scrolled to the top
		paint(tiles, 0, 6 * ROW_STEP);
		assertTrue("asked for " + sprites.loads, sprites.loads <= 7 * 5);
		assertEquals(sprites.pictureIds, sprites.namedIds);

		// scrolling down asks for the new rows only
		int before = sprites.loads;
		paint(tiles, 0, 6 * ROW_STEP);
		assertEquals(before, sprites.loads);
		paint(tiles, 100 * ROW_STEP, 6 * ROW_STEP);
		assertTrue(sprites.pictureIds.contains(501));
		assertTrue(sprites.loads <= before + 7 * 5);
	}

	@Test
	public void refreshingThePanelDoesntReloadPictures()
	{
		CountingSprites sprites = new CountingSprites();
		paint(new ItemGrid.Tiles(items(50), sprites, ItemGrid.NO_MARKS), 0, 6 * ROW_STEP);
		int loaded = sprites.loads;

		// a rebuild makes a new grid over the same sprites
		paint(new ItemGrid.Tiles(items(50), sprites, ItemGrid.NO_MARKS), 0, 6 * ROW_STEP);
		assertEquals(loaded, sprites.loads);
	}

	@Test
	public void tilesKeepTheirSize()
	{
		ItemGrid.Tiles tiles = new ItemGrid.Tiles(items(7), new CountingSprites(), ItemGrid.NO_MARKS);
		assertEquals(new Dimension(1 + 5 * COLUMN_STEP, 1 + 2 * ROW_STEP), tiles.getPreferredSize());
		assertEquals(0, ItemGrid.rowsFor(0));
		assertEquals(1, ItemGrid.rowsFor(5));
		assertEquals(2, ItemGrid.rowsFor(6));
	}

	@Test
	public void findsTheItemUnderTheMouse()
	{
		assertEquals(0, ItemGrid.itemAt(1, 1, 7));
		assertEquals(4, ItemGrid.itemAt(1 + 4 * COLUMN_STEP, 1, 7));
		assertEquals(6, ItemGrid.itemAt(1 + COLUMN_STEP, 1 + ROW_STEP, 7));
		// an empty tile at the end of the last row, and the outer line
		assertEquals(-1, ItemGrid.itemAt(1 + 2 * COLUMN_STEP, 1 + ROW_STEP, 7));
		assertEquals(-1, ItemGrid.itemAt(0, 5, 7));
	}

	@Test
	public void tooltipsNameTheItemAndAmount()
	{
		List<Item> items = new ArrayList<>();
		items.add(new Item(4151, 1));
		items.add(new Item(995, 1200));
		ItemGrid.Tiles tiles = new ItemGrid.Tiles(items, new CountingSprites(), ItemGrid.NO_MARKS);

		assertEquals(ItemNames.get(4151), tiles.getToolTipText(mouseAt(tiles, 5, 5)));
		String stack = tiles.getToolTipText(mouseAt(tiles, 5 + COLUMN_STEP, 5));
		assertNotNull(stack);
		assertTrue(stack, stack.startsWith(ItemNames.get(995) + " ×"));
		assertNull(tiles.getToolTipText(mouseAt(tiles, 5 + 2 * COLUMN_STEP, 5)));
	}

	private static MouseEvent mouseAt(ItemGrid.Tiles tiles, int x, int y)
	{
		return new MouseEvent(tiles, MouseEvent.MOUSE_MOVED, 0, 0, x, y, 0, false);
	}

	@Test
	public void oneItemIsNotItems()
	{
		assertEquals("1 item", ItemGrid.itemCount(1));
		assertEquals("0 items", ItemGrid.itemCount(0));
		assertEquals("67 items", ItemGrid.itemCount(67));
	}
}

package com.homebase.ui;

import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ItemSearchTest
{
	private static final Map<Integer, String> NAMES = new HashMap<>();

	static
	{
		NAMES.put(1, "Rune scimitar");
		NAMES.put(2, "Rune scimitar");
		NAMES.put(3, "Scimitar of rune");
		NAMES.put(4, "Dragon scimitar");
		NAMES.put(5, "Rune");
		NAMES.put(6, "Prune");
	}

	private static List<ItemSearch.Result> find(String query, ItemSearch.Holding... holdings)
	{
		return ItemSearch.find(query, Arrays.asList(holdings), NAMES::get, 10);
	}

	private static ItemSearch.Holding held(String owner, String place, int itemId, int quantity)
	{
		return new ItemSearch.Holding(owner, place, itemId, quantity);
	}

	@Test
	public void addsUpTheSameItemAcrossPeopleAndPlaces()
	{
		// item 2 is the noted version of item 1
		List<ItemSearch.Result> results = find("rune sci",
			held("Mundell", "Bank", 1, 2),
			held("Mundell", "Worn", 1, 1),
			held("Bonscott", "Bank", 2, 10),
			held("Mundell", "Bank", 2, 5));

		assertEquals(1, results.size());
		ItemSearch.Result result = results.get(0);
		assertEquals("Rune scimitar", result.getName());
		assertEquals(18, result.getTotal());
		assertEquals(Long.valueOf(7), result.getOwners().get("Mundell").get("Bank"));
		assertEquals(Long.valueOf(1), result.getOwners().get("Mundell").get("Worn"));
		assertEquals(Long.valueOf(10), result.getOwners().get("Bonscott").get("Bank"));
	}

	@Test
	public void bestMatchesComeFirst()
	{
		List<ItemSearch.Result> results = find("rune",
			held("A", "Bank", 6, 1),
			held("A", "Bank", 3, 1),
			held("A", "Bank", 1, 1),
			held("A", "Bank", 5, 1));

		assertEquals("Rune", results.get(0).getName());
		assertEquals("Rune scimitar", results.get(1).getName());
		assertEquals("Scimitar of rune", results.get(2).getName());
		assertEquals("Prune", results.get(3).getName());
	}

	@Test
	public void ignoresCaseAndSpacesAndUnnamedItems()
	{
		assertEquals(1, find("  DRAGON ", held("A", "Bank", 4, 1)).size());
		assertTrue(find("   ", held("A", "Bank", 4, 1)).isEmpty());
		// a name that hasn't been looked up yet can't match
		assertTrue(find("item", held("A", "Bank", 99, 1)).isEmpty());
	}

	@Test
	public void stopsAtTheLimit()
	{
		List<ItemSearch.Result> results = ItemSearch.find("rune",
			Arrays.asList(held("A", "Bank", 1, 1), held("A", "Bank", 3, 1), held("A", "Bank", 5, 1)), NAMES::get, 2);
		assertEquals(2, results.size());
		assertEquals("Rune", results.get(0).getName());
	}

	@Test
	public void describesWhereSomeoneHasIt()
	{
		Map<String, Long> places = new LinkedHashMap<>();
		places.put("Bank", 1200L);
		places.put("Worn", 1L);
		assertEquals("Mundell: Bank 1,200, Worn 1", ItemSearchView.describe("Mundell", places));

		Map<String, Long> storage = new LinkedHashMap<>();
		storage.put("Group storage", 5L);
		assertEquals("Group storage: 5", ItemSearchView.describe("Group storage", storage));
	}
}

package com.homebase.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.homebase.storage.StorageHistory;
import org.junit.Test;

public class StorageHistoryViewTest
{
	private static final int WHIP = 4151;

	private static String line(int amount)
	{
		return StorageHistoryView.text(new StorageHistory.Line("Mundell", WHIP, amount, System.currentTimeMillis()));
	}

	@Test
	public void linesSayWhoDidWhatWithHowManyAndWhen()
	{
		String out = line(-5);
		assertTrue(out, out.contains("Mundell"));
		assertTrue(out, out.contains(" took out " + ItemNames.get(WHIP) + " ×5"));
		assertTrue(out, out.contains("just now"));

		String in = line(5);
		assertTrue(in, in.contains(" put in " + ItemNames.get(WHIP) + " ×5"));
	}

	@Test
	public void oneOfSomethingHasNoCount()
	{
		String out = line(-1);
		assertTrue(out, out.contains(ItemNames.get(WHIP)));
		assertFalse(out, out.contains("×"));
	}

	@Test
	public void owedLinesSayWhoHasHowMany()
	{
		String out = StorageHistoryView.text(new StorageHistory.Owed("Mundell", WHIP, 3, System.currentTimeMillis()));
		assertTrue(out, out.contains("Mundell"));
		assertTrue(out, out.contains(": " + ItemNames.get(WHIP) + " ×3"));
	}

	@Test
	public void namesCantAddFormatting()
	{
		String image = StorageHistoryView.text(new StorageHistory.Line("<img src='http://x'>", WHIP, 1, 1));
		assertFalse(image, image.contains("<img"));

		// shown as it was typed, not turned into an ampersand
		String entity = StorageHistoryView.text(new StorageHistory.Line("A&amp;B", WHIP, 1, 1));
		assertTrue(entity, entity.contains("A&amp;amp;B"));
	}

	@Test
	public void aMissingNameStillReads()
	{
		String out = StorageHistoryView.text(new StorageHistory.Owed("<>", WHIP, 1, 1));
		assertTrue(out, out.contains("Someone"));
	}
}

